INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21400, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "索取", "is_correct": true, "explanation": "索取：与“付出”相对，指向别人讨要或获取，与把东西给别人意思相反。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论：与“付出”既无反义关系，也无近义关系，词义不相关。"}, {"text": "欢迎", "is_correct": false, "explanation": "欢迎：与“付出”既无反义关系，也无近义关系，词义不相关。"}, {"text": "相信", "is_correct": false, "explanation": "相信：与“付出”既无反义关系，也无近义关系，词义不相关。"}], "correct_answer": "索取", "explanations": {"索取": "索取：与“付出”相对，指向别人讨要或获取，与把东西给别人意思相反。", "讨论": "讨论：与“付出”既无反义关系，也无近义关系，词义不相关。", "欢迎": "欢迎：与“付出”既无反义关系，也无近义关系，词义不相关。", "相信": "相信：与“付出”既无反义关系，也无近义关系，词义不相关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21400, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "索取", "is_correct": true, "explanation": "索取：与“付出”相对，指向别人讨要或获取，与把东西给别人意思相反。"}, {"text": "观察", "is_correct": false, "explanation": "观察：与“付出”既无反义关系，也无近义关系，词义不相关。"}, {"text": "生长", "is_correct": false, "explanation": "生长：与“付出”既无反义关系，也无近义关系，词义不相关。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：与“付出”既无反义关系，也无近义关系，词义不相关。"}], "correct_answer": "索取", "explanations": {"索取": "索取：与“付出”相对，指向别人讨要或获取，与把东西给别人意思相反。", "观察": "观察：与“付出”既无反义关系，也无近义关系，词义不相关。", "生长": "生长：与“付出”既无反义关系，也无近义关系，词义不相关。", "旅行": "旅行：与“付出”既无反义关系，也无近义关系，词义不相关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21400, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把自己有的东西给别人。", "primary_collocate": null, "pronunciation": "fù chū", "ipa": "fu˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "母亲为孩子付出了一切。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对朋友总是真心付出。", "target_word": "付出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她为家人付出了自己所有的爱。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好老师愿意为学生付出自己的时间。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爱一个人，就要为她付出真心。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷为这个家付出了一辈子。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只想付出，不想从别人那里得到什么。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "志愿者为陌生人付出自己的力量。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对他付出了全部的感情。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友有困难时，他总是先付出，不谈回报。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "付出了", "label": "体标"}, {"form": "付出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "付出|把自己拥有的东西给予别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3bd6d02-7b3a-476c-b3ee-298438b187a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21400, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "付出", "is_correct": true, "explanation": "付出（fù chū）：正确答案，指把自己拥有的东西给别人。"}, {"text": "付诸", "is_correct": false, "explanation": "zhū 与 chū 声母不同（zh/ch），意思是付诸（付诸实践），不是付出。"}, {"text": "浮出", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，意思是浮出（露出水面或显现出来）。"}, {"text": "步出", "is_correct": false, "explanation": "bù 与 fù 声母不同（b/f），意思是步出（走出某处）。"}, {"text": "副处", "is_correct": false, "explanation": "chù（第四声）与 chū（第一声）声调不同，意思是副处（副职的级别）。"}], "explanations": {"付出": "付出（fù chū）：正确答案，指把自己拥有的东西给别人。", "付诸": "zhū 与 chū 声母不同（zh/ch），意思是付诸（付诸实践），不是付出。", "浮出": "fú（第二声）与 fù（第四声）声调不同，意思是浮出（露出水面或显现出来）。", "步出": "bù 与 fù 声母不同（b/f），意思是步出（走出某处）。", "副处": "chù（第四声）与 chū（第一声）声调不同，意思是副处（副职的级别）。"}, "sentence_index": null, "correct_answer": "付出"}, "level_3": {"options": [{"text": "付出", "is_correct": true, "explanation": "付出：把爱和全部给予孩子，符合“母亲为孩子付出了一切”的语境。"}, {"text": "毕业", "is_correct": false, "explanation": "语法：“毕业”是不及物动词，不能带“一切”作宾语。"}, {"text": "睡觉", "is_correct": false, "explanation": "语法：“睡觉”不能带“一切”作宾语，句子不成立。"}, {"text": "散步", "is_correct": false, "explanation": "语法：“散步”不能带“一切”作宾语，句子不成立。"}], "explanations": {"付出": "付出：把爱和全部给予孩子，符合“母亲为孩子付出了一切”的语境。", "毕业": "语法：“毕业”是不及物动词，不能带“一切”作宾语。", "睡觉": "语法：“睡觉”不能带“一切”作宾语，句子不成立。", "散步": "语法：“散步”不能带“一切”作宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "付出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这道题上付出了一个严重的错误。", "explanation": "这里应该用〈犯〉。付出 指把自己有的东西给别人，“错误”不能拿来给人，说“犯错误”才自然。"}, {"text": "他付出了这份责任。", "explanation": "这里应该用〈承担〉。付出 指把自己有的东西给别人，“责任”要用〈承担〉，不能说“付出责任”。"}, {"text": "他付出了一个贫困的学生。", "explanation": "这里应该用〈资助〉。付出 的宾语是东西，不能说“付出了一个学生”，资助 可以直接带受助的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21400, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付出", "is_correct": true, "explanation": "付出：把自己的东西给别人，符合“他只想付出，不想从别人那里得到什么”的语境。"}, {"text": "攀比", "is_correct": false, "explanation": "语义：“攀比”是与人比较高低，不是给予别人，与“不想从别人那里得到什么”不相符。"}, {"text": "挥霍", "is_correct": false, "explanation": "语义：“挥霍”是浪费钱财，与句中“只想给予、不想获取”的意思不符。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：“嫉妒”是因别人而不满，与句中“只想给予”的意愿矛盾。"}], "explanations": {"付出": "付出：把自己的东西给别人，符合“他只想付出，不想从别人那里得到什么”的语境。", "攀比": "语义：“攀比”是与人比较高低，不是给予别人，与“不想从别人那里得到什么”不相符。", "挥霍": "语义：“挥霍”是浪费钱财，与句中“只想给予、不想获取”的意思不符。", "嫉妒": "语义：“嫉妒”是因别人而不满，与句中“只想给予”的意愿矛盾。"}, "sentence_index": 6, "correct_answer": "付出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她向我付出了一个问题。", "explanation": "这里应该用〈提出〉。付出 指把自己有的东西给别人，“问题”是要提出来的，不能说“付出一个问题”。"}, {"text": "她把一本书付出到桌子上。", "explanation": "这里应该用〈放〉。“付出”是把自己的东西给别人，不能表示把东西放到某处。"}, {"text": "他从书中付出了很多知识。", "explanation": "这里应该用〈获取〉。付出 指把自己的东西给出去，不能用来说“从书中得到知识”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她明天将为孩子付出了很多时间。", "corrected_sentence": "她明天将为孩子付出很多时间。", "error_description": "体标错误：“明天将”表示将来要做的事，不能用表示完成的“了”，应说“将为孩子付出很多时间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她对这个家庭付出了过很多爱。", "corrected_sentence": "她对这个家庭付出过很多爱。", "error_description": "错误：“付出了过”同时用了“了”和“过”。表示曾经有过的付出只用“付出过”，“了过”不能连用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
