INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21404, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "买东西要付的钱。", "primary_collocate": null, "pronunciation": "jià gé", "ipa": "tɕia˥˩ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这件衣服的价格太高了。", "target_word": "价格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西以前，我先看价格。", "target_word": "价格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家店的价格不一样。", "target_word": "价格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的水果价格很便宜。", "target_word": "价格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能告诉我这个手机的价格吗？", "target_word": "价格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，菜的价格会变贵。", "target_word": "价格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这个价格很合适，就买了。", "target_word": "价格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格写在盒子的后面。", "target_word": "价格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的价格比商店里低。", "target_word": "价格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问了老板香蕉的价格。", "target_word": "价格", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "价格战", "label": "复合"}, {"form": "价格表", "label": "复合"}], "register": "中性", "sense_fingerprint": "商品买卖时要付的钱数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4208b8-fa3e-439a-94ca-4737d9934ac5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价格", "is_correct": true, "explanation": "正确。“这件衣服的价格太高了”指价钱高，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用“高”来形容，“太高了”不能修饰颜色。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道可以浓淡，但不能说“太高了”。"}, {"text": "材料", "is_correct": false, "explanation": "搭配：“高”不能修饰材料，材料一般说好或差。"}], "explanations": {"价格": "正确。“这件衣服的价格太高了”指价钱高，符合句意。", "颜色": "语义：颜色不能用“高”来形容，“太高了”不能修饰颜色。", "味道": "语义：味道可以浓淡，但不能说“太高了”。", "材料": "搭配：“高”不能修饰材料，材料一般说好或差。"}, "sentence_index": 0, "correct_answer": "价格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身上的价格只剩几块了。", "explanation": "这里应该用〈钱〉。身上带的钱要说“钱”，“价格”指商品的标价。"}, {"text": "他每个月的价格是五千块。", "explanation": "这里应该用〈工资〉。每个月拿到的劳动报酬是工资，价格指买卖商品的钱。"}, {"text": "这家店这个月赚的价格很高。", "explanation": "这里应该用〈利润〉。店铺赚到的钱要说“利润”，“价格”指商品的标价，不能说“赚的价格”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不能被买，“就买了”的对象不能是天气。"}, {"text": "价格", "is_correct": true, "explanation": "正确。“这个价格很合适，就买了”指价钱合适，所以买了。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“买”的对象不能是年龄。"}, {"text": "距离", "is_correct": false, "explanation": "语义：距离不能被买，句子无法成立。"}], "explanations": {"天气": "语义：天气不能被买，“就买了”的对象不能是天气。", "价格": "正确。“这个价格很合适，就买了”指价钱合适，所以买了。", "年龄": "搭配：“买”的对象不能是年龄。", "距离": "语义：距离不能被买，句子无法成立。"}, "sentence_index": 6, "correct_answer": "价格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "银行存款的价格比去年高了不少。", "explanation": "这里应该用〈利息〉。存进银行的钱产生的收益叫利息，价格指买卖商品的标价，不能用来说存款的收益。"}, {"text": "他年底拿到了一大笔价格。", "explanation": "这里应该用〈奖金〉。年底额外发的钱是奖金，不能说“拿到一大笔价格”。"}, {"text": "租房的时候要交一笔价格。", "explanation": "这里应该用〈押金〉。租房时交的担保钱是押金，价格是买卖商品的标价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种菜的价格涨价了。", "corrected_sentence": "这种菜的价格上涨了。", "error_description": "错误形式：“价格涨价了”；正确形式：“价格上涨了”。“涨价”本身已包含价格上升的意思，与“价格”同用会重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板给了我一个很低价格。", "corrected_sentence": "老板给了我一个很低的价格。", "error_description": "错误形式：“很低价格”；正确形式：“很低的价格”。修饰名词的形容词词组后面要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4afb8475-7b77-42ed-ba27-21c1484e7e27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
