INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21408, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天上的雨、雪、风、太阳等大气状况，都叫做天气。", "primary_collocate": null, "pronunciation": "tiān qì", "ipa": "tʰjɛn˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "今天天气很好，我们去公园玩吧。", "target_word": "天气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天的天气怎么样？", "target_word": "天气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天气太冷，他穿了一件厚衣服。", "target_word": "天气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每天早上都看天气，再决定穿什么。", "target_word": "天气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里夏天的天气又热又湿。", "target_word": "天气", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天气变冷了，你要多穿点儿衣服。", "target_word": "天气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为天气不好，飞机晚点了两个小时。", "target_word": "天气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢春天的天气，不冷也不热。", "target_word": "天气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京的天气和上海的不一样。", "target_word": "天气", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气晴朗，很多人在海边游泳。", "target_word": "天气", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "天气预报", "label": "复合"}, {"form": "天气图", "label": "复合"}], "register": "中性", "sense_fingerprint": "某地某时冷热、晴雨、风雪等大气状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7679ce6-7410-49f6-bfdd-e5891d0d533a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21408, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天气", "is_correct": true, "explanation": "天气：天上的雨、雪、风、太阳等大气状况。"}, {"text": "田契", "is_correct": false, "explanation": "tiān（第一声）与 tián（第二声）声调不同，qì 相同，意思是土地的契约。"}, {"text": "天际", "is_correct": false, "explanation": "qì（第四声）与 jì（第四声）声母不同（q 与 j），意思是天边。"}, {"text": "田七", "is_correct": false, "explanation": "tiān（第一声）与 tián（第二声）、qì（第四声）与 qī（第一声）声调都不同，意思是一种草药。"}], "explanations": {"天气": "天气：天上的雨、雪、风、太阳等大气状况。", "田契": "tiān（第一声）与 tián（第二声）声调不同，qì 相同，意思是土地的契约。", "天际": "qì（第四声）与 jì（第四声）声母不同（q 与 j），意思是天边。", "田七": "tiān（第一声）与 tián（第二声）、qì（第四声）与 qī（第一声）声调都不同，意思是一种草药。"}, "sentence_index": null, "correct_answer": "天气"}, "level_3": {"options": [{"text": "天气", "is_correct": true, "explanation": "天气：天上的雨、雪、风、太阳等状况，与“很好”相合。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来说今天的状况。"}, {"text": "墙", "is_correct": false, "explanation": "语义：“墙”是建筑物，没有“好”或“不好”的天气状况。"}, {"text": "地震", "is_correct": false, "explanation": "语义：“地震”是灾害，不能用“很好”来形容。"}], "explanations": {"天气": "天气：天上的雨、雪、风、太阳等状况，与“很好”相合。", "身材": "体貌：“身材”指人的体形，不能用来说今天的状况。", "墙": "语义：“墙”是建筑物，没有“好”或“不好”的天气状况。", "地震": "语义：“地震”是灾害，不能用“很好”来形容。"}, "sentence_index": 0, "correct_answer": "天气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的天气很好听。", "explanation": "这里应该用〈声音〉。天气指晴雨、风雪等整体状况，歌曲好听说的是声音，不能说天气好听。"}, {"text": "这碗汤的天气很咸。", "explanation": "这里应该用〈味道〉。“咸”形容味道，天气不能说咸；汤的咸淡要说味道，如“这碗汤的味道很咸”。"}, {"text": "这朵花的天气很香。", "explanation": "这里应该用〈气味〉。“香”形容气味，天气不能说香。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21408, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "天气", "is_correct": true, "explanation": "天气：天上的雨、雪、风、太阳等大气状况。"}, {"text": "田畦", "is_correct": false, "explanation": "tiān（第一声）与 tián（第二声）、qì（第四声）与 qí（第二声）声调不同，意思是田里分成的小块。"}, {"text": "田七", "is_correct": false, "explanation": "tiān（第一声）与 tián（第二声）、qì（第四声）与 qī（第一声）声调都不同，意思是一种草药。"}, {"text": "天启", "is_correct": false, "explanation": "qì（第四声）与 qǐ（第三声）声调不同，意思是上天的启示。"}], "explanations": {"天气": "天气：天上的雨、雪、风、太阳等大气状况。", "田畦": "tiān（第一声）与 tián（第二声）、qì（第四声）与 qí（第二声）声调不同，意思是田里分成的小块。", "田七": "tiān（第一声）与 tián（第二声）、qì（第四声）与 qī（第一声）声调都不同，意思是一种草药。", "天启": "qì（第四声）与 qǐ（第三声）声调不同，意思是上天的启示。"}, "sentence_index": null, "correct_answer": "天气"}, "level_3": {"options": [{"text": "天气", "is_correct": true, "explanation": "天气：天上的雨、雪、风、太阳等状况，不好会导致航班晚点。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字与飞机晚点没有因果关系，句中的原因应是天气。"}, {"text": "风景", "is_correct": false, "explanation": "语义：风景的好坏不会让飞机晚点，句中说的是天气原因。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身材，不能用来说飞机晚点的原因。"}], "explanations": {"天气": "天气：天上的雨、雪、风、太阳等状况，不好会导致航班晚点。", "名字": "语义：名字与飞机晚点没有因果关系，句中的原因应是天气。", "风景": "语义：风景的好坏不会让飞机晚点，句中说的是天气原因。", "身高": "体貌：“身高”指人的身材，不能用来说飞机晚点的原因。"}, "sentence_index": 6, "correct_answer": "天气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的天气很便宜。", "explanation": "这里应该用〈价格〉。天气指晴雨、风雪等整体状况，商品便宜说的是价格，不能说天气便宜。"}, {"text": "这个箱子的天气很重。", "explanation": "这里应该用〈重量〉。天气指整体气象状况，箱子轻重要说重量。"}, {"text": "这条河的天气很深。", "explanation": "这里应该用〈水〉。天气指晴雨、风雪等状况，河深说的是水，应说“这条河的水很深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天的天气很晴天，适合出门。", "corrected_sentence": "今天的天气很晴朗，适合出门。", "error_description": "“天气”的谓语要用形容词“晴朗”，“晴天”是名词，不能说“天气很晴天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块天气很少见。", "corrected_sentence": "这种天气很少见。", "error_description": "“天气”的量词应用“种”，“块”用于块状物，不能用来数天气。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
