INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21412, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21412, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示程度最高，没有比它更厉害的了。", "primary_collocate": null, "pronunciation": "zuì wéi", "ipa": "tsweɪ˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这座城市的夏天最为舒服。", "target_word": "最为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我的朋友中，他最为聪明。", "target_word": "最为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事对我来说最为重要。", "target_word": "最为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天是这里最为美丽的季节。", "target_word": "最为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师最为关心的是学生的健康。", "target_word": "最为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的鱼最为有名。", "target_word": "最为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路上，早上最为热闹。", "target_word": "最为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我们班最为努力的学生。", "target_word": "最为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话让我最为感动。", "target_word": "最为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法最为简单，也最为有用。", "target_word": "最为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "最為", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "程度副词，用在双音节形容词或动词前，表示程度最高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b72803e1-d339-466f-98b7-61dea376201f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最为", "is_correct": true, "explanation": "最为：表示程度最高，与“夏天最为舒服”的句意相符。"}, {"text": "吗", "is_correct": false, "explanation": "语法：“吗”是疑问语气词，不能放在“夏天”与“舒服”之间，句子不成立。"}, {"text": "了", "is_correct": false, "explanation": "语法：“了”是体标词，不能放在“夏天”与“舒服”之间，句子不成立。"}, {"text": "的", "is_correct": false, "explanation": "语法：“的”是结构助词，不能充当副词，“夏天的舒服”句子不成立。"}], "explanations": {"最为": "最为：表示程度最高，与“夏天最为舒服”的句意相符。", "吗": "语法：“吗”是疑问语气词，不能放在“夏天”与“舒服”之间，句子不成立。", "了": "语法：“了”是体标词，不能放在“夏天”与“舒服”之间，句子不成立。", "的": "语法：“的”是结构助词，不能充当副词，“夏天的舒服”句子不成立。"}, "sentence_index": 0, "correct_answer": "最为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是我最为好的朋友。", "explanation": "这里应该用〈最〉。“最为”要修饰双音节形容词或动词，“好”是单音节，只能说“最好”。"}, {"text": "今天比昨天最为暖和。", "explanation": "这里应该用〈更〉。“最为”表示程度最高，不能用在“比”字句中，比较时应用〈更〉。"}, {"text": "我最为爱这座城市。", "explanation": "这里应该用〈最〉。“最为”要修饰双音节形容词或动词，“爱”是单音节，应说“最爱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最为", "is_correct": true, "explanation": "最为：表示程度最高，与“早上最为热闹”的句意相符。"}, {"text": "连夜", "is_correct": false, "explanation": "语义：“连夜”指整夜不停，与句中的“早上”冲突，早上不能说“连夜”。"}, {"text": "彻夜", "is_correct": false, "explanation": "语义：“彻夜”指整个夜晚，与“早上”的时间不符，句意无法成立。"}, {"text": "通宵", "is_correct": false, "explanation": "搭配：“通宵”多修饰持续进行的动作，不能用来修饰“热闹”这类状态。"}], "explanations": {"最为": "最为：表示程度最高，与“早上最为热闹”的句意相符。", "连夜": "语义：“连夜”指整夜不停，与句中的“早上”冲突，早上不能说“连夜”。", "彻夜": "语义：“彻夜”指整个夜晚，与“早上”的时间不符，句意无法成立。", "通宵": "搭配：“通宵”多修饰持续进行的动作，不能用来修饰“热闹”这类状态。"}, "sentence_index": 6, "correct_answer": "最为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个办法最为好，也很有用。", "explanation": "这里应该用〈十分〉。“最为”要修饰双音节形容词或动词，“好”是单音节，不能这样用。"}, {"text": "他比以前最为自信。", "explanation": "这里应该用〈更〉。“最为”表示程度最高，不能用在“比”字句中，比较时应用〈更〉。"}, {"text": "我最为怕冷，冬天总穿厚衣服。", "explanation": "这里应该用〈非常〉。“最为”要修饰双音节动词，“怕”是单音节，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的成绩最为的突出。", "corrected_sentence": "他的成绩最为突出。", "error_description": "错误形式：“最为的突出”。正确形式：“最为突出”。“最为”是副词，后面应直接接形容词，不能在“最为”后加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题最为重。", "corrected_sentence": "这个问题最为重要。", "error_description": "错误形式：“最为重”。正确形式：“最为重要”。“最为”后面要接双音节形容词或动词，不能直接接单音节的“重”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
