INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "体系就是很多部分一起组成的一个大整体。", "primary_collocate": null, "pronunciation": "tǐ xì", "ipa": "tʰi˨˩ ɕi˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家有完整的教育体系。", "target_word": "体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学语言要有自己的知识体系。", "target_word": "体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司建立了新的管理体系。", "target_word": "体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套体系包括三个部分。", "target_word": "体系", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医疗体系需要更多医生。", "target_word": "体系", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他正在建立自己的学习体系。", "target_word": "体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汉语的语音体系并不难学。", "target_word": "体系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个城市都有自己的交通体系。", "target_word": "体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个体系已经用了二十年。", "target_word": "体系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师帮我们整理出一个清楚的体系。", "target_word": "体系", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个体系", "label": "量词"}, {"form": "一套体系", "label": "量词"}, {"form": "教育体系", "label": "复合"}, {"form": "知识体系", "label": "复合"}], "register": "书面", "sense_fingerprint": "名词：由许多相关部分组成的有条理的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebfe7736-19f5-4660-8550-caa3fb9fd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体系", "is_correct": true, "explanation": "体系：名词，指许多部分组成的有条理的整体，与“完整的教育”搭配，句子通顺。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：“西瓜”是水果，不能作为“完整的教育”的组成部分，句子不通。"}, {"text": "旅馆", "is_correct": false, "explanation": "搭配：“教育旅馆”搭配不通，句子不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是通讯工具，不能用于描述“完整的教育”，句子不通。"}], "explanations": {"体系": "体系：名词，指许多部分组成的有条理的整体，与“完整的教育”搭配，句子通顺。", "西瓜": "语义：“西瓜”是水果，不能作为“完整的教育”的组成部分，句子不通。", "旅馆": "搭配：“教育旅馆”搭配不通，句子不通。", "手机": "语义：“手机”是通讯工具，不能用于描述“完整的教育”，句子不通。"}, "sentence_index": 0, "correct_answer": "体系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯咖啡的体系很香。", "explanation": "这里应该用〈香气〉。“体系”指很多部分组成的抽象整体，不用来形容饮品的气味，应说“香气”。"}, {"text": "这个歌手的体系很好听。", "explanation": "这里应该用〈声音〉。“体系”指很多部分组成的大整体，如理论、制度，不能用来形容声音。"}, {"text": "这件衣服的体系很漂亮。", "explanation": "这里应该用〈款式〉。衣服的样式应说“款式”，“体系”不用于形容衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体系", "is_correct": true, "explanation": "体系：名词，指语音的整体结构，与“语音”搭配，句子通顺。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不是语音的组成部分，句子不通。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“语音饭店”搭配不通，句子不通。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：“苹果”与“语音”无关，句子不通。"}], "explanations": {"体系": "体系：名词，指语音的整体结构，与“语音”搭配，句子通顺。", "房子": "语义：“房子”不是语音的组成部分，句子不通。", "饭店": "搭配：“语音饭店”搭配不通，句子不通。", "苹果": "语义：“苹果”与“语音”无关，句子不通。"}, "sentence_index": 6, "correct_answer": "体系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天体系不舒服，想早点休息。", "explanation": "这里应该用〈身体〉。“体系”指许多部分组成的有条理的整体，不指人的身体。"}, {"text": "这碗汤的体系有点咸。", "explanation": "这里应该用〈味道〉。“体系”是抽象的整体结构，不能用来说食物的咸淡。"}, {"text": "他每天晚上都写体系，记录一天的生活。", "explanation": "这里应该用〈日记〉。“体系”指由很多部分组成的整体，不是用来写的生活记录。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校建立了一只新的评价体系。", "corrected_sentence": "学校建立了一套新的评价体系。", "error_description": "“体系”的量词应为“套”或“个”，不能用“只”（“只”用于动物或成对物件中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所大学有一幅完整的评价体系。", "corrected_sentence": "这所大学有一套完整的评价体系。", "error_description": "“体系”的量词应为“套”或“个”，不能用“幅”（“幅”用于画、布等平面的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
