INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21416, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "当作，比如“作为学生”就是“当学生”的意思。", "primary_collocate": null, "pronunciation": "zuò wéi", "ipa": "tswo˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "作为学生，我们要认真学习。", "target_word": "作为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作为老师，她对每个学生都很好。", "target_word": "作为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作为朋友，我想告诉你一件事。", "target_word": "作为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作为中国人，我们很爱自己的国家。", "target_word": "作为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作为经理，他每天都很忙。", "target_word": "作为", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "作为妈妈，她总是把孩子放在第一位。", "target_word": "作为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为一个医生，他见过很多病人。", "target_word": "作为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为队长，他要照顾每个队员。", "target_word": "作为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作为客人，你不用做饭。", "target_word": "作为", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "作为班长，他每天都很早到学校。", "target_word": "作为", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "介词，表示以某种身份或资格，如“作为学生”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7679ce6-7410-49f6-bfdd-e5891d0d533a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21416, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "作为", "is_correct": true, "explanation": "作为（zuò wéi）即本题词，表示以某种身份或资格。"}, {"text": "座位", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是座位，不是“作为”。"}, {"text": "作文", "is_correct": false, "explanation": "wén 与 wéi 韵母不同（-en／-ei），意思是写文章。"}, {"text": "做完", "is_correct": false, "explanation": "wán 与 wéi 韵母不同（-an／-ei），意思是做完、完成。"}, {"text": "最为", "is_correct": false, "explanation": "zuì 与 zuò 韵母不同（-ui／-uo），最为的意思是最。"}], "explanations": {"作为": "作为（zuò wéi）即本题词，表示以某种身份或资格。", "座位": "wèi（第四声）与 wéi（第二声）声调不同，意思是座位，不是“作为”。", "作文": "wén 与 wéi 韵母不同（-en／-ei），意思是写文章。", "做完": "wán 与 wéi 韵母不同（-an／-ei），意思是做完、完成。", "最为": "zuì 与 zuò 韵母不同（-ui／-uo），最为的意思是最。"}, "sentence_index": null, "correct_answer": "作为"}, "level_3": {"options": [{"text": "作为", "is_correct": true, "explanation": "作为：表示以“学生”这一身份，与句意相符。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：“按照”后要接标准、规定，不能接“学生”这样的身份。"}, {"text": "凭借", "is_correct": false, "explanation": "语义：“凭借”表示依靠某种条件或能力，与身份不合，句子说不通。"}, {"text": "通过", "is_correct": false, "explanation": "语义：“通过”表示经由某种途径，不能引出身份，“通过学生”说不通。"}], "explanations": {"作为": "作为：表示以“学生”这一身份，与句意相符。", "按照": "搭配：“按照”后要接标准、规定，不能接“学生”这样的身份。", "凭借": "语义：“凭借”表示依靠某种条件或能力，与身份不合，句子说不通。", "通过": "语义：“通过”表示经由某种途径，不能引出身份，“通过学生”说不通。"}, "sentence_index": 0, "correct_answer": "作为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作为这件事，我很担心。", "explanation": "这里应该用〈对于〉。作为表示身份或资格，引出话题要用“对于”，如“对于这件事，我很担心”。"}, {"text": "他作为大家服务，每天都很辛苦。", "explanation": "这里应该用〈为〉。作为表示身份，不能引出服务的对象，“为大家服务”才对。"}, {"text": "作为考试，他每天复习。", "explanation": "这里应该用〈为了〉。作为表示身份或资格，不能引出目的，“为了考试”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为了", "is_correct": false, "explanation": "语义：“为了”引出目的，不能接“一个医生”这样的身份，句子说不通。"}, {"text": "用", "is_correct": false, "explanation": "配价：“用”后要接工具或手段，不能直接接身份人物，句子说不通。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示方向或对象，与“见过很多病人”的句意不符。"}, {"text": "作为", "is_correct": true, "explanation": "作为：表示以“医生”这一身份，与句意相符。"}], "explanations": {"为了": "语义：“为了”引出目的，不能接“一个医生”这样的身份，句子说不通。", "用": "配价：“用”后要接工具或手段，不能直接接身份人物，句子说不通。", "向": "语义：“向”表示方向或对象，与“见过很多病人”的句意不符。", "作为": "作为：表示以“医生”这一身份，与句意相符。"}, "sentence_index": 6, "correct_answer": "作为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作为健康，我每天早上都去跑步。", "explanation": "这里应该用〈为了〉。作为表示身份或资格，不能引出目的，“为了健康”才对。"}, {"text": "作为大雨，我们没有出去。", "explanation": "这里应该用〈因为〉。作为表示身份，不能引出原因，“因为大雨”才对。"}, {"text": "作为努力，他考上了大学。", "explanation": "这里应该用〈依靠〉。作为表示身份，不能表示凭借的手段，“依靠努力”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我作为了班长，要帮助同学们。", "corrected_sentence": "我作为班长，要帮助同学们。", "error_description": "错误：“作为”是介词，后面不能加“了”，应说“我作为班长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她作为的护士，每天要照顾病人。", "corrected_sentence": "她作为护士，每天要照顾病人。", "error_description": "错误：“作为”后面不能加“的”，应说“她作为护士”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
