INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21418, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个国家或地区的生产、流通、消费等经济活动的整体情况。", "primary_collocate": null, "pronunciation": "jīng jì", "ipa": "tɕiŋ˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家的经济发展得很快。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥很关心经济。", "target_word": "经济", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年的经济比去年好。", "target_word": "经济", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经济好了，大家的钱也多了。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的经济靠旅游。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场大雨影响了经济，很多店都关门了。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济不好的时候，找工作很难。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在世界经济有一些问题。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸每天看报纸，关心国家的经济。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的路让小城的经济变得更好了。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "经济学", "label": "复合"}, {"form": "经济体", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：一个地方生产、赚钱、买卖的整体情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ebcdd33-4c2b-4870-aa27-7ac3753dba86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21418, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "竞技", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，竞技指体育比赛中的较量。"}, {"text": "京剧", "is_correct": false, "explanation": "jù（ü）与 jì（i）韵母不同，京剧是一种传统戏曲。"}, {"text": "精细", "is_correct": false, "explanation": "xì 与 jì 声母不同，精细指非常细致。"}, {"text": "经济", "is_correct": true, "explanation": "正确答案，指国家或地区的整体生产、流通和消费情况。"}], "explanations": {"竞技": "jìng（第四声）与 jīng（第一声）声调不同，竞技指体育比赛中的较量。", "京剧": "jù（ü）与 jì（i）韵母不同，京剧是一种传统戏曲。", "精细": "xì 与 jì 声母不同，精细指非常细致。", "经济": "正确答案，指国家或地区的整体生产、流通和消费情况。"}, "sentence_index": null, "correct_answer": "经济"}, "level_3": {"options": [{"text": "经济", "is_correct": true, "explanation": "正确答案。国家的生产、流通和消费等整体情况可以发展。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的身材特征，不能说“发展得很快”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会发展，句子说的是国家的整体情况。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的功课，不能说国家的作业发展得很快。"}], "explanations": {"经济": "正确答案。国家的生产、流通和消费等整体情况可以发展。", "身高": "体貌：身高是人的身材特征，不能说“发展得很快”。", "颜色": "语义：颜色不会发展，句子说的是国家的整体情况。", "作业": "语义：作业是学生的功课，不能说国家的作业发展得很快。"}, "sentence_index": 0, "correct_answer": "经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每个月的经济很多。", "explanation": "这里应该用〈收入〉。经济指整体经济情况，不能用来说个人每月进账的多少。"}, {"text": "公司需要更多经济。", "explanation": "这里应该用〈资金〉。经济指整体经济情况，不能指公司投入的钱。"}, {"text": "这个家族拥有很多经济。", "explanation": "这里应该用〈财富〉。经济指整体经济情况，不是可以数量多少的财产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经济", "is_correct": true, "explanation": "正确答案。句子说的是国家或地区整体经济状况不好。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子的好坏与找工作难不难无关，句子说的是整体状况。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“不好”一般说状况或质量，不说学费不好。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能决定找工作难不难，这一说法没有意义。"}], "explanations": {"经济": "正确答案。句子说的是国家或地区整体经济状况不好。", "房子": "语义：房子的好坏与找工作难不难无关，句子说的是整体状况。", "学费": "搭配：“不好”一般说状况或质量，不说学费不好。", "桌子": "语义：桌子不能决定找工作难不难，这一说法没有意义。"}, "sentence_index": 6, "correct_answer": "经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行的经济很高。", "explanation": "这里应该用〈费用〉。经济指整体经济情况，不能用来说某次开支的多少。"}, {"text": "这批货物的经济很多。", "explanation": "这里应该用〈数量〉。经济指整体经济情况，不能用来说货物的多少。"}, {"text": "这次考试的经济很好。", "explanation": "这里应该用〈成绩〉。经济指整体经济情况，不能用来说考试的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要长大经济。", "corrected_sentence": "我们要发展经济。", "error_description": "错误：“长大经济”。正确：“发展经济”。“长大”不能带宾语，让经济变好要说“发展经济”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年经济得很好。", "corrected_sentence": "这几年经济很好。", "error_description": "错误：“经济得很好”。正确：“经济很好”。“经济”后面不加“得”，程度副词“很”直接修饰形容词即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21420, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21420, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "商品从一个地方卖到另一个地方，或者从一个人手里交给另一个人。", "primary_collocate": null, "pronunciation": "shāng pǐn liú tōng", "ipa": "ʂɑŋ˥ pʰin˨˩ ljoʊ˧˥ tʰʊŋ˥", "syllable_count": 4, "sentences": [{"text": "铁路修好后，山区的商品流通快多了。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春节前，市场上的商品流通特别活跃。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商品流通不畅，农民的水果卖不出去。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河是两省商品流通的主要通道。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候，丝绸之路促进了东西方的商品流通。", "target_word": "商品流通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪封路，城里的商品流通暂时停了。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了快递，农村和城市之间的商品流通方便了。", "target_word": "商品流通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "批发市场对商品流通很重要。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小店老板说，节日里商品流通最快。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了新公路，两个小镇的商品流通快了。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "商品", "label": "复合"}, {"form": "流通", "label": "复合"}], "register": "中性", "sense_fingerprint": "商品在地区之间或人与人之间的买卖流动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b00e750-9992-41a7-9c7a-85867ab1d091') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商品流通", "is_correct": true, "explanation": "商品流通指商品的流转，与“铁路修好后，山区的……快多了”相合。"}, {"text": "历史文化", "is_correct": false, "explanation": "语义：历史文化不会因铁路修好而“快多了”。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“快多了”一般不修饰“眼镜”。"}, {"text": "戏剧", "is_correct": false, "explanation": "语义：戏剧与铁路修好后的变化无关。"}], "explanations": {"商品流通": "商品流通指商品的流转，与“铁路修好后，山区的……快多了”相合。", "历史文化": "语义：历史文化不会因铁路修好而“快多了”。", "眼镜": "搭配：“快多了”一般不修饰“眼镜”。", "戏剧": "语义：戏剧与铁路修好后的变化无关。"}, "sentence_index": 0, "correct_answer": "商品流通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在市场上商品流通水果。", "explanation": "这里应该用〈卖〉。商品流通是名词，表示流转过程，不能当动词带宾语。"}, {"text": "工人们商品流通了二十箱货。", "explanation": "这里应该用〈搬运〉。商品流通不是表示搬运动作的动词，不能用来说搬货。"}, {"text": "我和妈妈在商店里商品流通了一个下午。", "explanation": "这里应该用〈逛街〉。商品流通是名词，指商品的流转，不能表示人逛商店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商品流通", "is_correct": true, "explanation": "商品流通指商品的流转，与“有了快递，农村和城市之间的……方便了”相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不会因快递而“方便”。"}, {"text": "农药", "is_correct": false, "explanation": "搭配：“方便”不修饰“农药”。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言与快递带来的便利无关。"}], "explanations": {"商品流通": "商品流通指商品的流转，与“有了快递，农村和城市之间的……方便了”相合。", "天气": "语义：天气不会因快递而“方便”。", "农药": "搭配：“方便”不修饰“农药”。", "方言": "语义：方言与快递带来的便利无关。"}, "sentence_index": 6, "correct_answer": "商品流通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河水在地下商品流通。", "explanation": "这里应该用〈流动〉。商品流通专指商品的流转，不能用于水的流动。"}, {"text": "公司商品流通了三名员工。", "explanation": "这里应该用〈调动〉。商品流通只指商品的流转，不能用于人员的调配。"}, {"text": "她每天早上在公园里商品流通半小时。", "explanation": "这里应该用〈跑步〉。商品流通指商品的流转，不能表示人的运动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春节期间，这座城市的商品流通了很活跃。", "corrected_sentence": "春节期间，这座城市的商品流通很活跃。", "error_description": "“商品流通”后不能直接加“了”接形容词谓语；应说“商品流通很活跃”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两省之间的商品流通很频繁着。", "corrected_sentence": "两省之间的商品流通很频繁。", "error_description": "“很频繁”是形容词谓语，后面不能加“着”；应说“两省之间的商品流通很频繁”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
