INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21424, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21424, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "交易量就是买卖东西的数量。", "primary_collocate": null, "pronunciation": "jiāo yì liàng", "ipa": "tɕjɑʊ˥ i˥˩ ljɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "周末集市上的交易量最大。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天下雨，水果摊的交易量不高。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快过年了，市场的交易量一天比一天大。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想知道这个月的交易量是多少。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小店的交易量不大，老板只赚一点钱。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上的交易量一年比一年多。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "价格便宜以后，交易量马上变大了。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的交易量比上个月少了一些。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老李每天都看看当天的交易量。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买东西的人多了，交易量就上去了。", "target_word": "交易量", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "交易", "label": "复合"}, {"form": "交易额", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常买卖东西的多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b00e750-9992-41a7-9c7a-85867ab1d091') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指生存的时长，与买卖东西的数量无关。"}, {"text": "交易量", "is_correct": true, "explanation": "交易量指买卖东西的数量，这里说周末集市上的数量居首，与“最大”搭配。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人，不能用来描述集市。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或动物，不能修饰集市。"}], "explanations": {"年龄": "语义：“年龄”指生存的时长，与买卖东西的数量无关。", "交易量": "交易量指买卖东西的数量，这里说周末集市上的数量居首，与“最大”搭配。", "身高": "搭配：“身高”只用于人，不能用来描述集市。", "体重": "搭配：“体重”只用于人或动物，不能修饰集市。"}, "sentence_index": 0, "correct_answer": "交易量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想知道这个月的交易量叫什么名字。", "explanation": "这里应该用〈商品〉。交易量是买卖的数量，没有名字；问名字要说商品。"}, {"text": "他想知道这个月的交易量有多贵。", "explanation": "这里应该用〈价格〉。交易量是数量，不能说贵；问贵贱要用价格。"}, {"text": "他想知道这个月的交易量能赚多少钱。", "explanation": "这里应该用〈收入〉。交易量本身不能赚钱；问赚钱要用收入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视力", "is_correct": false, "explanation": "搭配：“视力”只用于人或动物的眼睛，不能说“变大”来描述交易。"}, {"text": "交易量", "is_correct": true, "explanation": "交易量指买卖东西的数量，价格便宜后数量马上增加，与“变大”相符。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：“寿命”指存在的年限，与“价格便宜”之后的变化无关。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”说的是高低，不能用“变大”来描述。"}], "explanations": {"视力": "搭配：“视力”只用于人或动物的眼睛，不能说“变大”来描述交易。", "交易量": "交易量指买卖东西的数量，价格便宜后数量马上增加，与“变大”相符。", "寿命": "语义：“寿命”指存在的年限，与“价格便宜”之后的变化无关。", "体温": "搭配：“体温”说的是高低，不能用“变大”来描述。"}, "sentence_index": 6, "correct_answer": "交易量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "买东西的人多了，一笔交易量就上去了。", "explanation": "这里应该去掉〈一笔〉。“笔”用于一次具体的买卖，不能直接修饰交易量这个总数。"}, {"text": "买东西的人多了，交易量就很热闹。", "explanation": "这里应该用〈市场〉。交易量是数量，不能说热闹；热闹的是市场。"}, {"text": "买东西的人多了，交易量就多了几个人。", "explanation": "这里应该用〈人数〉。交易量统计的是买卖的商品数量，不统计人；说人多了要用人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天集市上的交易量少了一个。", "corrected_sentence": "今天集市上的交易量少了一些。", "error_description": "量词错误：“一个”用于可数的个体，交易量是抽象的数量，应说“少了一些”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一周的交易量已经有五百多人了。", "corrected_sentence": "这一周的交易量已经有五百多件了。", "error_description": "量词错误：“人”指人，交易量统计的是买卖的商品数量，应说“五百多件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21426, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最小", "is_correct": true, "explanation": "最大与最小互为反义，指比较中的两个极端。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与“最大”不构成反义。"}, {"text": "安静", "is_correct": false, "explanation": "安静与“吵闹”构成反义，与“最大”无关。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、不模糊，与“最大”没有反义关系。"}], "correct_answer": "最小", "explanations": {"最小": "最大与最小互为反义，指比较中的两个极端。", "明亮": "明亮形容光线或颜色，与“最大”不构成反义。", "安静": "安静与“吵闹”构成反义，与“最大”无关。", "清楚": "清楚指明白、不模糊，与“最大”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21426, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最小", "is_correct": true, "explanation": "最大与最小互为反义，指比较中的两个极端。"}, {"text": "温柔", "is_correct": false, "explanation": "温柔形容性格或态度，与“最大”不构成反义。"}, {"text": "干净", "is_correct": false, "explanation": "干净指整洁，与“最大”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐形容排列有序，与“最大”没有反义关系。"}], "correct_answer": "最小", "explanations": {"最小": "最大与最小互为反义，指比较中的两个极端。", "温柔": "温柔形容性格或态度，与“最大”不构成反义。", "干净": "干净指整洁，与“最大”没有反义关系。", "整齐": "整齐形容排列有序，与“最大”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21426, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "比较中个头、年纪、程度居首。", "primary_collocate": null, "pronunciation": "zuì dà", "ipa": "tswei̯˥˩ ta˥˩", "syllable_count": 2, "sentences": [{"text": "这三个杯子里，红色的杯子最大。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家五个孩子中，姐姐最大，弟弟最小。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的苹果，我拿了看起来最大的那个，因为我很饿。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的房间在三楼，是这套房子里最大的一间。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的鞋子是四十五码，在我们班里最大。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周六晚上的雨最大，我们没有出门。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家超市很小，对面那家才是城里最大的。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风最大的时候，海边的树都倒了。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在三个姐妹里年纪最大，所以常常照顾妹妹。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机屏幕不大，朋友的屏幕才是最大的。", "target_word": "最大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "最大|形容词|比较中个头年纪程度居首", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b00e750-9992-41a7-9c7a-85867ab1d091') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21426, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "最大", "is_correct": true, "explanation": "最大 zuì dà：本词，指比较中个头、年纪、程度居首。"}, {"text": "自大", "is_correct": false, "explanation": "zì 与 zuì 韵母不同，意思是自以为了不起。"}, {"text": "做大", "is_correct": false, "explanation": "zuò 与 zuì 韵母不同，意思是使变大。"}, {"text": "嘴大", "is_correct": false, "explanation": "zuǐ（第三声）与 zuì（第四声）声调不同，意思是嘴巴大。"}, {"text": "再大", "is_correct": false, "explanation": "zài 与 zuì 韵母不同，意思是比现在更大。"}], "explanations": {"最大": "最大 zuì dà：本词，指比较中个头、年纪、程度居首。", "自大": "zì 与 zuì 韵母不同，意思是自以为了不起。", "做大": "zuò 与 zuì 韵母不同，意思是使变大。", "嘴大": "zuǐ（第三声）与 zuì（第四声）声调不同，意思是嘴巴大。", "再大": "zài 与 zuì 韵母不同，意思是比现在更大。"}, "sentence_index": null, "correct_answer": "最大"}, "level_3": {"options": [{"text": "最热闹", "is_correct": false, "explanation": "搭配：杯子不能热闹，“热闹”不能用来描述器物。"}, {"text": "最大", "is_correct": true, "explanation": "最大作谓语，指三个杯子里红色的那个个头第一。"}, {"text": "最聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人，不能说杯子聪明。"}, {"text": "最年轻", "is_correct": false, "explanation": "语义：“年轻”指年龄，杯子没有年龄，与这里的比较无关。"}], "explanations": {"最热闹": "搭配：杯子不能热闹，“热闹”不能用来描述器物。", "最大": "最大作谓语，指三个杯子里红色的那个个头第一。", "最聪明": "搭配：“聪明”形容人，不能说杯子聪明。", "最年轻": "语义：“年轻”指年龄，杯子没有年龄，与这里的比较无关。"}, "sentence_index": 0, "correct_answer": "最大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的价钱最大，我买不起。", "explanation": "这里应该用〈最贵〉。说价钱的高低要用“最贵”，“最大”不用来说价钱。"}, {"text": "他在这套房子里住的时间最大了。", "explanation": "这里应该用〈最长〉。说时间的长短要用“最长”，不用“最大”。"}, {"text": "这次考试，他的表现最大。", "explanation": "这里应该用〈最好〉。说表现、成绩的优劣要用“最好”，不用“最大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最长", "is_correct": false, "explanation": "搭配：超市不能说“长”，“最长”与句意不符。"}, {"text": "最大", "is_correct": true, "explanation": "最大与前文“很小”形成对比，指城里规模第一，所以对面那家才是。"}, {"text": "最勇敢", "is_correct": false, "explanation": "搭配：“勇敢”形容人的品质，不能用来说超市。"}, {"text": "最害羞", "is_correct": false, "explanation": "搭配：“害羞”形容人，不能用来描述超市。"}], "explanations": {"最长": "搭配：超市不能说“长”，“最长”与句意不符。", "最大": "最大与前文“很小”形成对比，指城里规模第一，所以对面那家才是。", "最勇敢": "搭配：“勇敢”形容人的品质，不能用来说超市。", "最害羞": "搭配：“害羞”形容人，不能用来描述超市。"}, "sentence_index": 6, "correct_answer": "最大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的服务态度最大，客人都很满意。", "explanation": "这里应该用〈最热情〉。说态度的好坏要用“热情”一类的词，“最大”不用来形容态度。"}, {"text": "这座老房子的历史最大，已经有三百年了。", "explanation": "这里应该用〈最老〉。说房子的年代要用“老”一类的词，不用“最大”。"}, {"text": "我家离学校最大，每天要坐很久的车。", "explanation": "这里应该用〈最远〉。说距离要用“最远”或“最近”，不用“最大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这三只小猫里，灰色的那只很最大。", "corrected_sentence": "这三只小猫里，灰色的那只最大。", "error_description": "“最大”前不能加“很”，“很最大”是错误的；正确说法是直接用“最大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城里的三所学校，这所比那所最大。", "corrected_sentence": "城里的三所学校，这所最大。", "error_description": "最高级“最大”不能与“比那所”同用：“比”引出比较句，应去掉比较成分，说“这所最大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
