INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21430, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地里长出来的能吃的东西，比如米、菜、水果。", "primary_collocate": null, "pronunciation": "nóng chǎn pǐn", "ipa": "noŋ˧˥ tʂʰan˨˩˦ pʰin˨˩˦", "syllable_count": 3, "sentences": [{"text": "地里长出来的米和菜，都是农产品。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天把地里的农产品送到市场去卖。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天是农产品最多的时候。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店只卖农产品，不卖衣服。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨太多，今年的农产品不太好。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们吃的大米、青菜和苹果都是农产品。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈喜欢去市场买新鲜的农产品，回家就做饭。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些农产品是从农村运来的，很便宜。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小城因为农产品很有名，很多人去买。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在网上卖农产品，生意越来越好。", "target_word": "农产品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "農產品", "label": "繁体"}, {"form": "种", "label": "量词"}, {"form": "批", "label": "量词"}], "register": "中性", "sense_fingerprint": "农产品|名词|地里长出来能吃的米菜水果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b00e750-9992-41a7-9c7a-85867ab1d091') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21430, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工业品", "is_correct": false, "explanation": "语义：工业品是工厂生产的，与地里长出来的米和菜不符。"}, {"text": "农产品", "is_correct": true, "explanation": "正确：地里长出来的米和菜正是农产品。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：米和菜不是乐器，句中“地里长出来”也说明不是乐器。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“都是”后要接同类事物，天空与米、菜不属同类。"}], "explanations": {"工业品": "语义：工业品是工厂生产的，与地里长出来的米和菜不符。", "农产品": "正确：地里长出来的米和菜正是农产品。", "乐器": "语义：米和菜不是乐器，句中“地里长出来”也说明不是乐器。", "天空": "搭配：“都是”后要接同类事物，天空与米、菜不属同类。"}, "sentence_index": 0, "correct_answer": "农产品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民每年给地里施很多农产品。", "explanation": "这里应该用〈化肥〉。“施”的对象是化肥等肥料，农产品是地里收获的食物，不能施。"}, {"text": "他每天穿农产品上学。", "explanation": "这里应该用〈鞋子〉。“穿”的对象是衣物鞋帽，农产品不能穿。"}, {"text": "这家纸厂生产了很多农产品。", "explanation": "这里应该用〈纸张〉。纸厂出产的是纸张，不是农产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能用来做饭，句中“回家就做饭”说明买的是食材。"}, {"text": "书籍", "is_correct": false, "explanation": "语义：书籍不能用来做饭，与“回家就做饭”的食材语境不符。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具不能用来做饭，句中买的是食材。"}, {"text": "农产品", "is_correct": true, "explanation": "正确：妈妈在市场买的新鲜东西是农产品。"}], "explanations": {"玩具": "语义：玩具不能用来做饭，句中“回家就做饭”说明买的是食材。", "书籍": "语义：书籍不能用来做饭，与“回家就做饭”的食材语境不符。", "家具": "语义：家具不能用来做饭，句中买的是食材。", "农产品": "正确：妈妈在市场买的新鲜东西是农产品。"}, "sentence_index": 6, "correct_answer": "农产品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在家里听农产品，很开心。", "explanation": "这里应该用〈音乐〉。“听”的对象是声音作品，农产品不是可以听的东西。"}, {"text": "图书馆里的农产品可以借回家看。", "explanation": "这里应该用〈书籍〉。图书馆藏的是书，农产品不能借阅。"}, {"text": "他每天戴农产品去上班。", "explanation": "这里应该用〈帽子〉。“戴”的对象是帽子等头饰，农产品不能戴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只农产品很新鲜。", "corrected_sentence": "这批农产品很新鲜。", "error_description": "量词错误：“农产品”应该用“批”或“种”，“只”用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些农产品们都很新鲜。", "corrected_sentence": "这些农产品都很新鲜。", "error_description": "“们”只用于指人的复数，“农产品”是物，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
