INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21432, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市，就是有很多房子和很多人的地方。", "primary_collocate": null, "pronunciation": "dū shì", "ipa": "tu˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "我喜欢都市里的夜晚。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座都市有一千多万人。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小山村搬到了都市。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "都市里的车非常多。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人想去都市工作。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "都市的生活节奏很快。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在一座现代化的都市长大。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上的都市到处都是灯。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "都市里的空气不太好。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一部写都市生活的电影。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "人口多、楼房多、很繁华的大城市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b72803e1-d339-466f-98b7-61dea376201f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "都市", "is_correct": true, "explanation": "都市：指人口多、楼房多的大城市，与“都市里的夜晚”的句意相符。"}, {"text": "同学", "is_correct": false, "explanation": "语义：“同学”指人，不是可以“里”的场所，“同学里的夜晚”句意说不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，不是可以容纳夜晚的地方，句意说不通。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“里”多接地点或场所，“考试”是活动，不能说“考试里的夜晚”。"}], "explanations": {"都市": "都市：指人口多、楼房多的大城市，与“都市里的夜晚”的句意相符。", "同学": "语义：“同学”指人，不是可以“里”的场所，“同学里的夜晚”句意说不通。", "钢琴": "语义：“钢琴”是乐器，不是可以容纳夜晚的地方，句意说不通。", "考试": "搭配：“里”多接地点或场所，“考试”是活动，不能说“考试里的夜晚”。"}, "sentence_index": 0, "correct_answer": "都市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家住在一个都市里，周围都是田地。", "explanation": "这里应该用〈村庄〉。“都市”指人口密集、楼房林立的大城市，不能用来形容周围都是田地的地方。"}, {"text": "这个都市只有两条街，大家都互相认识。", "explanation": "这里应该用〈小镇〉。“都市”是大城市，人口多，不能用来形容只有两条街、居民彼此相识的地方。"}, {"text": "都市的夜晚几乎看不到灯，只能听见虫子的叫声。", "explanation": "这里应该用〈乡下〉。“都市”指灯火通明、人口密集的大城市，夜里到处是灯，不能用来形容几乎看不到灯、只能听见虫鸣的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "都市", "is_correct": true, "explanation": "都市：指人口多、楼房多的大城市，与“在一座现代化的都市长大”的句意相符。"}, {"text": "山", "is_correct": false, "explanation": "搭配：“现代化”多修饰城市、工厂等，不能修饰“山”。"}, {"text": "桥", "is_correct": false, "explanation": "语义：“桥”不是人可以在里面长大的地方，“现代化的桥”之中“长大”句意不通。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”是物品，不能用量词“座”，也不是人可以在里面长大的地方，句意说不通。"}], "explanations": {"都市": "都市：指人口多、楼房多的大城市，与“在一座现代化的都市长大”的句意相符。", "山": "搭配：“现代化”多修饰城市、工厂等，不能修饰“山”。", "桥": "语义：“桥”不是人可以在里面长大的地方，“现代化的桥”之中“长大”句意不通。", "电脑": "语义：“电脑”是物品，不能用量词“座”，也不是人可以在里面长大的地方，句意说不通。"}, "sentence_index": 6, "correct_answer": "都市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个都市到处是庄稼和果树。", "explanation": "这里应该用〈农村〉。“都市”指高楼林立的大城市，不能用来形容到处是庄稼和果树的地方。"}, {"text": "这个都市位于深山里，出门要走三天的山路。", "explanation": "这里应该用〈山村〉。“都市”是大城市，不能用来形容位于深山、出门要走三天山路的地方。"}, {"text": "这个都市的人口只有几千，大家都在田里干活。", "explanation": "这里应该用〈乡镇〉。“都市”人口多、楼房多，不能用来形容只有几千人、大家都在田里干活的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条都市的交通很方便。", "corrected_sentence": "这座都市的交通很方便。", "error_description": "量词错误：“都市”是大型城市，应用量词“座”，不能用“条”，应为“这座都市”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆车在都市上开得很慢。", "corrected_sentence": "这辆车在都市里开得很慢。", "error_description": "方位词错误：表示范围应说“都市里”，“都市上”不能这样用，应为“在都市里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21434, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21434, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21434, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "链条是一节一节连起来的东西，像自行车的链子。", "primary_collocate": null, "pronunciation": "liàn tiáo", "ipa": "ljɛn˥˩ tʰjɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "自行车的链条掉了，我不能骑车。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给自行车的链条加了一点油。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条链条是铁做的，一节一节很结实。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用一根粗链条把大门锁住了。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "链条断了，自行车一点儿也不能走。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狗用链条拴着，不能到处跑。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁做的链条一节一节连在一起。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的自行车链条太脏了，要洗一洗。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根链条很长，也很重，一个人拿不动。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自行车上的链条很重要，坏了就走不了。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一根链条", "label": "量词"}, {"form": "一条链条", "label": "量词"}, {"form": "鏈條", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一节一节连起来的金属链子，如自行车链条", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ebcdd33-4c2b-4870-aa27-7ac3753dba86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "链条", "is_correct": true, "explanation": "正确答案。链条是一节节连起来的金属链子，是自行车上会掉落的部件。"}, {"text": "眉毛", "is_correct": false, "explanation": "体貌：眉毛是人的体貌特征，不属于自行车。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是称呼，不是能掉下来的部件。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不是实体，不会掉下来。"}], "explanations": {"链条": "正确答案。链条是一节节连起来的金属链子，是自行车上会掉落的部件。", "眉毛": "体貌：眉毛是人的体貌特征，不属于自行车。", "名字": "语义：名字是称呼，不是能掉下来的部件。", "味道": "语义：味道不是实体，不会掉下来。"}, "sentence_index": 0, "correct_answer": "链条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用链条晾衣服。", "explanation": "这里应该用〈绳子〉。链条是一节节金属环连起来的，晾衣服要用绳子。"}, {"text": "她用链条织了一条围巾。", "explanation": "这里应该用〈毛线〉。链条是金属环连成的，不能用来编织。"}, {"text": "火车在链条上飞驰。", "explanation": "这里应该用〈铁轨〉。链条是一节节连起来的金属链子，火车要在铁轨上行驶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "链条", "is_correct": true, "explanation": "正确答案。链条是一节节连在一起的金属链子。"}, {"text": "句子", "is_correct": false, "explanation": "语义：句子不是金属制品，不能“一节一节连在一起”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不会一节节连在一起，句子说的是链子。"}, {"text": "笔记", "is_correct": false, "explanation": "搭配：“一节一节”搭配可分段的条状物，笔记不适用。"}], "explanations": {"链条": "正确答案。链条是一节节连在一起的金属链子。", "句子": "语义：句子不是金属制品，不能“一节一节连在一起”。", "钥匙": "语义：钥匙不会一节节连在一起，句子说的是链子。", "笔记": "搭配：“一节一节”搭配可分段的条状物，笔记不适用。"}, "sentence_index": 6, "correct_answer": "链条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司机转动链条，车子就拐弯了。", "explanation": "这里应该用〈方向盘〉。链条是传动部件，不能用来转向。"}, {"text": "他用链条在本子上写字。", "explanation": "这里应该用〈笔〉。链条是一节节连起来的金属链子，不能用来写字。"}, {"text": "用链条拧螺丝。", "explanation": "这里应该用〈扳手〉。链条不是拧螺丝的工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的自行车上有一只新链条。", "corrected_sentence": "我的自行车上有一根新链条。", "error_description": "错误：“一只新链条”。正确：“一根新链条”。链条是长条形的东西，量词要用“根”或“条”，“只”不用于链条。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用一只链条把车子锁上了。", "corrected_sentence": "他用一根链条把车子锁上了。", "error_description": "错误：“一只链条”。正确：“一根链条”。链条是长条形的东西，量词要用“根”或“条”，“只”不用于链条。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21436, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静止", "is_correct": true, "explanation": "反义：“静止”指不动，与“流动”（水或空气移动）相对，水池里的水不流动即是静止。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”是发声的动作，与“流动”不构成反义。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：“睡觉”是休息的行为，与“流动”不构成反义。"}, {"text": "思考", "is_correct": false, "explanation": "无关：“思考”指用脑，与“流动”不构成反义。"}], "correct_answer": "静止", "explanations": {"静止": "反义：“静止”指不动，与“流动”（水或空气移动）相对，水池里的水不流动即是静止。", "唱歌": "无关：“唱歌”是发声的动作，与“流动”不构成反义。", "睡觉": "无关：“睡觉”是休息的行为，与“流动”不构成反义。", "思考": "无关：“思考”指用脑，与“流动”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21436, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静止", "is_correct": true, "explanation": "反义：“静止”指不动，与“流动”（水移动）相对，大河里的水不流动即是静止。"}, {"text": "跳舞", "is_correct": false, "explanation": "无关：“跳舞”是身体的律动，与“流动”不构成反义。"}, {"text": "写字", "is_correct": false, "explanation": "无关：“写字”是书写的动作，与“流动”不构成反义。"}, {"text": "吃饭", "is_correct": false, "explanation": "无关：“吃饭”是进食的行为，与“流动”不构成反义。"}], "correct_answer": "静止", "explanations": {"静止": "反义：“静止”指不动，与“流动”（水移动）相对，大河里的水不流动即是静止。", "跳舞": "无关：“跳舞”是身体的律动，与“流动”不构成反义。", "写字": "无关：“写字”是书写的动作，与“流动”不构成反义。", "吃饭": "无关：“吃饭”是进食的行为，与“流动”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21436, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水或空气可以移动，就像河里的水在流。", "primary_collocate": null, "pronunciation": "liú dòng", "ipa": "liou̯˧˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "小河里的水一直在流动。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹过来，空气开始流动了。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水龙头打开后，管子里的水就流动起来了。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水池里的水不流动，会变脏。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的泉水向下流动，最后进了湖里。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里没有风，空气几乎不流动。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，路边的水沿着小沟流动。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天开着窗，凉风在屋里流动着。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水向东流动，穿过了整个城市。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大河里的水，流动得很快，不要下去游泳。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流动着", "label": "体标"}, {"form": "流动了", "label": "体标"}, {"form": "流动过", "label": "体标"}, {"form": "流動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "流动|动词|水或空气像河水一样移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b00e750-9992-41a7-9c7a-85867ab1d091') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21436, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "配价：“喝”的施事须是人或动物，水不能作“喝”的主语。"}, {"text": "上课", "is_correct": false, "explanation": "语义：河水不会上课，这样的说法与句意不符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：水没有考试这样的行为，句子说不通。"}, {"text": "流动", "is_correct": true, "explanation": "正确：小河里的水一直在移动，即“流动”。"}], "explanations": {"喝": "配价：“喝”的施事须是人或动物，水不能作“喝”的主语。", "上课": "语义：河水不会上课，这样的说法与句意不符。", "考试": "语义：水没有考试这样的行为，句子说不通。", "流动": "正确：小河里的水一直在移动，即“流动”。"}, "sentence_index": 0, "correct_answer": "流动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小狗在院子里流动。", "explanation": "这里应该用〈跑〉。动物在地面上奔跑用“跑”，不用“流动”。"}, {"text": "河边的石头在水里流动，很好看。", "explanation": "这里应该用〈滚动〉。石头是固体，在水中翻转移动用“滚动”，“流动”指水或空气等流体的移动。"}, {"text": "小猫从桌上流动下来。", "explanation": "这里应该用〈跳〉。猫从桌上跳下来，不用“流动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱歌", "is_correct": false, "explanation": "语义：水不会唱歌，句意不通。"}, {"text": "流动", "is_correct": true, "explanation": "正确：雨后路边的水沿着小沟移动，即“流动”。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：水不会跳舞，这样的说法与句意不符。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”的动作者须是人或动物，水不能散步。"}], "explanations": {"唱歌": "语义：水不会唱歌，句意不通。", "流动": "正确：雨后路边的水沿着小沟移动，即“流动”。", "跳舞": "语义：水不会跳舞，这样的说法与句意不符。", "散步": "配价：“散步”的动作者须是人或动物，水不能散步。"}, "sentence_index": 6, "correct_answer": "流动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "陀螺在地上流动，转得很快。", "explanation": "这里应该用〈旋转〉。陀螺绕轴转动用“旋转”，不用“流动”。"}, {"text": "杯子从桌上流动下来，摔碎了。", "explanation": "这里应该用〈掉〉。杯子从桌上掉下来是固体的下落，不能说“流动”，“流动”指水或空气等物质的连续移动。"}, {"text": "箱子在地上流动，推了很久。", "explanation": "这里应该用〈滑动〉。箱子在地面上移动用“滑动”，“流动”指水或空气等流体的移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨停以后，路边的水被流动了。", "corrected_sentence": "雨停以后，路边的水开始流动了。", "error_description": "“流动”是不及物动词，不能用“被”字句，应说“开始流动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小溪的水不停地流动着了。", "corrected_sentence": "小溪的水不停地流动着。", "error_description": "体标错误：“流动”后“着”表示持续，不能再加“了”；应说“流动着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0081638d-76d1-4c28-8f38-85c2ebc3efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
