INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21440, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "还在慢慢变富有的国家。", "primary_collocate": null, "pronunciation": "fā zhǎn zhōng guó jiā", "ipa": "fa˥ ʈʂan˨˩ ʈʂʊŋ˥ kuɔ˧˥ tɕja˥", "syllable_count": 5, "sentences": [{"text": "中国是一个发展中国家。", "target_word": "发展中国家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多发展中国家需要更多的学校。", "target_word": "发展中国家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个发展中国家的人口很多。", "target_word": "发展中国家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发展中国家的孩子也想上学。", "target_word": "发展中国家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一个发展中国家工作了三年。", "target_word": "发展中国家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些发展中国家正在修新的铁路。", "target_word": "发展中国家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的发展中国家有很多山和河。", "target_word": "发展中国家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发展中国家的经济一年比一年好。", "target_word": "发展中国家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司把电脑卖到了发展中国家。", "target_word": "发展中国家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个发展中国家的农村还没有通电。", "target_word": "发展中国家", "complexity_tier": "T3", "furigana": "zhè ge fā zhǎn zhōng guó jiā de nóng cūn hái méi yǒu tōng diàn", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "名词发展中国家：经济还在发展、还不富裕的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63681715-008c-4ce4-9cde-53c69200fb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发展中国家", "is_correct": true, "explanation": "“发展中国家”指经济还在发展、尚不富裕的国家，可以用来指“中国”这样的国家。"}, {"text": "大城市", "is_correct": false, "explanation": "语义：“大城市”指城市，不能用来说明中国是一个什么样的国家。"}, {"text": "小镇", "is_correct": false, "explanation": "语义：“小镇”是一个地方，与“国家”不符，句意不通。"}, {"text": "老家", "is_correct": false, "explanation": "语域：“老家”是口语，指人出生或长大的地方，不用来指国家。"}], "explanations": {"发展中国家": "“发展中国家”指经济还在发展、尚不富裕的国家，可以用来指“中国”这样的国家。", "大城市": "语义：“大城市”指城市，不能用来说明中国是一个什么样的国家。", "小镇": "语义：“小镇”是一个地方，与“国家”不符，句意不通。", "老家": "语域：“老家”是口语，指人出生或长大的地方，不用来指国家。"}, "sentence_index": 0, "correct_answer": "发展中国家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条发展中国家很长，从山里一直流到海里。", "explanation": "这里应该用〈河〉。发展中国家指国家，不能说“一条”，也不会流到海里。"}, {"text": "我家附近新开了一个发展中国家，卖很多水果。", "explanation": "这里应该用〈超市〉。发展中国家指国家，不是卖东西的商店。"}, {"text": "我哥哥是一个发展中国家。", "explanation": "这里说的是一个人，不是国家。发展中国家只指国家，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发展中国家", "is_correct": true, "explanation": "“发展中国家”指经济还在发展、尚不富裕的国家，可以放在“有的”之后作主语。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是售卖商品的地方，不会有很多山和河，句意不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是电子产品，不会有山和河，句意不通。"}, {"text": "老窝", "is_correct": false, "explanation": "语域：“老窝”是口语，多指坏人或动物的巢穴，不用于指国家。"}], "explanations": {"发展中国家": "“发展中国家”指经济还在发展、尚不富裕的国家，可以放在“有的”之后作主语。", "超市": "语义：超市是售卖商品的地方，不会有很多山和河，句意不通。", "手机": "语义：手机是电子产品，不会有山和河，句意不通。", "老窝": "语域：“老窝”是口语，多指坏人或动物的巢穴，不用于指国家。"}, "sentence_index": 6, "correct_answer": "发展中国家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个发展中国家有一万名员工。", "explanation": "这里应该用〈公司〉。发展中国家只指国家，不能指企业。"}, {"text": "这个发展中国家的班会很热闹。", "explanation": "这里应该用〈班级〉。发展中国家指国家，班会属于学校班级的活动，不能归国家所有。"}, {"text": "我的妈妈是一个发展中国家。", "explanation": "这里说的是一个人，不是国家。发展中国家只指国家，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老挝是一位发展中国家。", "corrected_sentence": "老挝是一个发展中国家。", "error_description": "“发展中国家”指国家，量词应用“个”；“位”用于人，这里误用了“位”，应为“一个发展中国家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多发展中国家们的人口都在增加。", "corrected_sentence": "很多发展中国家的人口都在增加。", "error_description": "“发展中国家”是名词，不能加“们”表示复数；“很多”已表示数量多，应直接用“发展中国家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
