INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21442, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "处所或物体的里面，与“外”相对。", "primary_collocate": null, "pronunciation": "nèi", "ipa": "neɪ̯˥˩", "syllable_count": 1, "sentences": [{"text": "房间内很安静，没有人说话。", "target_word": "内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子内有一只小猫。", "target_word": "内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校内不能抽烟。", "target_word": "内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门内有一张大桌子。", "target_word": "内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车内很热，请开一下窗。", "target_word": "内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱放在包内。", "target_word": "内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城内有很多老房子。", "target_word": "内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "容器内的水已经冷了。", "target_word": "内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门内是客厅，门外是花园。", "target_word": "内", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在教室内等老师。", "target_word": "内", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "方位词，指某处所的里面，与“外”相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d81d48-6f38-42b1-91d4-5cab678d6582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21442, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "内", "is_correct": true, "explanation": "nèi（第四声）：东西的里面，与“外”相对。"}, {"text": "类", "is_correct": false, "explanation": "lèi 与 nèi 声母不同（l 与 n），声调相同，意思是种类。"}, {"text": "妹", "is_correct": false, "explanation": "mèi 与 nèi 声母不同（m 与 n），声调相同，意思是妹妹。"}, {"text": "嫩", "is_correct": false, "explanation": "nèn 与 nèi 韵尾不同（n 与 i），声调相同，意思是柔软、幼嫩。"}], "explanations": {"内": "nèi（第四声）：东西的里面，与“外”相对。", "类": "lèi 与 nèi 声母不同（l 与 n），声调相同，意思是种类。", "妹": "mèi 与 nèi 声母不同（m 与 n），声调相同，意思是妹妹。", "嫩": "nèn 与 nèi 韵尾不同（n 与 i），声调相同，意思是柔软、幼嫩。"}, "sentence_index": null, "correct_answer": "内"}, "level_3": {"options": [{"text": "上", "is_correct": false, "explanation": "搭配：“上”指表面或上方，“房间上”不能表示房间的内部，此处应说“房间内”。"}, {"text": "内", "is_correct": true, "explanation": "“房间内”指房间的里面，与“很安静，没有人说话”相合。"}, {"text": "下", "is_correct": false, "explanation": "搭配：“下”指下方，“房间下”说不通，指房间的内部要用“内”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不能作为表示空间位置的词，也不能“很安静”。"}], "explanations": {"上": "搭配：“上”指表面或上方，“房间上”不能表示房间的内部，此处应说“房间内”。", "内": "“房间内”指房间的里面，与“很安静，没有人说话”相合。", "下": "搭配：“下”指下方，“房间下”说不通，指房间的内部要用“内”。", "桌子": "语义：“桌子”是家具，不能作为表示空间位置的词，也不能“很安静”。"}, "sentence_index": 0, "correct_answer": "内"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "黑板内写着今天的日期。", "explanation": "这里应该用〈上〉。写在黑板的表面要说“黑板上”，“内”指空间的里面。"}, {"text": "两棵树内有一条小路。", "explanation": "这里应该用〈之间〉。“内”指空间的里面，两棵树中间的位置要说“之间”。"}, {"text": "这棵树内开满了红花。", "explanation": "这里应该用〈上〉。“内”指空间的里面，开在树枝上的花要说“树上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21442, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "内", "is_correct": true, "explanation": "nèi（第四声）：东西的里面，与“外”相对。"}, {"text": "累", "is_correct": false, "explanation": "lèi 与 nèi 声母不同（l 与 n），声调相同，意思是疲劳。"}, {"text": "背", "is_correct": false, "explanation": "bèi 与 nèi 声母不同（b 与 n），声调相同，意思是身体的后面部分。"}, {"text": "腻", "is_correct": false, "explanation": "nì 与 nèi 韵母不同（i 与 ei），意思是油多、令人厌烦。"}], "explanations": {"内": "nèi（第四声）：东西的里面，与“外”相对。", "累": "lèi 与 nèi 声母不同（l 与 n），声调相同，意思是疲劳。", "背": "bèi 与 nèi 声母不同（b 与 n），声调相同，意思是身体的后面部分。", "腻": "nì 与 nèi 韵母不同（i 与 ei），意思是油多、令人厌烦。"}, "sentence_index": null, "correct_answer": "内"}, "level_3": {"options": [{"text": "墙", "is_correct": false, "explanation": "语义：“墙”是墙壁，“城墙有很多老房子”说不通。"}, {"text": "内", "is_correct": true, "explanation": "“城内”指城市的里面，与“有很多老房子”相合。"}, {"text": "书", "is_correct": false, "explanation": "语义：“书”是书籍，不能表示城市的位置，“城书有很多老房子”说不通。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”是颜色，不能表示城市里的位置，“城红有很多老房子”说不通。"}], "explanations": {"墙": "语义：“墙”是墙壁，“城墙有很多老房子”说不通。", "内": "“城内”指城市的里面，与“有很多老房子”相合。", "书": "语义：“书”是书籍，不能表示城市的位置，“城书有很多老房子”说不通。", "红": "语义：“红”是颜色，不能表示城市里的位置，“城红有很多老房子”说不通。"}, "sentence_index": 6, "correct_answer": "内"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "马路内有一家超市。", "explanation": "这里应该用〈上〉。“马路”是平面，“内”指空间的里面，马路上的东西要说“马路上”。"}, {"text": "他的脸内有一个小黑点。", "explanation": "这里应该用〈上〉。黑点在脸的表面，要说“脸上”，“内”指空间的里面。"}, {"text": "桌子内有一只猫。", "explanation": "这里应该用〈底下〉。猫在桌子底下，不是在桌子的里面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车内得空气很新鲜。", "corrected_sentence": "车内的空气很新鲜。", "error_description": "助词错误：表示修饰关系的“的”不能换成“得”。“得”是补语标记，用在“车内”后面不成立，应说“车内的空气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座古城内的保存着很多庙宇。", "corrected_sentence": "这座古城内保存着很多庙宇。", "error_description": "多加字错误：“内”后面直接接动词“保存”，中间不能加“的”，“的”在这里是多余的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
