INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21444, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西拿在身上或和别人一起走。", "primary_collocate": null, "pronunciation": "dài", "ipa": "tai˥˩", "syllable_count": 1, "sentences": [{"text": "周末我想带孩子去公园。", "target_word": "带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他带着狗在河边散步。", "target_word": "带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以带女朋友一起来。", "target_word": "带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶带孙子去医院看病。", "target_word": "带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我带你去找那家书店吧。", "target_word": "带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门要带钥匙，不然进不了家。", "target_word": "带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身上带着一把小刀。", "target_word": "带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天请带你的作业来学校。", "target_word": "带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下午我带妹妹去买新鞋。", "target_word": "带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明带过同学来我们家玩。", "target_word": "带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带着", "label": "着体标"}, {"form": "带过", "label": "过体标"}, {"form": "带了", "label": "了体标"}, {"form": "帶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "拿在身上或陪人一起去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616a40b2-ff1d-4894-b98c-a82aa79ff0f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21444, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "带", "is_correct": true, "explanation": "带（dài）即本词，意为拿在身上或和别人一起走。"}, {"text": "太", "is_correct": false, "explanation": "tài 与 dài 声母不同（t/d），意思是太，是副词。"}, {"text": "大", "is_correct": false, "explanation": "dà 与 dài 韵母不同（a/ai），声调相同，意思是大。"}, {"text": "耐", "is_correct": false, "explanation": "nài 与 dài 声母不同（n/d），意思是耐，即忍耐。"}], "explanations": {"带": "带（dài）即本词，意为拿在身上或和别人一起走。", "太": "tài 与 dài 声母不同（t/d），意思是太，是副词。", "大": "dà 与 dài 韵母不同（a/ai），声调相同，意思是大。", "耐": "nài 与 dài 声母不同（n/d），意思是耐，即忍耐。"}, "sentence_index": null, "correct_answer": "带"}, "level_3": {"options": [{"text": "带", "is_correct": true, "explanation": "带：周末陪孩子一起去公园，与“周末”和“去公园”相合。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”是出售，“卖孩子去公园”不成立。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”是殴打，与陪孩子去公园的意思完全相反。"}, {"text": "喂", "is_correct": false, "explanation": "配价：“喂”要带食物，不能只带人去某处。"}], "explanations": {"带": "带：周末陪孩子一起去公园，与“周末”和“去公园”相合。", "卖": "语义：“卖”是出售，“卖孩子去公园”不成立。", "打": "语义：“打”是殴打，与陪孩子去公园的意思完全相反。", "喂": "配价：“喂”要带食物，不能只带人去某处。"}, "sentence_index": 0, "correct_answer": "带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把杯子带在了桌子上。", "explanation": "这里应该用“摆”。“带”表示把东西拿在身上或和别人一起走，不能表示把东西摆放在某处。"}, {"text": "妈妈把画带在了墙上。", "explanation": "这里应该用“挂”。“带”表示把东西拿在身上或和别人一起走，不能表示把画挂在墙上。"}, {"text": "她把百合带在了花瓶里。", "explanation": "这里应该用“插”。“带”表示把东西拿在身上或和别人一起走，不能表示把花插进花瓶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21444, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "带", "is_correct": true, "explanation": "带（dài）即本词，意为拿在身上或和别人一起走。"}, {"text": "呆", "is_correct": false, "explanation": "dāi（第一声）与 dài（第四声）声调不同，意思是呆。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 dài 声母不同（b/d），意思是拜，如拜访。"}, {"text": "蛋", "is_correct": false, "explanation": "dàn 与 dài 韵母不同（an/ai），声调相同，意思是蛋。"}], "explanations": {"带": "带（dài）即本词，意为拿在身上或和别人一起走。", "呆": "dāi（第一声）与 dài（第四声）声调不同，意思是呆。", "拜": "bài 与 dài 声母不同（b/d），意思是拜，如拜访。", "蛋": "dàn 与 dài 韵母不同（an/ai），声调相同，意思是蛋。"}, "sentence_index": null, "correct_answer": "带"}, "level_3": {"options": [{"text": "带", "is_correct": true, "explanation": "带：身上随身拿着一把小刀，与“身上”相合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”配衣物，不能说“穿小刀”。"}, {"text": "磨", "is_correct": false, "explanation": "语义：“磨”指研磨或打磨，与“身上”的状态不符，句子不通。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指擦拭，与“身上”放着小刀的状态无关，句子不通。"}], "explanations": {"带": "带：身上随身拿着一把小刀，与“身上”相合。", "穿": "搭配：“穿”配衣物，不能说“穿小刀”。", "磨": "语义：“磨”指研磨或打磨，与“身上”的状态不符，句子不通。", "擦": "语义：“擦”指擦拭，与“身上”放着小刀的状态无关，句子不通。"}, "sentence_index": 6, "correct_answer": "带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上带一个小时的书。", "explanation": "这里应该用“看”。“带”表示把东西拿在身上或和别人一起走，没有“阅读”的意思。"}, {"text": "护士给他带了血压。", "explanation": "这里应该用“量”。“带”表示把东西拿在身上或和别人一起走，没有“测量”的意思。"}, {"text": "请把黑板带干净。", "explanation": "这里应该用“擦”。“带”表示把东西拿在身上或和别人一起走，没有“擦拭”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小红明天带过妹妹去书店。", "corrected_sentence": "小红明天带妹妹去书店。", "error_description": "时体错误：「过」表示曾有过的经历，不能用于将来的「明天」，应去掉「过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他带狗着去河边。", "corrected_sentence": "他带着狗去河边。", "error_description": "错误形式是“带狗着”，“着”放在宾语“狗”之后；正确形式是“带着狗”，“着”紧跟动词“带”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
