INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21446, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "赤道南边的位置。", "primary_collocate": null, "pronunciation": "nán wěi", "ipa": "nan³⁵ weɪ²¹⁴", "syllable_count": 2, "sentences": [{"text": "南纬是赤道南边的位置。", "target_word": "南纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在地图上找南纬三十度。", "target_word": "南纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "悉尼在南纬三十四度左右。", "target_word": "南纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南纬三十度附近的冬天在六月到八月。", "target_word": "南纬", "complexity_tier": "T3", "furigana": "nán wěi sān shí dù fù jìn de dōng tiān zài liù yuè dào bā yuè.", "sentence_source": "generated"}, {"text": "那个科学家去过南纬六十度以南的地方。", "target_word": "南纬", "complexity_tier": "T3", "furigana": "nà ge kē xué jiā qù guo nán wěi liù shí dù yǐ nán de dì fāng.", "sentence_source": "generated"}, {"text": "南纬二十度的天气很热。", "target_word": "南纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞到了南纬二十度的海上。", "target_word": "南纬", "complexity_tier": "T3", "furigana": "fēi jī fēi dào le nán wěi èr shí dù de hǎi shàng.", "sentence_source": "generated"}, {"text": "请在地图上画出南纬十度的线。", "target_word": "南纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南纬地区的季节和北方相反。", "target_word": "南纬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友住在南纬三十五度附近，圣诞节是夏天。", "target_word": "南纬", "complexity_tier": "T3", "furigana": "wǒ péng yǒu zhù zài nán wěi sān shí wǔ dù fù jìn, shèng dàn jié shì xià tiān.", "sentence_source": "generated"}], "morphological_forms": [{"form": "南緯", "label": "繁体"}], "register": "中性", "sense_fingerprint": "赤道南边的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abfcfa9a-a51d-42c1-8ec4-e1f3a9b309a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21446, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "南纬", "is_correct": true, "explanation": "正确。南纬指赤道以南的纬度位置，正好是“赤道南边的位置”。"}, {"text": "北纬", "is_correct": false, "explanation": "语义：北纬在赤道以北，与句中“赤道南边”矛盾。"}, {"text": "北极", "is_correct": false, "explanation": "语义：北极位于赤道北边，不在赤道南边。"}, {"text": "赤道", "is_correct": false, "explanation": "搭配：“赤道”本身是纬线，不能用“赤道南边的位置”来定义它自己。"}], "explanations": {"南纬": "正确。南纬指赤道以南的纬度位置，正好是“赤道南边的位置”。", "北纬": "语义：北纬在赤道以北，与句中“赤道南边”矛盾。", "北极": "语义：北极位于赤道北边，不在赤道南边。", "赤道": "搭配：“赤道”本身是纬线，不能用“赤道南边的位置”来定义它自己。"}, "sentence_index": 0, "correct_answer": "南纬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的南纬是二十五度，很暖和。", "explanation": "这里应该用〈气温〉。“南纬”是地理位置，不表示天气冷热；说暖和要用“气温”。"}, {"text": "老师带我们向南纬出发。", "explanation": "这里应该用〈南方〉。“南纬”是纬度坐标，不表示方向，表示方向应说“南方”。"}, {"text": "这条河的南纬有三百公里长。", "explanation": "这里应该用〈长〉。“南纬”指纬线的位置，不能表示长度；说河有多长要用“长”，如“这条河有三百公里长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21446, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "南纬", "is_correct": true, "explanation": "正确。“南纬二十度”是一个纬度位置，飞机可以飞到那里的海上。"}, {"text": "海拔", "is_correct": false, "explanation": "搭配：海拔以米计，不以度计，“海拔二十度的海上”不成立。"}, {"text": "时速", "is_correct": false, "explanation": "搭配：时速以公里计，“飞到了时速二十度的海上”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重不是地理位置，也不以度计，“体重二十度的海上”说不通。"}], "explanations": {"南纬": "正确。“南纬二十度”是一个纬度位置，飞机可以飞到那里的海上。", "海拔": "搭配：海拔以米计，不以度计，“海拔二十度的海上”不成立。", "时速": "搭配：时速以公里计，“飞到了时速二十度的海上”不成立。", "体重": "语义：体重不是地理位置，也不以度计，“体重二十度的海上”说不通。"}, "sentence_index": 6, "correct_answer": "南纬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "东京位于南纬三十五度附近。", "explanation": "这里应该用〈北纬〉。东京在赤道以北，描述位置要说“北纬”；“南纬”指赤道以南。"}, {"text": "这个岛屿的南纬很漂亮。", "explanation": "这里应该用〈风景〉。“南纬”是纬线位置，不能形容美丑；说美要用“风景”，如“这个岛屿的风景很美”。"}, {"text": "北极圈在南纬六十六度附近。", "explanation": "这里应该用〈北纬〉。北极圈位于北纬六十六度左右，描述北半球的位置要用“北纬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河流位于南纬十六附近。", "corrected_sentence": "这条河流位于南纬十六度附近。", "error_description": "漏了单位“度”。纬度数值后要带“度”，应说“南纬十六度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们的科考船在南纬六十度南的海域工作。", "corrected_sentence": "他们的科考船在南纬六十度以南的海域工作。", "error_description": "漏了方位词“以”。表示某纬度以南要说“南纬六十度以南”，不能省略“以”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21448, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短暂", "is_correct": true, "explanation": "反义：“漫长”说时间延续很久，“短暂”说时间很短，两者在时间长短上相反，正是这一义项的反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "与“漫长”无反义关系：“明亮”形容光线，与时间长短无关。"}, {"text": "热闹", "is_correct": false, "explanation": "与“漫长”无反义关系：“热闹”形容场面，不涉及时间的长短。"}, {"text": "干净", "is_correct": false, "explanation": "与“漫长”无反义关系：“干净”形容洁净，与时间无关。"}], "correct_answer": "短暂", "explanations": {"短暂": "反义：“漫长”说时间延续很久，“短暂”说时间很短，两者在时间长短上相反，正是这一义项的反义词。", "明亮": "与“漫长”无反义关系：“明亮”形容光线，与时间长短无关。", "热闹": "与“漫长”无反义关系：“热闹”形容场面，不涉及时间的长短。", "干净": "与“漫长”无反义关系：“干净”形容洁净，与时间无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21448, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短暂", "is_correct": true, "explanation": "反义：“漫长”说时间延续很久，“短暂”说时间很短，在时间长短上相对，是这一义项的反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "与“漫长”无反义关系：“清楚”形容明白或清晰，与时间长短无关。"}, {"text": "寒冷", "is_correct": false, "explanation": "与“漫长”无反义关系：“寒冷”形容温度，与时间无关。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“漫长”无反义关系：“陡峭”形容地势，不涉及时间。"}], "correct_answer": "短暂", "explanations": {"短暂": "反义：“漫长”说时间延续很久，“短暂”说时间很短，在时间长短上相对，是这一义项的反义词。", "清楚": "与“漫长”无反义关系：“清楚”形容明白或清晰，与时间长短无关。", "寒冷": "与“漫长”无反义关系：“寒冷”形容温度，与时间无关。", "陡峭": "与“漫长”无反义关系：“陡峭”形容地势，不涉及时间。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21448, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容时间或路程很长，让人感觉过得慢。", "primary_collocate": null, "pronunciation": "màn cháng", "ipa": "man˥˩ ʈʂʰaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "等人的时候，一分钟也很漫长。", "target_word": "漫长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上课的时候，我觉得时间特别漫长。", "target_word": "漫长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有手机，火车上的几个小时更漫长了。", "target_word": "漫长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子盼着过年，觉得一个月太漫长。", "target_word": "漫长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排队买票的两个小时真漫长。", "target_word": "漫长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天的白天很漫长，晚上八点天才黑。", "target_word": "漫长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人坐车回家，路显得很漫长。", "target_word": "漫长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试前的一天，我觉得过得很漫长。", "target_word": "漫长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在病床上躺着，每个夜晚都很漫长。", "target_word": "漫长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对小孩子来说，一节课太漫长了。", "target_word": "漫长", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "漫长：时间或路程很长，感觉过得慢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e4321f-de6e-46a4-8743-02c784fb0964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21448, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漫长", "is_correct": true, "explanation": "漫长：形容等待的时间长、感觉慢，与“等人的时候”的心理相合。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容质地，不能用来形容一段时间。"}, {"text": "清晰", "is_correct": false, "explanation": "搭配：“清晰”形容轮廓或声音，不用来形容时间的长短。"}, {"text": "冰凉", "is_correct": false, "explanation": "搭配：“冰凉”形容温度，不能修饰“一分钟”这样的时间。"}], "explanations": {"漫长": "漫长：形容等待的时间长、感觉慢，与“等人的时候”的心理相合。", "粗糙": "搭配：“粗糙”形容质地，不能用来形容一段时间。", "清晰": "搭配：“清晰”形容轮廓或声音，不用来形容时间的长短。", "冰凉": "搭配：“冰凉”形容温度，不能修饰“一分钟”这样的时间。"}, "sentence_index": 0, "correct_answer": "漫长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片操场很漫长。", "explanation": "这里应该用〈宽阔〉。“漫长”形容时间或距离延续很久，操场的大小要说“宽阔”。"}, {"text": "这间房间很漫长。", "explanation": "这里应该用〈宽敞〉。“漫长”形容时间或距离延续很久，不能用来说房间的大小，房间的大小要说“宽敞”。"}, {"text": "这个行李箱很漫长。", "explanation": "这里应该用〈大〉。“漫长”形容时间或距离延续很久，不能用来说物品的尺寸，行李箱的大小要说“大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "漫长", "is_correct": true, "explanation": "漫长：形容路程延续很久，与“一个人坐车回家”的孤单感相合，在句中受“很”修饰作谓语。"}, {"text": "欢快", "is_correct": false, "explanation": "语义：“一个人坐车回家”的情景与“欢快”的气氛相悖。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”形容声音或笑容，不能用来形容路。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容质地，不能用来形容路的长短。"}], "explanations": {"漫长": "漫长：形容路程延续很久，与“一个人坐车回家”的孤单感相合，在句中受“很”修饰作谓语。", "欢快": "语义：“一个人坐车回家”的情景与“欢快”的气氛相悖。", "甜美": "搭配：“甜美”形容声音或笑容，不能用来形容路。", "柔软": "搭配：“柔软”形容质地，不能用来形容路的长短。"}, "sentence_index": 6, "correct_answer": "漫长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那棵树很漫长。", "explanation": "这里应该用〈高大〉。“漫长”说时间或距离延续很久，不形容树的高矮，要说“高大”。"}, {"text": "这件衬衫很漫长。", "explanation": "这里应该用〈长〉。“漫长”形容时间或距离延续很久，不能用来说衣服的长短，衣服的长短要说“长”。"}, {"text": "这块木板很漫长。", "explanation": "这里应该用〈长〉。“漫长”形容时间或距离延续很久，不能用来说物体的长度，木板的长度要说“长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个下午我觉得时间过很漫长。", "corrected_sentence": "这个下午我觉得时间过得很漫长。", "error_description": "错误在补语标记：“过很漫长”应为“过得很漫长”，形容词作程度补语时必须用“得”，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "对小孩子来说，这是一节漫长地课。", "corrected_sentence": "对小孩子来说，这是一节漫长的课。", "error_description": "错误在结构助词：“漫长”修饰名词“课”时应用“的”，“地”用于修饰动词，不能用于此处。应为“一节漫长的课”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
