INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21452, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一起存在", "primary_collocate": null, "pronunciation": "bìng cún", "ipa": "piŋ˥˩ tsʰuən˧˥", "syllable_count": 2, "sentences": [{"text": "两种不同的意见可以并存。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的老树和新房子并存。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这片森林里，多种动物并存。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市里，富人区和穷人区并存。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快乐和难过在她心里并存着。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里新桥与旧桥并存。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的电车和汽车长期并存。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的校园里，老楼和新楼并存。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个想法在他脑子里并存。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现金和手机支付在小店里并存。", "target_word": "并存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "并存着", "label": "体标"}, {"form": "并存过", "label": "体标"}], "register": "书面", "sense_fingerprint": "不同的人、事物或想法在一起共同存在，互不排斥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af58cd74-a966-4809-b2bd-5cb92529248a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21452, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "并存", "is_correct": true, "explanation": "正确：“并存”指不同的意见在一起存在、互不排斥，与“可以”相符。"}, {"text": "雷同", "is_correct": false, "explanation": "语义：“雷同”指完全一样，与句中的“不同的意见”矛盾。"}, {"text": "发霉", "is_correct": false, "explanation": "搭配：“发霉”指物品长霉，不用于“意见”。"}, {"text": "消毒", "is_correct": false, "explanation": "搭配：“消毒”用于物品或环境，不能用于“意见”。"}], "explanations": {"并存": "正确：“并存”指不同的意见在一起存在、互不排斥，与“可以”相符。", "雷同": "语义：“雷同”指完全一样，与句中的“不同的意见”矛盾。", "发霉": "搭配：“发霉”指物品长霉，不用于“意见”。", "消毒": "搭配：“消毒”用于物品或环境，不能用于“意见”。"}, "sentence_index": 0, "correct_answer": "并存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座古塔并存于山脚。", "explanation": "这里应该用〈存在〉。“存在”可用于单个事物；“并存”指两种或更多事物同时存在，一座古塔不能说并存。"}, {"text": "他一个人并存在家里看书。", "explanation": "这里应该用〈待〉。“并存”指两种或以上事物同时存在，不能用来说一个人待在某处。"}, {"text": "白天与黑夜并存，先后轮流出现。", "explanation": "这里应该用〈交替〉。“交替”指先后轮流出现；“并存”指同时存在，与“先后轮流”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "并存", "is_correct": true, "explanation": "正确：“并存”指两种交通工具长期同时存在，与“长期”相符。"}, {"text": "诞生", "is_correct": false, "explanation": "体貌：“诞生”是一次完成的动作，不能和“长期”这样的时段连用。"}, {"text": "灭绝", "is_correct": false, "explanation": "搭配：“灭绝”多用于物种，不能用于电车和汽车。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：“出生”只用于人或动物，不能用于交通工具。"}], "explanations": {"并存": "正确：“并存”指两种交通工具长期同时存在，与“长期”相符。", "诞生": "体貌：“诞生”是一次完成的动作，不能和“长期”这样的时段连用。", "灭绝": "搭配：“灭绝”多用于物种，不能用于电车和汽车。", "出生": "搭配：“出生”只用于人或动物，不能用于交通工具。"}, "sentence_index": 6, "correct_answer": "并存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条并存的小路通往山顶。", "explanation": "这里应该用〈存在〉。“存在”可用于单个事物；“并存”需要两种或以上的事物同时存在，一条小路不能说并存。"}, {"text": "我把旧照片并存在抽屉里。", "explanation": "这里应该用〈保存〉。“保存”指把东西存放好；“并存”是不及物动词，指不同事物同时存在，不能带宾语表示存放。"}, {"text": "这位经理并存于两个部门。", "explanation": "这里应该用〈兼任〉。“兼任”指一人同时担任两个职务；“并存”指事物或情况同时存在，不用于一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在这座古城里，寺庙与教堂被并存。", "corrected_sentence": "在这座古城里，寺庙与教堂并存。", "error_description": "错误：“并存”前面加了“被”。并存是不及物动词，不能用于被动句，应说“寺庙与教堂并存”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家菜市场里，现金和手机支付很并存。", "corrected_sentence": "这家菜市场里，现金和手机支付并存。", "error_description": "错误：“并存”前面加了程度副词“很”。并存是动词，不能被“很”修饰，应说“现金和手机支付并存”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
