INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21454, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地球中间很热的地方。", "primary_collocate": null, "pronunciation": "rè dài", "ipa": "ʐɤ⁵¹ taɪ⁵¹", "syllable_count": 2, "sentences": [{"text": "热带在地球的中间，天气很热。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的地图上，热带是红色的。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里是热带，冬天也不冷。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从热带回来，皮肤变黑了。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热带的太阳又大又热。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在热带的人常穿短袖。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们想知道热带有没有雪。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热带的海水很暖和。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次去热带，准备了很多防晒霜。", "target_word": "热带", "complexity_tier": "T3", "furigana": "tā dì yī cì qù rè dài, zhǔn bèi le hěn duō fáng shài shuāng.", "sentence_source": "generated"}, {"text": "热带的夜晚也不凉快。", "target_word": "热带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "热带雨林", "label": "复合"}, {"form": "熱帶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "地球中间很热的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abfcfa9a-a51d-42c1-8ec4-e1f3a9b309a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21454, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热带", "is_correct": true, "explanation": "正确。热带位于地球中部，天气炎热，符合句意。"}, {"text": "北极", "is_correct": false, "explanation": "语义：北极位于地球最北端，不在地球中间。"}, {"text": "冰川", "is_correct": false, "explanation": "搭配：“冰川”与“天气很热”搭配冲突，冰川地区天气寒冷。"}, {"text": "北方", "is_correct": false, "explanation": "语义：北方位于地球北部，并不在地球中间。"}], "explanations": {"热带": "正确。热带位于地球中部，天气炎热，符合句意。", "北极": "语义：北极位于地球最北端，不在地球中间。", "冰川": "搭配：“冰川”与“天气很热”搭配冲突，冰川地区天气寒冷。", "北方": "语义：北方位于地球北部，并不在地球中间。"}, "sentence_index": 0, "correct_answer": "热带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "北京四季分明，冬天会下雪，属于热带。", "explanation": "这里应该用〈温带〉。热带全年高温、没有冬天；四季分明、冬天下雪的地方属于温带。"}, {"text": "北极全年很冷，属于热带。", "explanation": "这里应该用〈寒带〉。全年寒冷的北极属于寒带，热带指全年高温的地区。"}, {"text": "成都冬天有霜，属于热带。", "explanation": "这里应该用〈亚热带〉。冬天有霜说明不是全年高温的热带，成都属于亚热带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "热带", "is_correct": true, "explanation": "正确。孩子们想知道的是热带地区有没有雪，只有“热带”符合句意。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是恒星，不会下雪，“太阳有没有雪”不成立。"}, {"text": "香蕉", "is_correct": false, "explanation": "搭配：“有没有雪”需要地点或地区作主语，“香蕉”不是地点。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是地方，“课本有没有雪”没有意义。"}], "explanations": {"热带": "正确。孩子们想知道的是热带地区有没有雪，只有“热带”符合句意。", "太阳": "语义：太阳是恒星，不会下雪，“太阳有没有雪”不成立。", "香蕉": "搭配：“有没有雪”需要地点或地区作主语，“香蕉”不是地点。", "课本": "语义：课本不是地方，“课本有没有雪”没有意义。"}, "sentence_index": 6, "correct_answer": "热带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "拉萨海拔很高，夏天凉爽，属于热带气候。", "explanation": "这里应该用〈高原〉。海拔高、夏天凉爽的地区属于高原气候，与热带的全年高温不符。"}, {"text": "罗马夏天干燥，冬天湿润，属于热带气候。", "explanation": "这里应该用〈地中海〉。夏干冬湿的气候属于地中海气候，不属于热带。"}, {"text": "东北冬天很冷，属于热带气候。", "explanation": "这里应该用〈温带〉。冬冷夏热的东北属于温带气候，不是全年高温的热带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从热带住过两年。", "corrected_sentence": "他在热带住过两年。", "error_description": "用词错误：“在”误用为“从”。“住”表示在某地居住，地点前要用“在”；“从”表示起点，不能和“住过两年”搭配。错误形式是“从热带住过”，正确形式是“在热带住过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天要飞了热带。", "corrected_sentence": "我们明天要飞到热带。", "error_description": "误用“了”：“了”表完成，不能表示去向，与“明天要”也不相容；“飞”后接去向应用“到”或“往”。正确形式是“飞到热带”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21456, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "商品经济", "is_correct": true, "explanation": "〈商品经济〉以交换和销售为目的，与“不卖给别人、自己吃”的小农经济相对，是反义关系。"}, {"text": "体育场", "is_correct": false, "explanation": "〈体育场〉是进行体育活动的场地，与经济形态无关。"}, {"text": "动物园", "is_correct": false, "explanation": "〈动物园〉是展示动物的场所，与农业经济形态没有反义关系。"}, {"text": "图书馆", "is_correct": false, "explanation": "〈图书馆〉是借阅书籍的场所，与经济形态无关。"}], "correct_answer": "商品经济", "explanations": {"商品经济": "〈商品经济〉以交换和销售为目的，与“不卖给别人、自己吃”的小农经济相对，是反义关系。", "体育场": "〈体育场〉是进行体育活动的场地，与经济形态无关。", "动物园": "〈动物园〉是展示动物的场所，与农业经济形态没有反义关系。", "图书馆": "〈图书馆〉是借阅书籍的场所，与经济形态无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21456, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "商品经济", "is_correct": true, "explanation": "〈商品经济〉以交换和销售为目的，与“不卖给别人”的小农经济相对，是反义关系。"}, {"text": "火车站", "is_correct": false, "explanation": "〈火车站〉是交通场所，与经济形态无关。"}, {"text": "钢琴", "is_correct": false, "explanation": "〈钢琴〉是乐器，与农业经济形态没有反义关系。"}, {"text": "冰箱", "is_correct": false, "explanation": "〈冰箱〉是家用电器，与经济形态无关。"}], "correct_answer": "商品经济", "explanations": {"商品经济": "〈商品经济〉以交换和销售为目的，与“不卖给别人”的小农经济相对，是反义关系。", "火车站": "〈火车站〉是交通场所，与经济形态无关。", "钢琴": "〈钢琴〉是乐器，与农业经济形态没有反义关系。", "冰箱": "〈冰箱〉是家用电器，与经济形态无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21456, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "农民在自己家里种地，自己吃，不卖给别人。", "primary_collocate": null, "pronunciation": "xiǎo nóng jīng jì", "ipa": "ɕjɑʊ²¹⁴ nʊŋ³⁵ tɕiŋ⁵⁵ tɕi⁵¹", "syllable_count": 4, "sentences": [{"text": "小农经济就是农民自己种地自己吃。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷小时候，村里是小农经济。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小农经济不卖粮食给别人。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在小农经济里，一家人一起种地。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子以前是小农经济。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小农经济的农民很少去市场。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们靠小农经济过日子。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小农经济让农民有饭吃，但钱不多。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里讲了小农经济的故事。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在小农经济比以前少多了。", "target_word": "小农经济", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小農經濟", "label": "繁体"}], "register": "书面", "sense_fingerprint": "农民自己种地自己吃、不卖给别人的经济方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abfcfa9a-a51d-42c1-8ec4-e1f3a9b309a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21456, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小农经济", "is_correct": true, "explanation": "正确：指农民自己种地、自己吃的经济形态，与句意一致。"}, {"text": "大农场", "is_correct": false, "explanation": "语义：大农场靠雇工经营，与“农民自己种地自己吃”的意思相反。"}, {"text": "城市经济", "is_correct": false, "explanation": "语义：城市经济以工商业和交换为主，与“农民自己种地”不相符。"}, {"text": "工业化", "is_correct": false, "explanation": "搭配：“就是……”后接具体的经济形态，“工业化”是发展过程，不能这样下定义。"}], "explanations": {"小农经济": "正确：指农民自己种地、自己吃的经济形态，与句意一致。", "大农场": "语义：大农场靠雇工经营，与“农民自己种地自己吃”的意思相反。", "城市经济": "语义：城市经济以工商业和交换为主，与“农民自己种地”不相符。", "工业化": "搭配：“就是……”后接具体的经济形态，“工业化”是发展过程，不能这样下定义。"}, "sentence_index": 0, "correct_answer": "小农经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在小农经济里，农民都听大队统一安排去地里干活。", "explanation": "这里应该用〈集体农庄〉。小农经济是各家自己种地、自己吃，不由大队统一安排；统一安排劳动要用〈集体农庄〉。"}, {"text": "这个村子是小农经济，粮食全部卖给外地商人。", "explanation": "这里应该用〈市场经济〉。小农经济不卖给别人，粮食全部卖给外地商人要用〈市场经济〉。"}, {"text": "在小农经济里，农民每天都把粮食卖到市场。", "explanation": "这里应该用〈商品经济〉。小农经济不卖粮食给别人，说“每天把粮食卖到市场”要用〈商品经济〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21456, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小农经济", "is_correct": true, "explanation": "正确：“靠……过日子”说的是靠某种经济方式维持生计，与句意一致。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不是生计来源，“靠阳光过日子”说不通。"}, {"text": "矿泉水", "is_correct": false, "explanation": "语义：矿泉水是饮品，不能作为维持生计的依靠。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是挡雨的用品，不能作为维持生计的依靠，“靠雨伞过日子”说不通。"}], "explanations": {"小农经济": "正确：“靠……过日子”说的是靠某种经济方式维持生计，与句意一致。", "阳光": "语义：阳光不是生计来源，“靠阳光过日子”说不通。", "矿泉水": "语义：矿泉水是饮品，不能作为维持生计的依靠。", "雨伞": "语义：雨伞是挡雨的用品，不能作为维持生计的依靠，“靠雨伞过日子”说不通。"}, "sentence_index": 6, "correct_answer": "小农经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现在我们村的小农经济开了很多店。", "explanation": "这里应该用〈个体户〉。小农经济指经济形态，不能充当开店的经营者。"}, {"text": "城里的小农经济每年按股份给股东分红。", "explanation": "这里应该用〈股份制企业〉。小农经济是以家庭为单位、自给自足的经营形态，不设股东，也不按股份分红。"}, {"text": "这家小农经济一直靠出口赚钱。", "explanation": "这里应该用〈公司〉。小农经济以自给自足为主，不靠出口赚钱，也不是经营主体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那时候的村子很小农经济。", "corrected_sentence": "那时候的村子是小农经济。", "error_description": "用词错误：“是”误用为“很”。“小农经济”是名词，作判断的宾语要用“是”，不能用程度副词“很”修饰。错误形式是“村子很小农经济”，正确形式是“村子是小农经济”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民把小农经济生活，很少买东西。", "corrected_sentence": "农民靠小农经济生活，很少买东西。", "error_description": "用词错误：“靠”误用为“把”。“把”字句要求后面有被处置的对象，这里表示依靠，应该用“靠”。错误形式是“农民把小农经济生活”，正确形式是“农民靠小农经济生活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
