INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21458, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事或运行时固定的方式。", "primary_collocate": null, "pronunciation": "mó shì", "ipa": "mwo˧˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "他的学习模式很特别。", "target_word": "模式", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现在很多人喜欢线上的工作模式。", "target_word": "模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店用新的经营模式赚了不少钱。", "target_word": "模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个孩子都有自己的成长模式。", "target_word": "模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机有安静模式，开会时可以用。", "target_word": "模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要改变以前的生活模式。", "target_word": "模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种合作模式让两家公司都很满意。", "target_word": "模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天的生活模式都一样：起床、工作、睡觉。", "target_word": "模式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏有两种模式，你想玩哪一种？", "target_word": "模式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们喜欢新的教学模式。", "target_word": "模式", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "工作模式", "label": "复合"}, {"form": "生活模式", "label": "复合"}, {"form": "经营模式", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事或运行时固定、可重复的方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e685e353-0b99-4f1c-ae5d-499665025313') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模式", "is_correct": true, "explanation": "模式：指学习时固定的方式，与“学习”搭配，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，学习不能有味道，句意不通。"}, {"text": "脸色", "is_correct": false, "explanation": "搭配：“脸色”指面部的气色，不能说“学习脸色”。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”属于身体特征，与学习方式无关，不能用于“学习”。"}], "explanations": {"模式": "模式：指学习时固定的方式，与“学习”搭配，符合句意。", "味道": "语义：“味道”指气味或滋味，学习不能有味道，句意不通。", "脸色": "搭配：“脸色”指面部的气色，不能说“学习脸色”。", "体重": "体貌：“体重”属于身体特征，与学习方式无关，不能用于“学习”。"}, "sentence_index": 0, "correct_answer": "模式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的模式很可爱。", "explanation": "这里应该用〈模样〉。模式指做事或运行的固定方式，不能用来形容外貌。"}, {"text": "老师学了一块新模式，很快就掌握了。", "explanation": "这里应该用〈种〉。模式用“种”计量，“块”多用于片状的东西，不能用来计量抽象的模式。"}, {"text": "他的模式很开朗，大家都喜欢他。", "explanation": "这里应该用〈性格〉。模式指固定的做法，不能用来形容人的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模式", "is_correct": true, "explanation": "模式：指合作时固定的方式，与“合作”搭配，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”与“合作”无关，句子说的是合作方式，不能指天气。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“合作”不能跟“水果”组成搭配，句意不通。"}, {"text": "亲情", "is_correct": false, "explanation": "语义：“亲情”指家人之间的感情，与公司之间的合作句意不符。"}], "explanations": {"模式": "模式：指合作时固定的方式，与“合作”搭配，符合句意。", "天气": "语义：“天气”与“合作”无关，句子说的是合作方式，不能指天气。", "水果": "搭配：“合作”不能跟“水果”组成搭配，句意不通。", "亲情": "语义：“亲情”指家人之间的感情，与公司之间的合作句意不符。"}, "sentence_index": 6, "correct_answer": "模式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的模式很鲜美。", "explanation": "这里应该用〈味道〉。模式指做事或运行的固定方式，不能用来形容菜的味道。"}, {"text": "这个汽车模式很精致，放在橱窗里。", "explanation": "这里应该用〈模型〉。模式是抽象的做法或样式，指实物模型要用模型。"}, {"text": "他把模式装进了书包。", "explanation": "这里应该用〈资料〉。模式是抽象概念，不能被装进容器，装进书包的应是具体的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师总结了这种教学模式们的优点。", "corrected_sentence": "老师总结了这种教学模式的优点。", "error_description": "错误在“模式”后多加了“们”。“模式”是抽象名词，不能加“们”表示复数，应去掉“们”，说“教学模式的优点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们想改变原来的一块模式。", "corrected_sentence": "他们想改变原来的一种模式。", "error_description": "错误在量词“块”。“模式”是抽象的做法，应用量词“种”，“块”多用于片状的东西，应说“一种模式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e211d8-98e0-4280-807c-a91714ed980f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
