INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21460, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿出东西给需要的人用。", "primary_collocate": null, "pronunciation": "gōng jǐ", "ipa": "kʊŋ˥ tɕi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家工厂供给全城的电。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民供给城里人新鲜的菜。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府供给灾区食物和水。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的泉水供给全村人用水。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司供给员工免费午饭。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河供给了整个城市的水。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每月供给我生活费。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个农场一直供给学校牛奶。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座水库每天供给周边三个县的农田用水。", "target_word": "供给", "complexity_tier": "T3", "furigana": "zhè zuò shuǐkù měitiān gōngjǐ zhōubiān sān gè xiàn de nóngtián yòngshuǐ", "sentence_source": "generated"}, {"text": "妈妈供给着弟弟上学的钱。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "供给了", "label": "体标"}, {"form": "供给着", "label": "体标"}, {"form": "供給", "label": "繁体"}], "register": "书面", "sense_fingerprint": "拿出物资、钱财等，满足别人的需要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6d81d48-6f38-42b1-91d4-5cab678d6582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21460, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "供给", "is_correct": true, "explanation": "正确答案。供给 gōng jǐ，意思是拿出物资供人使用。"}, {"text": "攻击", "is_correct": false, "explanation": "gōngjī（第一声）与 gōng jǐ（第三声）第二音节声调不同，意思是攻击。"}, {"text": "恭喜", "is_correct": false, "explanation": "xǐ 与 jǐ 声母不同（x 与 j），声调相同，意思是祝贺。"}, {"text": "功绩", "is_correct": false, "explanation": "jì（第四声）与 jǐ（第三声）声调不同，意思是功绩。"}], "explanations": {"供给": "正确答案。供给 gōng jǐ，意思是拿出物资供人使用。", "攻击": "gōngjī（第一声）与 gōng jǐ（第三声）第二音节声调不同，意思是攻击。", "恭喜": "xǐ 与 jǐ 声母不同（x 与 j），声调相同，意思是祝贺。", "功绩": "jì（第四声）与 jǐ（第三声）声调不同，意思是功绩。"}, "sentence_index": null, "correct_answer": "供给"}, "level_3": {"options": [{"text": "供给", "is_correct": true, "explanation": "“供给”指拿出电力供全城使用，与“这家工厂”“全城的电”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃全城的电”。"}, {"text": "聊天", "is_correct": false, "explanation": "配价：“聊天”是不及物动词，不能带“全城的电”作宾语。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的对象是可以赏玩的事物，电不能被欣赏。"}], "explanations": {"供给": "“供给”指拿出电力供全城使用，与“这家工厂”“全城的电”相符。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃全城的电”。", "聊天": "配价：“聊天”是不及物动词，不能带“全城的电”作宾语。", "欣赏": "语义：“欣赏”的对象是可以赏玩的事物，电不能被欣赏。"}, "sentence_index": 0, "correct_answer": "供给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师每周向学生供给一个难题。", "explanation": "这里应该用〈布置〉。供给指拿出物资、钱财给人用，难题要说布置。"}, {"text": "这次旅行供给了我很多快乐。", "explanation": "这里应该用〈带给〉。供给指把物资、钱财拿出来给人用，快乐是感受，不能被供给。"}, {"text": "志愿者给灾区供给了很多温暖。", "explanation": "这里应该用〈送〉。供给面向物资、能源，温暖是情感，应说“给灾区送温暖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "供给", "is_correct": true, "explanation": "“供给”指定期拿出生活费给人用，与“爸爸每月”“生活费”相符。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的宾语应是人或行为，不能说“批评生活费”。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象应是可以洗涤的东西，生活费不能被洗。"}, {"text": "赚", "is_correct": false, "explanation": "语义：“赚”是自己挣得钱，句中是给我钱，不能说“赚我生活费”。"}], "explanations": {"供给": "“供给”指定期拿出生活费给人用，与“爸爸每月”“生活费”相符。", "批评": "搭配：“批评”的宾语应是人或行为，不能说“批评生活费”。", "洗": "搭配：“洗”的对象应是可以洗涤的东西，生活费不能被洗。", "赚": "语义：“赚”是自己挣得钱，句中是给我钱，不能说“赚我生活费”。"}, "sentence_index": 6, "correct_answer": "供给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校供给了他很多鼓励。", "explanation": "这里应该用〈给予〉。供给用于物资、钱财，鼓励是抽象的情感，应说“给予鼓励”。"}, {"text": "法律供给公民言论自由。", "explanation": "这里应该用〈赋予〉。供给指拿出实物或钱财，权利、自由要说“赋予”。"}, {"text": "这门课供给了我很多兴趣。", "explanation": "这里应该用〈激发〉。兴趣要说“激发”，供给只用于物资、钱财等实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府供给给居民清洁的饮用水。", "corrected_sentence": "政府供给居民清洁的饮用水。", "error_description": "错误在于“供给”后多加了“给”。“供给”本身已含给予的意思，后面直接接服务对象和物品，不能再加“给”。正确说法是“政府供给居民清洁的饮用水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水站每天向居民的供给桶装水。", "corrected_sentence": "水站每天向居民供给桶装水。", "error_description": "错误在于“供给”前多加了结构助词“的”。“的”会把“供给”变成名词化的修饰成分，后面不能再接宾语“桶装水”，应说“水站每天向居民供给桶装水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76a3926b-a5e3-439d-81d9-235f61c47e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21462, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解", "is_correct": true, "explanation": "分解：把整体拆分成各个部分，与“构成”意思相反，构成反义。"}, {"text": "唱歌", "is_correct": false, "explanation": "与“构成”无反义关系：“唱歌”指用声音表演歌曲，与组合成整体无关。"}, {"text": "打扫", "is_correct": false, "explanation": "与“构成”无反义关系：“打扫”指清除垃圾、灰尘，与组合成整体无关。"}, {"text": "批评", "is_correct": false, "explanation": "与“构成”无反义关系：“批评”指指出缺点错误，与组合成整体无关。"}], "correct_answer": "分解", "explanations": {"分解": "分解：把整体拆分成各个部分，与“构成”意思相反，构成反义。", "唱歌": "与“构成”无反义关系：“唱歌”指用声音表演歌曲，与组合成整体无关。", "打扫": "与“构成”无反义关系：“打扫”指清除垃圾、灰尘，与组合成整体无关。", "批评": "与“构成”无反义关系：“批评”指指出缺点错误，与组合成整体无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21462, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分解", "is_correct": true, "explanation": "分解：把整体拆分成各个部分，与“构成”意思相反，构成反义。"}, {"text": "游泳", "is_correct": false, "explanation": "与“构成”无反义关系：“游泳”指在水中运动，与组合成整体无关。"}, {"text": "播种", "is_correct": false, "explanation": "与“构成”无反义关系：“播种”指把种子撒到土里，与组合成整体无关。"}, {"text": "报告", "is_correct": false, "explanation": "与“构成”无反义关系：“报告”指向他人陈述情况，与组合成整体无关。"}], "correct_answer": "分解", "explanations": {"分解": "分解：把整体拆分成各个部分，与“构成”意思相反，构成反义。", "游泳": "与“构成”无反义关系：“游泳”指在水中运动，与组合成整体无关。", "播种": "与“构成”无反义关系：“播种”指把种子撒到土里，与组合成整体无关。", "报告": "与“构成”无反义关系：“报告”指向他人陈述情况，与组合成整体无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21462, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不同的部分组合在一起成为一个整体。", "primary_collocate": null, "pronunciation": "gòu chéng", "ipa": "kou˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "水由氢和氧构成。", "target_word": "构成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子由五个词构成。", "target_word": "构成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小房子构成了一个村子。", "target_word": "构成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个队由十一个人构成。", "target_word": "构成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的颜色构成了这幅画。", "target_word": "构成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些点构成一条线。", "target_word": "构成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家庭由爸爸、妈妈和孩子构成。", "target_word": "构成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四个短句构成了这段话。", "target_word": "构成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市由三个区构成。", "target_word": "构成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多小事构成了我们的生活。", "target_word": "构成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "构成了", "label": "体标"}, {"form": "构成过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "各部分组合成一个整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e21988-a24b-41f5-92fd-a20a131657a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "构成", "is_correct": true, "explanation": "构成：把部分组合成整体，与“水由氢和氧……”相符。"}, {"text": "燃烧", "is_correct": false, "explanation": "语义：“燃烧”指物质剧烈发光发热地氧化，水由氢和氧“燃烧”而成，说法不通。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能说“水由氢和氧喝”。"}, {"text": "寻找", "is_correct": false, "explanation": "配价：“寻找”需要有施事（人）去找，氢和氧不能作施事，句子不成立。"}], "explanations": {"构成": "构成：把部分组合成整体，与“水由氢和氧……”相符。", "燃烧": "语义：“燃烧”指物质剧烈发光发热地氧化，水由氢和氧“燃烧”而成，说法不通。", "喝": "搭配：“喝”的对象是饮品，不能说“水由氢和氧喝”。", "寻找": "配价：“寻找”需要有施事（人）去找，氢和氧不能作施事，句子不成立。"}, "sentence_index": 0, "correct_answer": "构成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他构成了一名优秀的医生。", "explanation": "这里应该用〈成为〉。“构成”指部分组成整体，不能表示人的身份变化。"}, {"text": "我们构成了一次讨论。", "explanation": "这里应该用〈进行〉。讨论是人的行为，不是由部分组合成的整体，应说进行讨论。"}, {"text": "他构成了第一名。", "explanation": "这里应该用〈获得〉。名次是取得的，不是由部分组合而成，应说获得第一名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "构成", "is_correct": true, "explanation": "构成：部分组合成整体，与“家庭由爸爸、妈妈和孩子……”相符。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”的对象是动物，不能说“家庭由……饲养”。"}, {"text": "参观", "is_correct": false, "explanation": "语义：家庭不是可以去参观的地点，“由……参观”说法不通。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”需要表示起点的处所（由某地出发），“家庭由……出发”不成立。"}], "explanations": {"构成": "构成：部分组合成整体，与“家庭由爸爸、妈妈和孩子……”相符。", "饲养": "搭配：“饲养”的对象是动物，不能说“家庭由……饲养”。", "参观": "语义：家庭不是可以去参观的地点，“由……参观”说法不通。", "出发": "配价：“出发”需要表示起点的处所（由某地出发），“家庭由……出发”不成立。"}, "sentence_index": 6, "correct_answer": "构成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈构成了一次家庭聚会。", "explanation": "这里应该用〈组织〉。“构成”指部分组合成整体，不能表示主动安排活动。"}, {"text": "这个新政策构成了很多好处。", "explanation": "这里应该用〈带来〉。“好处”是结果，不是由部分组合成的整体，应说带来很多好处。"}, {"text": "他构成了一项新纪录。", "explanation": "这里应该用〈创造〉。纪录是创造或打破出来的，不是由部分组合而成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首歌三段旋律构成。", "corrected_sentence": "这首歌由三段旋律构成。", "error_description": "配价错误：表示由哪些部分组成时，“构成”前须用“由”引出组成部分，“由”不能省略，应说“由三段旋律构成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个班三十名学生构成。", "corrected_sentence": "这个班由三十名学生构成。", "error_description": "配价错误：表示由哪些部分组成时，“构成”前须用“由”引出组成部分，“由”不能省略，应说“由三十名学生构成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
