INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21468, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物最主要的、最开始的、最下面的部分。", "primary_collocate": null, "pronunciation": "jī chǔ", "ipa": "tɕi˥ ʈʂʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "学好汉语要先打好基础。", "target_word": "基础", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座楼的基础很深，所以很结实。", "target_word": "基础", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的数学基础不太好。", "target_word": "基础", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在这个基础上做了新的计划。", "target_word": "基础", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子的基础打得好，楼才不会倒。", "target_word": "基础", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有很好的英语基础，学法语很快。", "target_word": "基础", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基础不好，学新课会很难。", "target_word": "基础", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个练习是为了给你打基础。", "target_word": "基础", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的基础是学习成功的第一步。", "target_word": "基础", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在为新楼打基础。", "target_word": "基础", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "基礎", "label": "繁体"}, {"form": "基础上", "label": "复合"}, {"form": "基础课", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物最底层、最开始的部分，如学习或建筑的基础", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ebcdd33-4c2b-4870-aa27-7ac3753dba86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21468, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基础", "is_correct": true, "explanation": "正确答案。基础指事物最开始、最下面的部分，句中指学习的起点。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是称呼，不能“打好”，句子说的是学习的根基。"}, {"text": "礼貌", "is_correct": false, "explanation": "搭配：“打好”通常接基础、根基，不接礼貌。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物是送人的东西，不能“打好”，句子说的是学习的根基。"}], "explanations": {"基础": "正确答案。基础指事物最开始、最下面的部分，句中指学习的起点。", "名字": "语义：名字是称呼，不能“打好”，句子说的是学习的根基。", "礼貌": "搭配：“打好”通常接基础、根基，不接礼貌。", "礼物": "语义：礼物是送人的东西，不能“打好”，句子说的是学习的根基。"}, "sentence_index": 0, "correct_answer": "基础"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他住在楼的基础。", "explanation": "这里应该用〈底层〉。基础指事物最下面的根基部分，不指可以住人的楼层。"}, {"text": "汽车停在基础上。", "explanation": "这里应该用〈地面〉。基础指事物的根基，不是可以停车的平面。"}, {"text": "救灾队运来了大量基础。", "explanation": "这里应该用〈物资〉。基础指事物的根基，不是可以运送的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基础", "is_correct": true, "explanation": "正确答案。基础不好，学新课就会很难，句子说的是学习的根基。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子的好坏与学新课难不难无关，这一说法没有意义。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会影响学习难度，这一说法没有意义。"}, {"text": "电费", "is_correct": false, "explanation": "搭配：“不好”一般说状况或质量，不说电费不好。"}], "explanations": {"基础": "正确答案。基础不好，学新课就会很难，句子说的是学习的根基。", "房子": "语义：房子的好坏与学新课难不难无关，这一说法没有意义。", "桌子": "语义：桌子不会影响学习难度，这一说法没有意义。", "电费": "搭配：“不好”一般说状况或质量，不说电费不好。"}, "sentence_index": 6, "correct_answer": "基础"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把基础存进了银行。", "explanation": "这里应该用〈钱〉。基础指事物的根基，不是可以存进银行的东西。"}, {"text": "他用基础修好了自行车。", "explanation": "这里应该用〈工具〉。基础指事物最下面的部分，不是修理用的器具。"}, {"text": "工厂用基础生产产品。", "explanation": "这里应该用〈原料〉。基础不是生产时投入的材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家在这个基础继续努力。", "corrected_sentence": "大家在这个基础上继续努力。", "error_description": "错误：“在这个基础继续努力”。正确：“在这个基础上继续努力”。“在……基础上”是固定格式，“基础”后面要加“上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "盖新房子以前，要先盖好基础。", "corrected_sentence": "盖新房子以前，要先打好基础。", "error_description": "错误：“盖好基础”。正确：“打好基础”。“盖”用于房子、楼，建筑的基础要说“打基础”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
