INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种植园是一个很大的农场，专门种一种植物，比如茶叶或橡胶。", "primary_collocate": null, "pronunciation": "zhòng zhí yuán", "ipa": "ʈʂʊŋ˥˩ ʈʂɨ˧˥ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "这座种植园只种茶叶。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷以前在橡胶种植园干活。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种植园里一眼看不到头，全是绿色的茶树。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在种植园里走了一个小时。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个种植园每年都出口很多茶叶。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种植园的主人住在山下。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个种植园很大，有几百个工人。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们第一次去种植园，看到了很多橡胶树。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种植园里的甘蔗已经长高了。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想买一块地，开一个种植园。", "target_word": "种植园", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "茶叶种植园", "label": "复合"}, {"form": "橡胶种植园", "label": "复合"}, {"form": "種植園", "label": "繁体"}], "register": "中性", "sense_fingerprint": "专门种一种植物的大农场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abfcfa9a-a51d-42c1-8ec4-e1f3a9b309a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "种植园", "is_correct": true, "explanation": "正确：专门种一种植物的大农场，与“只种茶叶”的语义一致。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂不种茶叶，“这座工厂只种茶叶”与生产性质不符。"}, {"text": "宾馆", "is_correct": false, "explanation": "搭配：“只种茶叶”描述农业生产，宾馆的经营对象不是作物，二者不搭配。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是收藏书籍的场所，不种茶叶。"}], "explanations": {"种植园": "正确：专门种一种植物的大农场，与“只种茶叶”的语义一致。", "工厂": "语义：工厂不种茶叶，“这座工厂只种茶叶”与生产性质不符。", "宾馆": "搭配：“只种茶叶”描述农业生产，宾馆的经营对象不是作物，二者不搭配。", "图书馆": "语义：图书馆是收藏书籍的场所，不种茶叶。"}, "sentence_index": 0, "correct_answer": "种植园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "种植园今晚演出一部话剧，座位几乎全满了。", "explanation": "这里应该用〈剧院〉。种植园是很大的农场，专门种一种植物，不演出话剧；演出话剧、座位全满要用〈剧院〉。"}, {"text": "种植园里的工人每天生产零件，机器轰鸣。", "explanation": "这里应该用〈车间〉。种植园是专门种植一种植物的大农场，不生产零件；生产零件、机器轰鸣要用〈车间〉。"}, {"text": "种植园的地面上划满了车位线。", "explanation": "这里应该用〈停车场〉。种植园是很大的农场，地面上不划车位线；划满车位线的场地要用〈停车场〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种植园", "is_correct": true, "explanation": "正确：指大农场，“很大，有几百个工人”描述的是这类场所，句意通顺。"}, {"text": "宇宙", "is_correct": false, "explanation": "语义：宇宙不是可以雇佣工人的场所，“那个宇宙很大，有几百个工人”说不通。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“海洋”不与“几百个工人”这种人员数量描述搭配。"}, {"text": "星球", "is_correct": false, "explanation": "语义：星球是天体，不能有几百个工人在其中工作。"}], "explanations": {"种植园": "正确：指大农场，“很大，有几百个工人”描述的是这类场所，句意通顺。", "宇宙": "语义：宇宙不是可以雇佣工人的场所，“那个宇宙很大，有几百个工人”说不通。", "海洋": "搭配：“海洋”不与“几百个工人”这种人员数量描述搭配。", "星球": "语义：星球是天体，不能有几百个工人在其中工作。"}, "sentence_index": 6, "correct_answer": "种植园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想在街上开一个种植园，每天晚上都很热闹。", "explanation": "这里应该用〈酒吧〉。种植园是很大的农场，不在街上营业，也没有夜里的热闹；夜里热闹的营业场所要用〈酒吧〉。"}, {"text": "种植园每天早上都有很多人排队安检。", "explanation": "这里应该用〈机场〉。种植园是种植作物的大农场，没有安检；排队安检要用〈机场〉。"}, {"text": "种植园的展厅里陈列着很多古代文物。", "explanation": "这里应该用〈博物馆〉。种植园是种植作物的农场，不陈列文物；陈列古代文物的场所要用〈博物馆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那座种满了茶树种植园很大。", "corrected_sentence": "那座种满了茶树的种植园很大。", "error_description": "漏字：“种满了茶树”修饰“种植园”，中间要加“的”。错误形式是“种满了茶树种植园”，正确形式是“种满了茶树的种植园”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的哥哥一个橡胶种植园里工作。", "corrected_sentence": "他的哥哥在一个橡胶种植园里工作。", "error_description": "漏字：表示地点的“在”漏掉了。错误形式是“一个橡胶种植园里工作”，正确形式是“在一个橡胶种植园里工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce2e5616-33f2-42ed-b123-399b58aba24d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
