INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21472, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多小岛连在一起，叫群岛。", "primary_collocate": null, "pronunciation": "qún dǎo", "ipa": "tɕʰyn˧˥ tɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "海里有很多小岛，它们合起来叫群岛。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在地图上找到了这个群岛。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个群岛有二十个小岛，人很少。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐船去群岛玩，看到了很多小岛。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群岛里的每个小岛都很小。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个群岛的天气很热，一年四季都像夏天。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师指着地图说：“这些小岛是一个群岛。”", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去看那个群岛上的海和沙子。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那片群岛的小岛挨得很近，坐小船就能到。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个群岛里只有一个岛上有人住。", "target_word": "群岛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "群島", "label": "繁体"}], "register": "中性", "sense_fingerprint": "群岛：挨在一起的很多小岛（日常简单义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965d3399-3e60-46ea-aa3b-18edf6edc58a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群岛", "is_correct": true, "explanation": "正确：海里的许多小岛合起来叫群岛，与句中的描述一致。"}, {"text": "大陆", "is_correct": false, "explanation": "体貌：大陆是连成一片的大块陆地，与分散的小岛不符。"}, {"text": "湖泊", "is_correct": false, "explanation": "语义：湖泊是陆上的水域，不是海里小岛的合称。"}, {"text": "山脉", "is_correct": false, "explanation": "语义：山脉是连绵的山，不是小岛合起来的名称。"}], "explanations": {"群岛": "正确：海里的许多小岛合起来叫群岛，与句中的描述一致。", "大陆": "体貌：大陆是连成一片的大块陆地，与分散的小岛不符。", "湖泊": "语义：湖泊是陆上的水域，不是海里小岛的合称。", "山脉": "语义：山脉是连绵的山，不是小岛合起来的名称。"}, "sentence_index": 0, "correct_answer": "群岛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校旁边的群岛里有很多鱼，大家常去钓鱼。", "explanation": "这里应该用〈湖〉。群岛是海里的很多小岛，有水有鱼、能钓鱼的地方是湖。"}, {"text": "大海中间只有一个小小的群岛，上面有一棵树。", "explanation": "这里应该用〈小岛〉。群岛是很多小岛合在一起，只有一个岛不能叫群岛。"}, {"text": "这片群岛连着大陆，三面都是海。", "explanation": "这里应该用〈半岛〉。连着大陆、三面是海的陆地叫半岛，群岛是分开的很多小岛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群岛", "is_correct": true, "explanation": "正确：「这些小岛是一个」后接的是许多小岛的合称，即群岛。"}, {"text": "半岛", "is_correct": false, "explanation": "语义：半岛与大陆相连，不是独立小岛的合称。"}, {"text": "高原", "is_correct": false, "explanation": "体貌：高原是高起的大片陆地，外形与小岛不同。"}, {"text": "海峡", "is_correct": false, "explanation": "语义：海峡是两块陆地之间的水道，不是小岛的合称。"}], "explanations": {"群岛": "正确：「这些小岛是一个」后接的是许多小岛的合称，即群岛。", "半岛": "语义：半岛与大陆相连，不是独立小岛的合称。", "高原": "体貌：高原是高起的大片陆地，外形与小岛不同。", "海峡": "语义：海峡是两块陆地之间的水道，不是小岛的合称。"}, "sentence_index": 6, "correct_answer": "群岛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷家旁边的群岛水很清，夏天可以游泳。", "explanation": "这里应该用〈河〉。群岛是海里的很多小岛，水很清、可以游泳的是河。"}, {"text": "海里只有一个很小的岛，人们叫它群岛。", "explanation": "这里应该用〈小岛〉。只有一个岛不能叫群岛，群岛要有很多小岛。"}, {"text": "这些大山连在一起，叫群岛。", "explanation": "这里应该用〈山脉〉。连在一起的山叫山脉，群岛是海里的很多小岛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们乘船去那把群岛看海。", "corrected_sentence": "我们乘船去那个群岛看海。", "error_description": "量词错误：「群岛」应用量词「个」，「把」用于有柄的器具，不能用来计量群岛。错误形式：那把群岛；正确形式：那个群岛。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张群岛的岛屿都很小，适合露营。", "corrected_sentence": "这个群岛的岛屿都很小，适合露营。", "error_description": "量词错误：「群岛」应用量词「个」，「张」用于平面的东西，不能用来计量群岛。错误形式：这张群岛；正确形式：这个群岛。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
