INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21474, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很高的平地，上面很平。", "primary_collocate": null, "pronunciation": "gāo yuán", "ipa": "kau˥ yɛn˧˥", "syllable_count": 2, "sentences": [{"text": "云南有一片很大的高原。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片高原平平的，一眼看不到头。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高原上有很多牛和羊。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山后面是一片高原。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块高原比周围的地方高得多。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在高原上走了一天。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那片高原很高，上面很平。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机下面是一大片黄色的高原。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高原上的草地一直连到天边。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，很多人去高原旅游。", "target_word": "高原", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片高原", "label": "量词"}, {"form": "高原反应", "label": "复合"}], "register": "中性", "sense_fingerprint": "位置很高、顶面平坦的大片土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af58cd74-a966-4809-b2bd-5cb92529248a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21474, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高原", "is_correct": true, "explanation": "正确：“高原”指很高的平地，与“云南有一片很大的”相符。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：云南是内陆省份，没有“很大的海洋”。"}, {"text": "荒岛", "is_correct": false, "explanation": "语义：云南是内陆地区，没有大片的岛屿。"}, {"text": "星球", "is_correct": false, "explanation": "搭配：“星球”指天体，不能用来形容云南的一片土地。"}], "explanations": {"高原": "正确：“高原”指很高的平地，与“云南有一片很大的”相符。", "海洋": "语义：云南是内陆省份，没有“很大的海洋”。", "荒岛": "语义：云南是内陆地区，没有大片的岛屿。", "星球": "搭配：“星球”指天体，不能用来形容云南的一片土地。"}, "sentence_index": 0, "correct_answer": "高原"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山后面是一片高原，它的顶尖尖的，像一座山峰。", "explanation": "这里应该用〈山峰〉。高原顶面平坦，“顶尖尖的”与词义矛盾。"}, {"text": "这里是一片高原，面积只有几平方米，像个小土堆。", "explanation": "这里应该用〈土堆〉。高原是大片地区，面积只有几平方米的应说“土堆”。"}, {"text": "这里是一片高原，地势很低，一下雨就积水。", "explanation": "这里应该用〈低地〉。高原海拔高、地势高，与“地势很低，一下雨就积水”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高原", "is_correct": true, "explanation": "正确：“高原”顶面平坦，句中“很高，上面很平”正是对它的描述。"}, {"text": "平原", "is_correct": false, "explanation": "语义：“平原”地势低，与“很高”矛盾。"}, {"text": "山谷", "is_correct": false, "explanation": "语义：“山谷”地势低凹，与“很高，上面很平”矛盾。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“房间”不是地形，不能说“那片房间很高，上面很平”。"}], "explanations": {"高原": "正确：“高原”顶面平坦，句中“很高，上面很平”正是对它的描述。", "平原": "语义：“平原”地势低，与“很高”矛盾。", "山谷": "语义：“山谷”地势低凹，与“很高，上面很平”矛盾。", "房间": "搭配：“房间”不是地形，不能说“那片房间很高，上面很平”。"}, "sentence_index": 6, "correct_answer": "高原"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天，很多人去高原的深海里潜水。", "explanation": "这里应该用〈海洋〉。高原在陆地上，不会有深海，与“高原”矛盾。"}, {"text": "这片高原很深，河水在谷底奔流。", "explanation": "这里应该用〈峡谷〉。峡谷有深度，谷底才有河水奔流；高原顶面平坦，不能说“很深”。"}, {"text": "这块高原比周围的地方低得多，雨季常积水。", "explanation": "这里应该用〈洼地〉。洼地地势低于周围；高原海拔高于周围，与“比周围低得多”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天的时候，我们在一条高原上宿营。", "corrected_sentence": "夏天的时候，我们在一片高原上宿营。", "error_description": "量词错误：“条”用于细长的东西，高原是大片土地，应该用“片”，应说“一片高原”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那片高原的上有很多牛羊。", "corrected_sentence": "那片高原上有很多牛羊。", "error_description": "错误：方位词“上”应直接接在“高原”后面，中间不能加“的”。应说“那片高原上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
