INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21482, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很特别，跟别人不一样。", "primary_collocate": null, "pronunciation": "dú tè", "ipa": "tu˧˥ tʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这只小狗的叫声很独特，不像别的狗。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法很独特，老师也很喜欢。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的颜色很独特，别人都没有。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有一个独特的名字，全班只有她叫这个。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋糕的样子很独特，像一只小猫。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走路的样子很独特，我一看就认识他。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店很独特，里面卖的东西别处买不到。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌的方式很独特，跟别人不一样。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校有一个独特的花园，里面种着很多树。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子画的画很独特，用了很多颜色。", "target_word": "独特", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "独特性", "label": "复合"}, {"form": "獨特", "label": "繁体"}], "register": "中性", "sense_fingerprint": "独特：很特别、跟别人不一样（日常简单义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965d3399-3e60-46ea-aa3b-18edf6edc58a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独特", "is_correct": true, "explanation": "独特：很特别、跟别人不一样，正符合“不像别的狗”的语境。"}, {"text": "整洁", "is_correct": false, "explanation": "语义：“整洁”说干净有序，叫声不能整洁。"}, {"text": "苦涩", "is_correct": false, "explanation": "语义：“苦涩”说味道，叫声不能苦涩。"}, {"text": "方正", "is_correct": false, "explanation": "体貌：“方正”说形状或外形，不能用来形容叫声。"}], "explanations": {"独特": "独特：很特别、跟别人不一样，正符合“不像别的狗”的语境。", "整洁": "语义：“整洁”说干净有序，叫声不能整洁。", "苦涩": "语义：“苦涩”说味道，叫声不能苦涩。", "方正": "体貌：“方正”说形状或外形，不能用来形容叫声。"}, "sentence_index": 0, "correct_answer": "独特"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "独特的同学没有交作业，老师很生气。", "explanation": "这里应该用〈个别〉。“个别”指少数几个；“独特”指与众不同，不能表示数量少。"}, {"text": "这个孩子有独特需要，需要老师特别照顾。", "explanation": "这里应该用〈特殊〉。“特殊需要”是固定说法，指特别的需求；“独特”不能这样组成固定搭配。"}, {"text": "这个孩子很独特，自己洗衣服做饭。", "explanation": "这里应该用〈独立〉。“独立”指不依赖别人；“独特”指与众不同，这里不表示这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独特", "is_correct": true, "explanation": "独特：与众不同，正好说明小店的东西别处买不到。"}, {"text": "冰凉", "is_correct": false, "explanation": "语义：“冰凉”说温度，不能用来形容一家小店。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”形容人不说话，小店不能沉默。"}, {"text": "柔软", "is_correct": false, "explanation": "体貌：“柔软”形容质地，不能用来形容一家小店。"}], "explanations": {"独特": "独特：与众不同，正好说明小店的东西别处买不到。", "冰凉": "语义：“冰凉”说温度，不能用来形容一家小店。", "沉默": "语义：“沉默”形容人不说话，小店不能沉默。", "柔软": "体貌：“柔软”形容质地，不能用来形容一家小店。"}, "sentence_index": 6, "correct_answer": "独特"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是全班独特的男生。", "explanation": "这里应该用〈唯一〉。“唯一”指只有一个；“独特”指与众不同，不能表示只有一个。"}, {"text": "他今天很独特，一直不说话，不知道怎么了。", "explanation": "这里应该用〈奇怪〉。“奇怪”指反常、让人不明白；“独特”指与众不同，不用来说人一时的反常表现。"}, {"text": "这次考试他的成绩很独特，大家都很惊讶。", "explanation": "这里应该用〈优异〉。“优异”形容成绩好；“独特”指与别的不同，不用来评价成绩的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的笑声很的独特。", "corrected_sentence": "她的笑声很独特。", "error_description": "错误：“很”和“独特”之间多了“的”。正确：“很独特”，程度副词直接修饰形容词，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小店的货太很独特。", "corrected_sentence": "这个小店的货很独特。", "error_description": "错误：“独特”前面多了一个“太”，“太”和“很”两个程度副词不能连用。正确：“很独特”，形容词“独特”前只用一个程度副词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
