INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21486, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "拥有某种性质、特点或能力。", "primary_collocate": null, "pronunciation": "jù yǒu", "ipa": "tɕy⁵¹ joʊ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "这座老城具有很长的历史。", "target_word": "具有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书具有很大的学习价值。", "target_word": "具有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他具有很强的工作能力。", "target_word": "具有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果具有特别的香味。", "target_word": "具有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国菜具有各地不同的特色。", "target_word": "具有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事对我们具有重要的意义。", "target_word": "具有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师应该具有耐心。", "target_word": "具有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇具有独特的魅力。", "target_word": "具有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药不具有治病的作用。", "target_word": "具有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就具有画画的才能。", "target_word": "具有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不具有", "label": "否定"}, {"form": "具有着", "label": "体标（着）"}], "register": "书面", "sense_fingerprint": "拥有某种性质、特点或能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37e3a5b6-7c2b-4c3d-9201-526e04e5c049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21486, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "具有", "is_correct": true, "explanation": "具有指拥有某种性质，老城拥有很长的历史，与句意相符。"}, {"text": "进行", "is_correct": false, "explanation": "搭配：“进行”后面接的是活动，不能接“很长的历史”。"}, {"text": "发生", "is_correct": false, "explanation": "搭配：历史不会“发生”，“发生”不能与“很长的历史”搭配。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”是快速移动，与“老城的历史”无关，句意不通。"}], "explanations": {"具有": "具有指拥有某种性质，老城拥有很长的历史，与句意相符。", "进行": "搭配：“进行”后面接的是活动，不能接“很长的历史”。", "发生": "搭配：历史不会“发生”，“发生”不能与“很长的历史”搭配。", "跑": "语义：“跑”是快速移动，与“老城的历史”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "具有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我具有一辆自行车。", "explanation": "这里应该用〈拥有〉。具有指事物本身带有的性质、特点，拥有用于实物或财产，应说“我拥有一辆自行车”。"}, {"text": "瓶子里具有饮料。", "explanation": "这里应该用〈装有〉。具有指性质、特点，瓶子里盛着东西要用“装有”。"}, {"text": "我家具有一只猫。", "explanation": "这里应该用〈有〉。具有用于抽象的性质或特点，家里养猫这样的具体事物要用“有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21486, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "具有", "is_correct": true, "explanation": "具有指拥有某种性质，好老师应该拥有耐心，与句意相符。"}, {"text": "缺乏", "is_correct": false, "explanation": "语义：“应该”表示要求，“应该缺乏耐心”与句意相反，说不通。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于器物，不能与“耐心”搭配。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”用于具体的东西，不能说打碎耐心。"}], "explanations": {"具有": "具有指拥有某种性质，好老师应该拥有耐心，与句意相符。", "缺乏": "语义：“应该”表示要求，“应该缺乏耐心”与句意相反，说不通。", "修理": "搭配：“修理”用于器物，不能与“耐心”搭配。", "打碎": "搭配：“打碎”用于具体的东西，不能说打碎耐心。"}, "sentence_index": 6, "correct_answer": "具有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于具有了一份工作。", "explanation": "这里应该用〈得到〉。具有指本身带有的性质、能力，获得工作要用“得到”。"}, {"text": "这位老人具有一个孙子。", "explanation": "这里应该用〈有〉。具有指性质、特点，家人关系要用“有”。"}, {"text": "学习外语具有耐心。", "explanation": "这里应该用〈需要〉。具有指人或事物本身带有的性质，说学习需要某种条件，要用“需要”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇被具有悠久的历史文化。", "corrected_sentence": "这个小镇具有悠久的历史文化。", "error_description": "错误：“具有”是领有义动词，不能用于“被”字句。去掉“被”，应说“这个小镇具有悠久的历史文化。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种材料具有导电。", "corrected_sentence": "这种材料具有导电的性能。", "error_description": "错误：“具有”后面要接名词性宾语，不能直接接动词“导电”。正确应说“这种材料具有导电的性能。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
