INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西吃起来、闻起来特别的味道。", "primary_collocate": null, "pronunciation": "fēng wèi", "ipa": "fɤŋ˥ weɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这种奶酪的风味很特别。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯咖啡风味很好，有点果香。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加一点柠檬，鱼的风味会更好。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火锅的风味和别的菜很不一样。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的蛋糕保留了牛奶原来的风味。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最喜欢吃有海鲜风味的面条。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶放久了，风味就变淡了。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用新鲜的香草做出了特别的风味。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶酱油的风味比那瓶浓。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们买了几种不同风味的冰淇淋。", "target_word": "风味", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种风味", "label": "量词"}, {"form": "風味", "label": "繁体"}], "register": "中性", "sense_fingerprint": "食物吃起来、闻起来的特别味道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058d721c-6fd8-4b0f-a130-3d7cc342e209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风味", "is_correct": true, "explanation": "正确：“风味”指奶酪吃起来的特别味道，与“很特别”相合。"}, {"text": "书包", "is_correct": false, "explanation": "语义：奶酪不是书包，“这种奶酪的书包很特别”说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "配价：“脾气”要求有生命的人作主语，不能以奶酪为主语。"}, {"text": "身高", "is_correct": false, "explanation": "语义：奶酪不具备身高，“很特别”不能修饰身高。"}], "explanations": {"风味": "正确：“风味”指奶酪吃起来的特别味道，与“很特别”相合。", "书包": "语义：奶酪不是书包，“这种奶酪的书包很特别”说不通。", "脾气": "配价：“脾气”要求有生命的人作主语，不能以奶酪为主语。", "身高": "语义：奶酪不具备身高，“很特别”不能修饰身高。"}, "sentence_index": 0, "correct_answer": "风味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块饼干的风味很脆。", "explanation": "这里应该用〈口感〉。风味指滋味和特色，“脆”形容咬下去的质地，要用“口感”。"}, {"text": "这件衣服的风味很漂亮。", "explanation": "这里应该用〈外观〉。风味指食物的滋味，衣服好看要说“外观漂亮”。"}, {"text": "这块布的风味很柔软。", "explanation": "这里应该用〈质地〉。风味指滋味，“柔软”描写布料的质地，要用“质地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风味", "is_correct": true, "explanation": "正确：“放久了”之后“变淡”的是茶的滋味与香气，与“风味”的含义相合。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：茶放久后变淡的是滋味，不是硬度，“硬度变淡”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“变淡”不与“价格”搭配，价格可以涨跌，不能“变淡”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“变淡”说的是滋味或浓度的减弱，温度不会“变淡”。"}], "explanations": {"风味": "正确：“放久了”之后“变淡”的是茶的滋味与香气，与“风味”的含义相合。", "硬度": "语义：茶放久后变淡的是滋味，不是硬度，“硬度变淡”说不通。", "价格": "搭配：“变淡”不与“价格”搭配，价格可以涨跌，不能“变淡”。", "温度": "语义：“变淡”说的是滋味或浓度的减弱，温度不会“变淡”。"}, "sentence_index": 6, "correct_answer": "风味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯咖啡的风味很烫。", "explanation": "这里应该用〈温度〉。风味指滋味和气味，咖啡的冷热要说“温度”，不能用“风味”。"}, {"text": "这锅菜的风味很贵。", "explanation": "这里应该用〈价格〉。风味指滋味和气味，菜的贵贱要说“价格”，不能用“风味”。"}, {"text": "这碗面的风味很红。", "explanation": "这里应该用〈颜色〉。风味指滋味和气味，面的颜色要说“颜色”，不能用“风味”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块奶酪有一朵特别的风味。", "corrected_sentence": "这块奶酪有一股特别的风味。", "error_description": "错在量词：“朵”用于花，不能修饰风味；风味（气味或滋味）可用“股”或“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这杯咖啡的风味变淡着。", "corrected_sentence": "这杯咖啡的风味变淡了。", "error_description": "错在动态助词：“变淡”说已经完成的变化，要用“了”。用“着”表示持续的状态，与句意不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
