INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21494, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种东西有很多不同的样子，比如苹果有不同的品种。", "primary_collocate": null, "pronunciation": "pǐn zhǒng", "ipa": "pʰin˨˩˦ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "苹果有很多不同的品种。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个市场卖的西瓜有三个品种。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "葡萄的品种不同，味道也不同。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色的品种比绿色的更甜。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想买哪个品种的米？", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉米有白色和黄色两个品种。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的牛奶品种不多，只有三种。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢吃这个品种的梨，水很多。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些茶叶品种都很受欢迎。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找一个容易养的花的品种。", "target_word": "品种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个品种", "label": "量词"}, {"form": "新品种", "label": "复合"}, {"form": "品種", "label": "繁体"}], "register": "中性", "sense_fingerprint": "同一种东西中样子不同的种类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058d721c-6fd8-4b0f-a130-3d7cc342e209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21494, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "品种", "is_correct": true, "explanation": "正确：“不同的品种”指同一种水果中样子不同的类别，与句意相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：苹果没有年龄，“不同的年龄”说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "配价：“脾气”要求有生命的人作主语，不能用于苹果。"}, {"text": "性格", "is_correct": false, "explanation": "语义：苹果不具备性格，“不同的性格”不成立。"}], "explanations": {"品种": "正确：“不同的品种”指同一种水果中样子不同的类别，与句意相合。", "年龄": "语义：苹果没有年龄，“不同的年龄”说不通。", "脾气": "配价：“脾气”要求有生命的人作主语，不能用于苹果。", "性格": "语义：苹果不具备性格，“不同的性格”不成立。"}, "sentence_index": 0, "correct_answer": "品种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个果园里的苹果品种很吵。", "explanation": "这里应该用〈声音〉。品种指类别，“吵”说的是声音，不能用“品种”。"}, {"text": "这个果园里的苹果品种很重。", "explanation": "这里应该用〈重量〉。品种指类别，苹果的轻重要说“重量”，不能用“品种”。"}, {"text": "这个果园里的苹果品种很咸。", "explanation": "这里应该用〈味道〉。品种指类别，苹果的咸甜要说“味道”，不能用“品种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "品种", "is_correct": true, "explanation": "正确：“品种不多”指类别少，与“只有三种”相合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“不多”说的是类别数量，不能与“价格”搭配。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不能按种数计，“只有三种”说不通。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：牛奶的寿命与种数无关，“寿命只有三种”不成立。"}], "explanations": {"品种": "正确：“品种不多”指类别少，与“只有三种”相合。", "价格": "搭配：“不多”说的是类别数量，不能与“价格”搭配。", "温度": "语义：温度不能按种数计，“只有三种”说不通。", "寿命": "语义：牛奶的寿命与种数无关，“寿命只有三种”不成立。"}, "sentence_index": 6, "correct_answer": "品种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想找一个品种很浓的花。", "explanation": "这里应该用〈花香〉。“浓”说的是气味，“品种”不指气味。"}, {"text": "他想找一个品种很快的花。", "explanation": "这里应该用〈生长速度〉。“快”说的是生长的速度，“品种”不表示速度。"}, {"text": "他想找一个品种很长的花。", "explanation": "这里应该用〈花期〉。“长”说的是时间的长短，“品种”不指时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个果园里有两座品种的梨。", "corrected_sentence": "这个果园里有两个品种的梨。", "error_description": "错在量词：“品种”要用通用量词“个”，“座”用于山、楼等大型物体，不能用于品种。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家农场今年培育了一条新品种的西瓜。", "corrected_sentence": "这家农场今年培育了一个新品种的西瓜。", "error_description": "错在量词：“品种”用量词“个”，“条”用于长形的东西，不能用于品种。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
