INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21496, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种硬纸片，上面可以写字、画画。", "primary_collocate": null, "pronunciation": "kǎ", "ipa": "kʰa˨˩˦", "syllable_count": 1, "sentences": [{"text": "老师让我们在卡上写自己的名字。", "target_word": "卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在一张白卡上画了一只小猫。", "target_word": "卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张卡很硬，不容易弯。", "target_word": "卡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把卡剪成了小小的圆形。", "target_word": "卡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在卡上写字，再贴在墙上。", "target_word": "卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用笔在这张卡上写下你的愿望。", "target_word": "卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿出一张卡，画了一幅画。", "target_word": "卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种卡是纸做的，可以写字。", "target_word": "卡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把词写在卡上，每天看一看。", "target_word": "卡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有一叠空白的卡，还有彩笔。", "target_word": "卡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张卡", "label": "量词"}, {"form": "卡片", "label": "复合"}], "register": "中性", "sense_fingerprint": "可以写字、画画的硬纸片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058d721c-6fd8-4b0f-a130-3d7cc342e209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21496, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "卡", "is_correct": true, "explanation": "卡（kǎ）：一种硬纸片，可以写字、画画。"}, {"text": "考", "is_correct": false, "explanation": "kǎo（第三声）与 kǎ 的韵母不同（ao / a），意思是考试。"}, {"text": "砍", "is_correct": false, "explanation": "kǎn（第三声）与 kǎ 的韵母不同（an / a），意思是用刀斧砍。"}, {"text": "咖", "is_correct": false, "explanation": "kā（第一声）与 kǎ 仅声调不同，指咖啡的“咖”。"}], "explanations": {"卡": "卡（kǎ）：一种硬纸片，可以写字、画画。", "考": "kǎo（第三声）与 kǎ 的韵母不同（ao / a），意思是考试。", "砍": "kǎn（第三声）与 kǎ 的韵母不同（an / a），意思是用刀斧砍。", "咖": "kā（第一声）与 kǎ 仅声调不同，指咖啡的“咖”。"}, "sentence_index": null, "correct_answer": "卡"}, "level_3": {"options": [{"text": "卡", "is_correct": true, "explanation": "卡：可以在上面写字的硬纸片。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能被用来写字，“写名字”需要可书写的平面。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不是可以书写的平面，“在影子上写名字”说不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“在……上写”的处所要是可书写的平面，不说在时间上写。"}], "explanations": {"卡": "卡：可以在上面写字的硬纸片。", "声音": "语义：声音不能被用来写字，“写名字”需要可书写的平面。", "影子": "语义：影子不是可以书写的平面，“在影子上写名字”说不通。", "时间": "搭配：“在……上写”的处所要是可书写的平面，不说在时间上写。"}, "sentence_index": 0, "correct_answer": "卡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用这张卡煮了一锅粥。", "explanation": "这里应该用〈米〉。卡片是硬纸，不能煮，“煮”搭配的是米、菜等食材。"}, {"text": "她用这张卡梳了梳头发。", "explanation": "这里应该用〈梳子〉。卡片不能用来梳头，“梳”搭配的是梳子等工具。"}, {"text": "他拿这张卡去钓鱼了。", "explanation": "这里应该用〈鱼竿〉。卡片不能用来钓鱼，钓鱼要用鱼竿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21496, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "卡", "is_correct": true, "explanation": "卡（kǎ）：一种硬纸片，可以写字、画画。"}, {"text": "烤", "is_correct": false, "explanation": "kǎo（第三声）与 kǎ 的韵母不同（ao / a），意思是用火加热食物。"}, {"text": "咔", "is_correct": false, "explanation": "kā（第一声）与 kǎ 仅声调不同，“咔”多用于象声词，如“咔嚓”。"}, {"text": "哈", "is_correct": false, "explanation": "hǎ（第三声）与 kǎ 仅声母不同（h / k），如“哈腰”。"}], "explanations": {"卡": "卡（kǎ）：一种硬纸片，可以写字、画画。", "烤": "kǎo（第三声）与 kǎ 的韵母不同（ao / a），意思是用火加热食物。", "咔": "kā（第一声）与 kǎ 仅声调不同，“咔”多用于象声词，如“咔嚓”。", "哈": "hǎ（第三声）与 kǎ 仅声母不同（h / k），如“哈腰”。"}, "sentence_index": null, "correct_answer": "卡"}, "level_3": {"options": [{"text": "卡", "is_correct": true, "explanation": "卡：可以在上面画画的硬纸片。"}, {"text": "床", "is_correct": false, "explanation": "搭配：“拿出”的宾语要能被拿起来，床不能被拿出。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发不能拿出来用于画画，句中要的是可以作画的纸片。"}, {"text": "网", "is_correct": false, "explanation": "语义：网不能用来画画，句中要的是可以作画的纸片。"}], "explanations": {"卡": "卡：可以在上面画画的硬纸片。", "床": "搭配：“拿出”的宾语要能被拿起来，床不能被拿出。", "沙发": "语义：沙发不能拿出来用于画画，句中要的是可以作画的纸片。", "网": "语义：网不能用来画画，句中要的是可以作画的纸片。"}, "sentence_index": 6, "correct_answer": "卡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张卡很香，闻起来很舒服。", "explanation": "这里应该用〈花〉。卡片没有香味，“香”形容花、食物等。"}, {"text": "他骑着这张卡去上学了。", "explanation": "这里应该用〈自行车〉。卡片不能骑，“骑”搭配的是自行车、马等。"}, {"text": "他在这张卡上煎了两个鸡蛋。", "explanation": "这里应该用〈锅〉。卡片不能用来煎东西，“煎”要用锅等炊具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在一只卡上写了一句话。", "corrected_sentence": "他在一张卡上写了一句话。", "error_description": "量词错误：硬纸片“卡”应用量词“张”，不能说“一只卡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上放着一只空白的卡。", "corrected_sentence": "桌上放着一张空白的卡。", "error_description": "量词错误：硬纸片“卡”应用量词“张”，不能说“一只卡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
