INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "就是一个小地方的天气，比如花园里的天气。", "primary_collocate": null, "pronunciation": "wēi qì hòu", "ipa": "wei˥ tɕʰi˥˩ xou˥˩", "syllable_count": 3, "sentences": [{"text": "我家的小花园有自己的微气候。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下很热，但这个山洞的微气候很凉。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的微气候让这里的花开得很早。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的阳台有一个温暖的微气候。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大树下面的微气候比马路上舒服。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小村子的微气候很特别，雨很多。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，每个公园都有不同的微气候。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿地的微气候会影响小动物的生活。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种花的人要注意阳台的微气候。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边小镇的微气候让冬天不太冷。", "target_word": "微气候", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "小地方自己的天气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '965d3399-3e60-46ea-aa3b-18edf6edc58a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微气候", "is_correct": true, "explanation": "微气候：小地方自己的天气，正符合“小花园有自己的”的语境。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的脾气特点，小花园没有自己的性格。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指买卖的钱数，小花园不能有自己的价格。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能用来形容小花园。"}], "explanations": {"微气候": "微气候：小地方自己的天气，正符合“小花园有自己的”的语境。", "性格": "语义：“性格”指人的脾气特点，小花园没有自己的性格。", "价格": "语义：“价格”指买卖的钱数，小花园不能有自己的价格。", "身高": "体貌：“身高”指人的高矮，不能用来形容小花园。"}, "sentence_index": 0, "correct_answer": "微气候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的微气候很新鲜，我们开窗吧。", "explanation": "这里应该用〈空气〉。“新鲜”形容空气；“微气候”指温度、湿度等气象条件，不能说新鲜。"}, {"text": "整个国家的微气候都很干燥。", "explanation": "这里应该用〈气候〉。“气候”指大范围的气候，“微气候”只指小地方。"}, {"text": "窗外有一把温暖的微气候。", "explanation": "这里不能用〈把〉。“把”用于有柄的器具，“微气候”应该用量词“种”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微气候", "is_correct": true, "explanation": "微气候：每个公园的小地方气候各不相同，符合句意。"}, {"text": "性别", "is_correct": false, "explanation": "语义：“性别”是人的性别分类，公园不能有性别。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”形容人的体形，不能用于公园。"}, {"text": "学历", "is_correct": false, "explanation": "语义：“学历”指受教育的经历，公园没有学历。"}], "explanations": {"微气候": "微气候：每个公园的小地方气候各不相同，符合句意。", "性别": "语义：“性别”是人的性别分类，公园不能有性别。", "身材": "体貌：“身材”形容人的体形，不能用于公园。", "学历": "语义：“学历”指受教育的经历，公园没有学历。"}, "sentence_index": 6, "correct_answer": "微气候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子的微气候很吵闹，我睡不着。", "explanation": "这里应该用〈环境〉。“环境”可指周围的声音和氛围，“微气候”只指温度、湿度等气象条件。"}, {"text": "会场的微气候很热烈，大家都在鼓掌。", "explanation": "这里应该用〈气氛〉。“热烈”形容气氛；“微气候”指小地方的天气，不能说热烈。"}, {"text": "山上有一座温暖的微气候。", "explanation": "这里不能用〈座〉。“座”用于山、楼等大型固定的东西，“微气候”应该用量词“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间小屋是自己的微气候。", "corrected_sentence": "这间小屋有自己的微气候。", "error_description": "错误：“有”表示拥有，这里用“是”不通。正确：“有自己的微气候”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "阳台有一只温暖的微气候。", "corrected_sentence": "阳台有一种温暖的微气候。", "error_description": "错误：“只”多用于动物，“微气候”应该用量词“种”。正确：“一种温暖的微气候”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28ac183d-b49c-48c3-b1f1-35d36b68bef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
