INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21500, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你做过的事情，或者你遇到过的事情。", "primary_collocate": null, "pronunciation": "jīng lì", "ipa": "tɕiŋ˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "我想听听你的经历。", "target_word": "经历", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是一次很特别的经历。", "target_word": "经历", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她跟我讲了她在中国的经历。", "target_word": "经历", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有教孩子的经历吗？", "target_word": "经历", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那次坐船的经历我永远不会忘。", "target_word": "经历", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他常常给朋友讲自己小时候的经历。", "target_word": "经历", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一段好的经历会让人快乐很久。", "target_word": "经历", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做老师的经历对我现在的工作很有帮助。", "target_word": "经历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把在山里迷路的经历写成了故事。", "target_word": "经历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有自己不同的经历。", "target_word": "经历", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "工作经历", "label": "复合"}, {"form": "經歷", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自己做过或遇到过的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9032895-3c87-4536-a6ce-a44d1ddecd4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经历", "is_correct": true, "explanation": "正确。“听听你的经历”指想听对方做过或遇到过的事情，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体的重量，不是可以“听”的内容。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“听”不能与“颜色”搭配，“听听你的颜色”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是外貌特征，不能用“听听”来说。"}], "explanations": {"经历": "正确。“听听你的经历”指想听对方做过或遇到过的事情，符合句意。", "体重": "语义：“体重”是身体的重量，不是可以“听”的内容。", "颜色": "搭配：“听”不能与“颜色”搭配，“听听你的颜色”说不通。", "身高": "体貌：“身高”是外貌特征，不能用“听听”来说。"}, "sentence_index": 0, "correct_answer": "经历"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在书店里买了很多经历。", "explanation": "这里应该用〈书籍〉。买到的是书籍，经历指亲身做过或遇到的事，不能用来买。"}, {"text": "这位学者提出了新的经历。", "explanation": "这里应该用〈理论〉。提出的是理论，指系统的观点和原理；经历指亲身做过或遇到的事，不能说“提出经历”。"}, {"text": "请按照经历上写的方法组装机器。", "explanation": "这里应该用〈说明书〉。说明书写着组装的方法；经历指亲身做过或遇到的事，上面不会“写”着方法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经历", "is_correct": true, "explanation": "正确。“一段好的经历”指令人难忘的亲身遭遇，能让人快乐很久，符合句意。"}, {"text": "学号", "is_correct": false, "explanation": "语义：“学号”是学生的编号，不能让人快乐很久。"}, {"text": "鞋码", "is_correct": false, "explanation": "搭配：“鞋码”是尺寸，不能用“段”计量，“一段好的鞋码”说不通。"}, {"text": "门牌号", "is_correct": false, "explanation": "语义：“门牌号”是地址编号，不是能让人快乐的事情。"}], "explanations": {"经历": "正确。“一段好的经历”指令人难忘的亲身遭遇，能让人快乐很久，符合句意。", "学号": "语义：“学号”是学生的编号，不能让人快乐很久。", "鞋码": "搭配：“鞋码”是尺寸，不能用“段”计量，“一段好的鞋码”说不通。", "门牌号": "语义：“门牌号”是地址编号，不是能让人快乐的事情。"}, "sentence_index": 6, "correct_answer": "经历"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "读完这本书，我的经历特别深。", "explanation": "这里应该用〈感受〉。感受指内心的体会，可以说“深”；经历指亲身遭遇的事，不能说“经历特别深”。"}, {"text": "运动员在比赛中打破了经历。", "explanation": "这里应该用〈纪录〉。打破的是纪录，指最好的成绩；经历指亲身做过或遇到的事，不能被“打破”。"}, {"text": "做了这些年的志愿者，我擦干净了很多经历。", "explanation": "这里应该用〈窗户〉。擦的是窗户这类有形的物体，经历指做过或遇到的事，不能擦，应说“擦干净了很多窗户”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很想知道你这些经历们的细节。", "corrected_sentence": "我很想知道你这些经历的细节。", "error_description": "后缀错误：“们”只用于指人的名词，不能加在“经历”后面。正确形式是“这些经历的细节”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他讲了一节很长的经历。", "corrected_sentence": "他讲了一段很长的经历。", "error_description": "量词错误：“经历”应该用量词“段”，“节”用于课程、车厢等，不能计量“经历”。正确形式是“一段很长的经历”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
