INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21502, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "必须做某事，或必须具备某种条件，表示有此必要。", "primary_collocate": null, "pronunciation": "xū", "ipa": "ɕy˥", "syllable_count": 1, "sentences": [{"text": "进图书馆需出示学生证。", "target_word": "需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机前需提前两个小时到机场。", "target_word": "需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办这个手续需带身份证和照片。", "target_word": "需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人每天需吃三次药。", "target_word": "需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛需先在网上报名。", "target_word": "需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花需每天浇水。", "target_word": "需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子上车后需系好安全带。", "target_word": "需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去那个国家旅游需办签证。", "target_word": "需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写完作业后需请家长签字。", "target_word": "需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路时需看红绿灯。", "target_word": "需", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "需要", "label": "复合"}, {"form": "需求", "label": "复合"}, {"form": "无需", "label": "复合"}], "register": "书面", "sense_fingerprint": "书面用语，表示必须有、必须做某事，常用于规定和提示", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33c7f637-619d-49ba-80ef-a53edb7b3254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21502, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "需", "is_correct": true, "explanation": "正确。需（xū）表示需要、必须有，是目标词。"}, {"text": "许", "is_correct": false, "explanation": "xǔ（第三声）与 xū（第一声）声调不同，意思是允许、许多。"}, {"text": "序", "is_correct": false, "explanation": "xù（第四声）与 xū（第一声）声调不同，意思是顺序。"}, {"text": "区", "is_correct": false, "explanation": "qū 与 xū 声母不同（q/x），声调相同，意思是区域。"}, {"text": "居", "is_correct": false, "explanation": "jū 与 xū 声母不同（j/x），声调相同，意思是居住。"}, {"text": "曲", "is_correct": false, "explanation": "qū 与 xū 声母不同（q/x），声调相同，意思是曲子、弯曲。"}], "explanations": {"需": "正确。需（xū）表示需要、必须有，是目标词。", "许": "xǔ（第三声）与 xū（第一声）声调不同，意思是允许、许多。", "序": "xù（第四声）与 xū（第一声）声调不同，意思是顺序。", "区": "qū 与 xū 声母不同（q/x），声调相同，意思是区域。", "居": "jū 与 xū 声母不同（j/x），声调相同，意思是居住。", "曲": "qū 与 xū 声母不同（q/x），声调相同，意思是曲子、弯曲。"}, "sentence_index": null, "correct_answer": "需"}, "level_3": {"options": [{"text": "需", "is_correct": true, "explanation": "正确。“进图书馆需出示学生证”表示必须出示，符合句意。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：“禁止”表示不允许，与句中要求出示学生证的意思相反。"}, {"text": "不应", "is_correct": false, "explanation": "语义：“不应”表示不该，与进图书馆需要出示学生证的常规要求相矛盾。"}, {"text": "允许", "is_correct": false, "explanation": "语义：“允许”表示准许，句子会变成许可义，与“需”表示的必须义不符。"}], "explanations": {"需": "正确。“进图书馆需出示学生证”表示必须出示，符合句意。", "禁止": "语义：“禁止”表示不允许，与句中要求出示学生证的意思相反。", "不应": "语义：“不应”表示不该，与进图书馆需要出示学生证的常规要求相矛盾。", "允许": "语义：“允许”表示准许，句子会变成许可义，与“需”表示的必须义不符。"}, "sentence_index": 0, "correct_answer": "需"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈，我需吃糖。", "explanation": "这里应该用〈要〉或〈想〉。需强调必须有或必要，孩子想吃糖是口语中的愿望，不能用“需”。"}, {"text": "我真需你今天能来。", "explanation": "这里应该用〈希望〉。需表示必要，表达对别人来的愿望要用“希望”。"}, {"text": "学生需在考场上看手机。", "explanation": "这里应该用〈不能〉。需表示必须，考场上禁止看手机，不能用“需”来说禁止的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21502, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "需", "is_correct": true, "explanation": "正确。需（xū）表示需要、必须有，是目标词。"}, {"text": "续", "is_correct": false, "explanation": "xù（第四声）与 xū（第一声）声调不同，意思是继续。"}, {"text": "绪", "is_correct": false, "explanation": "xù（第四声）与 xū（第一声）声调不同，意思是情绪、头绪。"}, {"text": "屈", "is_correct": false, "explanation": "qū 与 xū 声母不同（q/x），声调相同，意思是屈服、委屈。"}, {"text": "驱", "is_correct": false, "explanation": "qū 与 xū 声母不同（q/x），声调相同，意思是驱赶、驱动。"}], "explanations": {"需": "正确。需（xū）表示需要、必须有，是目标词。", "续": "xù（第四声）与 xū（第一声）声调不同，意思是继续。", "绪": "xù（第四声）与 xū（第一声）声调不同，意思是情绪、头绪。", "屈": "qū 与 xū 声母不同（q/x），声调相同，意思是屈服、委屈。", "驱": "qū 与 xū 声母不同（q/x），声调相同，意思是驱赶、驱动。"}, "sentence_index": null, "correct_answer": "需"}, "level_3": {"options": [{"text": "需", "is_correct": true, "explanation": "正确。“孩子上车后需系好安全带”表示必须系好，符合句意。"}, {"text": "不许", "is_correct": false, "explanation": "语义：“不许”表示禁止，与安全带必须系好的要求相反。"}, {"text": "座位", "is_correct": false, "explanation": "词性：“座位”是名词，不能放在动词“系好”前作助动词，句子不成立。"}, {"text": "窗户", "is_correct": false, "explanation": "词性：“窗户”是名词，不能放在动词“系好”前，句子不成立。"}], "explanations": {"需": "正确。“孩子上车后需系好安全带”表示必须系好，符合句意。", "不许": "语义：“不许”表示禁止，与安全带必须系好的要求相反。", "座位": "词性：“座位”是名词，不能放在动词“系好”前作助动词，句子不成立。", "窗户": "词性：“窗户”是名词，不能放在动词“系好”前，句子不成立。"}, "sentence_index": 6, "correct_answer": "需"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "红绿灯需我们过马路。", "explanation": "这里是把〈需〉误用为〈让〉：需表示主语需要某物，不能说“红绿灯需我们过马路”，句意颠倒。"}, {"text": "过马路时我需大声唱歌。", "explanation": "这里应该用〈可以〉。需表示必须，唱歌不是过马路的必需步骤。"}, {"text": "过马路时需闭上眼睛。", "explanation": "这里应该用〈不要〉。需表示必须，闭眼过马路不是必需，反而危险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "参加考试前带需准考证。", "corrected_sentence": "参加考试前需带准考证。", "error_description": "词序错误：“需”应放在“带”前面，说“需带准考证”，不说“带需准考证”，因为“需”表示必须，修饰后面的动作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "进实验室前需了戴上手套。", "corrected_sentence": "进实验室前需戴上手套。", "error_description": "“需”后不能加“了”。“需”表示必须，是动词，“需了戴上”不成立，应说“需戴上手套”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
