INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21504, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "太阳晒到东西上。", "primary_collocate": null, "pronunciation": "rì shài", "ipa": "ʐ̩˥˩ ʂaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "红色的窗帘经过多年日晒，颜色变浅了。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机放在车里，日晒会让电池变热。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把伞可以挡住日晒。", "target_word": "日晒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日晒之后，鱼干变得又硬又香。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳台上的花怕日晒，要放到树下。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期日晒和风吹，让这块木板裂开了。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的海边，日晒特别强。", "target_word": "日晒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日晒过后的被子，睡起来很舒服。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车的油漆最怕日晒，所以要停在阴凉处。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把稻谷放在院子里，靠日晒让它变干。", "target_word": "日晒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日晒雨淋", "label": "复合"}, {"form": "日曬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "太阳晒到东西上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058d721c-6fd8-4b0f-a130-3d7cc342e209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日晒", "is_correct": true, "explanation": "正确：日晒指太阳晒到东西上，窗帘长期被晒，颜色就会变浅，符合句意。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻不会使窗帘褪色，“颜色变浅”不是冷冻造成的结果，句意不通。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：窗帘不是被烹饪的东西，“烹饪”与“颜色变浅”毫无关系。"}, {"text": "翻新", "is_correct": false, "explanation": "搭配：窗帘通常说“换”，不说“翻新”；而且翻新会让东西变新，与“颜色变浅”相反。"}], "explanations": {"日晒": "正确：日晒指太阳晒到东西上，窗帘长期被晒，颜色就会变浅，符合句意。", "冷冻": "语义：冷冻不会使窗帘褪色，“颜色变浅”不是冷冻造成的结果，句意不通。", "烹饪": "语义：窗帘不是被烹饪的东西，“烹饪”与“颜色变浅”毫无关系。", "翻新": "搭配：窗帘通常说“换”，不说“翻新”；而且翻新会让东西变新，与“颜色变浅”相反。"}, "sentence_index": 0, "correct_answer": "日晒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "把湿毛巾放进烘干机里，靠日晒烘干。", "explanation": "这里应该用〈烘干〉。烘干靠机器加热，日晒靠太阳照射，烘干机里没有阳光，不能说“靠日晒烘干”。"}, {"text": "把肉放进冰箱，靠日晒保存。", "explanation": "这里应该用〈冷藏〉。冷藏靠低温保存，日晒靠太阳照射，冰箱里没有阳光，不能说“靠日晒保存”。"}, {"text": "这棵大树下很凉快，适合日晒。", "explanation": "这里应该用〈乘凉〉。乘凉是在大树的树荫下休息；日晒必须在阳光下进行，树下有阴影，所以“适合日晒”与“树下凉快”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日晒", "is_correct": true, "explanation": "正确：日晒指太阳照射，夏天的海边阳光强，所以“特别强”指的是日晒。"}, {"text": "夜色", "is_correct": false, "explanation": "搭配：“夜色”指夜晚的景象，程度一般说“浓”，不说“特别强”，且与白天的日照语境不合。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指人的高矮，与海边的天气和日照无关，句意不通。"}, {"text": "冰雹", "is_correct": false, "explanation": "语义：冰雹是从天上落下的冰块，不能说“冰雹特别强”来形容夏天海边的天气，句意不通。"}], "explanations": {"日晒": "正确：日晒指太阳照射，夏天的海边阳光强，所以“特别强”指的是日晒。", "夜色": "搭配：“夜色”指夜晚的景象，程度一般说“浓”，不说“特别强”，且与白天的日照语境不合。", "身高": "语义：身高指人的高矮，与海边的天气和日照无关，句意不通。", "冰雹": "语义：冰雹是从天上落下的冰块，不能说“冰雹特别强”来形容夏天海边的天气，句意不通。"}, "sentence_index": 6, "correct_answer": "日晒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生说这种药膏能很快治好日晒。", "explanation": "这里应该用〈晒伤〉。“治好”针对的是伤害，日晒只是照射的过程，不能被治好。"}, {"text": "阴天的时候，我们在院子里日晒。", "explanation": "这里应该用〈乘凉〉。阴天在院子里乘凉很自然；日晒必须有阳光直接照射，阴天没有直射的阳光，所以不能说“阴天日晒”。"}, {"text": "把湿衣服挂在屋里，靠日晒让它变干。", "explanation": "这里应该用〈晾干〉。晾干是把湿物挂在通风处自然变干，不需要阳光；日晒要靠太阳直接照射，屋里没有阳光，不能说“靠日晒让它变干”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块木板把日晒弄得颜色变深了。", "corrected_sentence": "这块木板被日晒弄得颜色变深了。", "error_description": "把/被误用：木板是受日晒影响的一方，应该用“被”，说“这块木板被日晒弄得颜色变深了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "日晒了过后的毯子，摸起来又软又暖。", "corrected_sentence": "日晒过后的毯子，摸起来又软又暖。", "error_description": "体标错误：“日晒过后”表示时间，“日晒”和“过后”中间不能加“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
