INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21506, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物独有的标志或样子，让人可以认出它来。", "primary_collocate": null, "pronunciation": "tè zhēng", "ipa": "tʰɤ˥˩ ʈʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这种鸟的特征是尾巴很长。", "target_word": "特征", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大眼睛是他最明显的特征。", "target_word": "特征", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察让目击者描述小偷的特征。", "target_word": "特征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种花有一个相同的特征。", "target_word": "特征", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你说说这只狗的特征。", "target_word": "特征", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "南方城市的特征是夏天又热又湿。", "target_word": "特征", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "熊猫的特征是黑眼圈和白色的身体。", "target_word": "特征", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照片上的人有什么特征？", "target_word": "特征", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些水果有一个共同的特征，都是甜的。", "target_word": "特征", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高个子是他们家人的特征。", "target_word": "特征", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个特征", "label": "量词"}, {"form": "外貌特征", "label": "复合"}, {"form": "主要特征", "label": "复合"}], "register": "书面", "sense_fingerprint": "能区别于其他事物的突出特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7679ce6-7410-49f6-bfdd-e5891d0d533a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特征", "is_correct": true, "explanation": "特征：事物独有的标志，此处指这种鸟显著的标志。"}, {"text": "习惯", "is_correct": false, "explanation": "语义：“习惯”指做事的习惯，不指鸟的身体样子。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”说色彩，不能说“尾巴很长”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指买卖的钱数，与鸟的样子无关。"}], "explanations": {"特征": "特征：事物独有的标志，此处指这种鸟显著的标志。", "习惯": "语义：“习惯”指做事的习惯，不指鸟的身体样子。", "颜色": "搭配：“颜色”说色彩，不能说“尾巴很长”。", "价格": "语义：“价格”指买卖的钱数，与鸟的样子无关。"}, "sentence_index": 0, "correct_answer": "特征"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的特征菜很好吃。", "explanation": "这里应该用〈特色〉。“特色”指独特的风味或风格，“特征”不用作“特色菜”的修饰语。"}, {"text": "红灯是停车的特征。", "explanation": "这里应该用〈标志〉。红灯表示停车要说标志，“特征”指事物独有的样子，不能这样用。"}, {"text": "她的特征是游泳，比赛拿过很多奖。", "explanation": "这里应该用〈特长〉。“特长”指擅长的技能，比赛获奖说明的是擅长，“特征”指可以认出事物的标志，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特征", "is_correct": true, "explanation": "特征：事物独有的标志，此处指熊猫的标志性外形。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”指称呼，不指熊猫身上的外形标志。"}, {"text": "食物", "is_correct": false, "explanation": "语义：“食物”指吃的东西，不是熊猫外形的描述。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”说的是重量，不能接“黑眼圈和白色的身体”这样的外形描述。"}], "explanations": {"特征": "特征：事物独有的标志，此处指熊猫的标志性外形。", "名字": "语义：“名字”指称呼，不指熊猫身上的外形标志。", "食物": "语义：“食物”指吃的东西，不是熊猫外形的描述。", "体重": "搭配：“体重”说的是重量，不能接“黑眼圈和白色的身体”这样的外形描述。"}, "sentence_index": 6, "correct_answer": "特征"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的特征很好听。", "explanation": "这里应该用〈笑声〉。“特征”指让人认出事物的标志，好听的是笑声，不能说“特征很好听”。"}, {"text": "两地的特征很远。", "explanation": "这里应该用〈距离〉。“特征”指事物独有的标志或样子，两地之间的远近要说距离。"}, {"text": "他的特征很高。", "explanation": "这里应该用〈工资〉。“特征”指事物独有的标志，数额高低要说工资，不能说“特征很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的外貌特征们很明显。", "corrected_sentence": "他的外貌特征很明显。", "error_description": "错用复数词尾：“们”只接指人的名词，“特征”是抽象名词，不能说“特征们”，应说“外貌特征”，即“他的外貌特征很明显”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种狗有一只明显的特征。", "corrected_sentence": "这种狗有一个明显的特征。", "error_description": "“特征”的量词应用“个”或“种”，“只”用于动物，不能用来数“特征”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21508, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21508, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21508, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把硬壳去掉，让里面的东西出来。", "primary_collocate": null, "pronunciation": "tuō ké", "ipa": "tʰwo˥ kʰɤ˧˥", "syllable_count": 2, "sentences": [{"text": "工人用机器给稻谷脱壳，得到大米。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花生要先脱壳，再放进锅里炒。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每天给几吨松子脱壳。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "燕麦脱壳以后，才可以磨成粉。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台小机器脱壳很快，一分钟能处理很多种子。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把晒干的稻谷送去脱壳。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "葵花籽脱壳后，里面的籽仁又小又白。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "稻谷脱壳时要小心，别把米弄碎。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一台机器，专门给豆子脱壳。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新收的稻谷脱壳以后，颜色有点黄。", "target_word": "脱壳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "脱了壳", "label": "体标"}, {"form": "脱壳机", "label": "复合"}], "register": "中性", "sense_fingerprint": "去掉谷物、种子等的硬壳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1845352-48be-48eb-9b3d-f37709a0cac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脱壳", "is_correct": true, "explanation": "正确。脱壳：去掉稻谷的硬壳，与“得到大米”的结果相符。"}, {"text": "开采", "is_correct": false, "explanation": "搭配：“开采”用于矿产、资源，不能用于稻谷。"}, {"text": "编织", "is_correct": false, "explanation": "配价：“编织”需要丝线、竹条等材料作对象，稻谷不能作其对象。"}, {"text": "熔化", "is_correct": false, "explanation": "语义：“熔化”指固体受热变为液体，与稻谷脱壳的加工结果不符。"}], "explanations": {"脱壳": "正确。脱壳：去掉稻谷的硬壳，与“得到大米”的结果相符。", "开采": "搭配：“开采”用于矿产、资源，不能用于稻谷。", "编织": "配价：“编织”需要丝线、竹条等材料作对象，稻谷不能作其对象。", "熔化": "语义：“熔化”指固体受热变为液体，与稻谷脱壳的加工结果不符。"}, "sentence_index": 0, "correct_answer": "脱壳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些苹果要先脱壳，再切成块。", "explanation": "这里应该用〈去皮〉。“脱壳”指去掉硬壳，苹果有皮而无硬壳，应说“去皮”。"}, {"text": "这些蔬菜要先脱壳，再下锅炒。", "explanation": "这里应该用〈脱水〉。“脱壳”指去掉硬壳，蔬菜没有硬壳，应说“脱水”去掉水分。"}, {"text": "秋天到了，树叶一片片脱壳了。", "explanation": "这里应该用〈脱落〉。树叶没有硬壳，“脱落”指掉下来，不能说脱壳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脱壳", "is_correct": true, "explanation": "正确。脱壳：去掉葵花籽的硬壳，露出籽仁，与“籽仁又小又白”相符。"}, {"text": "锻造", "is_correct": false, "explanation": "语义：“锻造”指金属加工，与葵花籽的处理不符。"}, {"text": "焊接", "is_correct": false, "explanation": "搭配：“焊接”用于金属等材料，不能用于葵花籽。"}, {"text": "雕刻", "is_correct": false, "explanation": "语义：“雕刻”指加工出花纹或形象，与“籽仁又小又白”的描述不符。"}], "explanations": {"脱壳": "正确。脱壳：去掉葵花籽的硬壳，露出籽仁，与“籽仁又小又白”相符。", "锻造": "语义：“锻造”指金属加工，与葵花籽的处理不符。", "焊接": "搭配：“焊接”用于金属等材料，不能用于葵花籽。", "雕刻": "语义：“雕刻”指加工出花纹或形象，与“籽仁又小又白”的描述不符。"}, "sentence_index": 6, "correct_answer": "脱壳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布要先脱壳，再染新颜色。", "explanation": "这里应该用〈脱色〉。“脱壳”指去掉硬壳，布料没有硬壳，应说“脱色”去掉原有颜色。"}, {"text": "这只鸡要先脱壳，再开膛。", "explanation": "这里应该用〈脱毛〉。鸡身上是毛，没有硬壳，不能用“脱壳”去掉鸡毛。"}, {"text": "这条鱼要先脱壳，再下锅煎。", "explanation": "这里应该用〈去鳞〉。鱼身上是鳞片，没有硬壳，不能说“脱壳”，应说“去鳞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民用机器稻谷脱壳，再去卖。", "corrected_sentence": "农民用机器给稻谷脱壳，再去卖。", "error_description": "错误：“脱壳”的对象“稻谷”前缺少介词“给”，应说“给稻谷脱壳”，不能直接说“机器稻谷脱壳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "核桃了脱壳后，要尽快晒干。", "corrected_sentence": "核桃脱壳后，要尽快晒干。", "error_description": "错误：动态助词“了”不能放在动词“脱壳”之前，写成“了脱壳”。这里不需要“了”，应说“核桃脱壳后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
