INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21510, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蜜是蜜蜂从花里采来放在蜂巢里的甜甜的东西。", "primary_collocate": null, "pronunciation": "mì", "ipa": "mi˥˩", "syllable_count": 1, "sentences": [{"text": "小熊最爱吃树上的蜜。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂飞到花上采蜜。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在热水里放了一勺蜜。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这罐蜜是奶奶从山里带来的。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把蜜涂在面包上。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜很甜，可是不能吃太多。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜂巢里藏着很多金黄的蜜。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢用蜜拌酸奶。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩嘴上沾着蜜。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喝茶的时候喜欢加一点蜜。", "target_word": "蜜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一罐蜜", "label": "量词"}, {"form": "一勺蜜", "label": "量词"}, {"form": "蜂蜜", "label": "复合"}, {"form": "蜜蜂", "label": "复合"}], "register": "中性", "sense_fingerprint": "蜜蜂采来放在蜂巢里的甜东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1845352-48be-48eb-9b3d-f37709a0cac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21510, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蜜", "is_correct": true, "explanation": "正确。蜜 mì 指蜜蜂从花里采来放在蜂巢里的甜东西。"}, {"text": "米", "is_correct": false, "explanation": "mǐ（第三声）与 mì（第四声）声调不同，意思是大米。"}, {"text": "迷", "is_correct": false, "explanation": "mí（第二声）与 mì（第四声）声调不同，意思是迷恋或迷路。"}, {"text": "币", "is_correct": false, "explanation": "bì 与 mì 声母不同（b 与 m），意思是货币。"}, {"text": "逆", "is_correct": false, "explanation": "nì 与 mì 声母不同（n 与 m），意思是相反、逆向。"}], "explanations": {"蜜": "正确。蜜 mì 指蜜蜂从花里采来放在蜂巢里的甜东西。", "米": "mǐ（第三声）与 mì（第四声）声调不同，意思是大米。", "迷": "mí（第二声）与 mì（第四声）声调不同，意思是迷恋或迷路。", "币": "bì 与 mì 声母不同（b 与 m），意思是货币。", "逆": "nì 与 mì 声母不同（n 与 m），意思是相反、逆向。"}, "sentence_index": null, "correct_answer": "蜜"}, "level_3": {"options": [{"text": "蜜", "is_correct": true, "explanation": "正确。蜜是甜的东西，小熊爱吃，与“树上的”语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：小熊不吃石头，石头不能作为食物。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“吃”一般不接“水”，要说“喝”。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不长在树上，与“树上的”语境矛盾。"}], "explanations": {"蜜": "正确。蜜是甜的东西，小熊爱吃，与“树上的”语境相符。", "石头": "语义：小熊不吃石头，石头不能作为食物。", "水": "搭配：“吃”一般不接“水”，要说“喝”。", "鱼": "语义：鱼不长在树上，与“树上的”语境矛盾。"}, "sentence_index": 0, "correct_answer": "蜜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵树上的蜜开得很漂亮。", "explanation": "这里应该用〈花〉。花会开放，蜜是甜的物质，不能说“开”。"}, {"text": "天冷了，他把蜜穿在身上。", "explanation": "这里应该用〈外套〉。外套可以穿在身上保暖；蜜是蜜蜂采来的甜东西，不能穿。"}, {"text": "屋子里的蜜点着了，火光很亮。", "explanation": "这里应该用〈蜡烛〉。蜡烛燃烧发光，蜜不能用来点燃照明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21510, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蜜", "is_correct": true, "explanation": "正确。蜜 mì 指蜜蜂从花里采来放在蜂巢里的甜东西。"}, {"text": "利", "is_correct": false, "explanation": "lì 与 mì 声母不同（l 与 m），意思是利益、锋利。"}, {"text": "地", "is_correct": false, "explanation": "dì 与 mì 声母不同（d 与 m），意思是土地。"}, {"text": "戏", "is_correct": false, "explanation": "xì 与 mì 声母不同（x 与 m），意思是戏剧。"}, {"text": "避", "is_correct": false, "explanation": "bì 与 mì 声母不同（b 与 m），意思是躲避。"}], "explanations": {"蜜": "正确。蜜 mì 指蜜蜂从花里采来放在蜂巢里的甜东西。", "利": "lì 与 mì 声母不同（l 与 m），意思是利益、锋利。", "地": "dì 与 mì 声母不同（d 与 m），意思是土地。", "戏": "xì 与 mì 声母不同（x 与 m），意思是戏剧。", "避": "bì 与 mì 声母不同（b 与 m），意思是躲避。"}, "sentence_index": null, "correct_answer": "蜜"}, "level_3": {"options": [{"text": "蜜", "is_correct": true, "explanation": "正确。蜂巢里储存的金黄色甜物质就是蜜。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：蜂巢里不会藏沙子，与采集来的甜物质不符。"}, {"text": "石子", "is_correct": false, "explanation": "语义：蜂巢里不会藏石子，与句中的语境不符。"}, {"text": "铁屑", "is_correct": false, "explanation": "搭配：“金黄的”一般不用来形容铁屑。"}], "explanations": {"蜜": "正确。蜂巢里储存的金黄色甜物质就是蜜。", "沙子": "语义：蜂巢里不会藏沙子，与采集来的甜物质不符。", "石子": "语义：蜂巢里不会藏石子，与句中的语境不符。", "铁屑": "搭配：“金黄的”一般不用来形容铁屑。"}, "sentence_index": 6, "correct_answer": "蜜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片竹林长得很蜜，林子里几乎没有光。", "explanation": "这里应该用〈密〉。“密”指稠密，竹林很密；“蜜”是蜂蜜，不表示稠密。"}, {"text": "这件事是他们俩的蜜，谁也不能说。", "explanation": "这里应该用〈秘密〉。“秘密”指不让人知道的事；“蜜”是蜂蜜，不能表示秘密。"}, {"text": "奶奶用蜜给孩子煮了一锅咸汤。", "explanation": "这里应该用〈盐〉。咸汤要用盐调味；蜜是甜的，不能用来调出咸味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶在粥里加了一块蜜。", "corrected_sentence": "奶奶在粥里加了一勺蜜。", "error_description": "量词错误：“蜜”是半流质，应说“一勺蜜”，不能用“块”，“块”用于固体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "养蜂人在箱子里收集了很多金黄的蜜的。", "corrected_sentence": "养蜂人在箱子里收集了很多金黄的蜜。", "error_description": "助词错误：“金黄的蜜”中的“的”已连接定语，“蜜”后不能再加“的”，句末多出“的”不通，应说“金黄的蜜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
