INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21512, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21512, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用火把面粉等食物做熟。", "primary_collocate": null, "pronunciation": "hōng bèi", "ipa": "xʊŋ˥ pei˥˩", "syllable_count": 2, "sentences": [{"text": "周末我在家烘焙蛋糕和饼干。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很喜欢烘焙，每个星期都做面包。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包要在烤箱里烘焙三十分钟。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店每天早上五点开始烘焙新鲜面包。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用面粉和鸡蛋烘焙了一块小蛋糕。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烘焙饼干的时候，别忘了先预热烤箱。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会烘焙以后，她常常送朋友自己做的点心。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课上跟老师学烘焙面包。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕烘焙好了，整个厨房都是甜甜的香味。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跟着老师烘焙小饼干，玩得很开心。", "target_word": "烘焙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "烘焙了", "label": "体标"}, {"form": "烘焙过", "label": "体标"}, {"form": "烘焙师", "label": "复合"}, {"form": "烘焙店", "label": "复合"}], "register": "中性", "sense_fingerprint": "用烤箱做熟面包、蛋糕等面点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1845352-48be-48eb-9b3d-f37709a0cac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21512, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌唱", "is_correct": false, "explanation": "语义：“歌唱”的对象是歌曲，蛋糕不能歌唱。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆，不能说驾驶蛋糕。"}, {"text": "烘焙", "is_correct": true, "explanation": "烘焙：在家用烤箱做熟蛋糕和饼干，符合语境。"}, {"text": "遵守", "is_correct": false, "explanation": "搭配：“遵守”的对象是规则或法律，不能说遵守饼干。"}], "explanations": {"歌唱": "语义：“歌唱”的对象是歌曲，蛋糕不能歌唱。", "驾驶": "搭配：“驾驶”的对象是车辆，不能说驾驶蛋糕。", "烘焙": "烘焙：在家用烤箱做熟蛋糕和饼干，符合语境。", "遵守": "搭配：“遵守”的对象是规则或法律，不能说遵守饼干。"}, "sentence_index": 0, "correct_answer": "烘焙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店每天晚上烘焙鸭子。", "explanation": "这里应该用〈烤〉。烘焙限于面包、饼干等面点，烤鸭子要用烤。"}, {"text": "他早上烘焙了两笼包子。", "explanation": "这里应该用〈蒸〉。烘焙是烤制面点的做法，包子要用蒸。"}, {"text": "妈妈在厨房烘焙了一桌菜。", "explanation": "这里应该用〈做〉。烘焙只用于烤制面包、饼干等面点，一桌菜要用做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捕捞", "is_correct": false, "explanation": "语义：“捕捞”是捉鱼，与做点心不相干。"}, {"text": "烘焙", "is_correct": true, "explanation": "烘焙：学会做面点后，常常送朋友自己做的点心，符合语境。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：“吵架”是争吵，不是可以学会做点心的技能。"}, {"text": "撒谎", "is_correct": false, "explanation": "语义：“撒谎”不是一种可以学会的技能，与做点心无关。"}], "explanations": {"捕捞": "语义：“捕捞”是捉鱼，与做点心不相干。", "烘焙": "烘焙：学会做面点后，常常送朋友自己做的点心，符合语境。", "吵架": "语义：“吵架”是争吵，不是可以学会做点心的技能。", "撒谎": "语义：“撒谎”不是一种可以学会的技能，与做点心无关。"}, "sentence_index": 6, "correct_answer": "烘焙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷在厨房烘焙面条。", "explanation": "这里应该用〈煮〉。烘焙靠干热烘烤使食材变熟变色，面条要用煮。"}, {"text": "厨师在大锅里烘焙青菜。", "explanation": "这里应该用〈炒〉。烘焙用于面点等干燥食材，青菜要用炒。"}, {"text": "奶奶慢慢烘焙粥。", "explanation": "这里应该用〈熬〉。烘焙靠干热烘烤使食材变熟变色，粥是液体，要用熬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我烘焙了过蛋糕。", "corrected_sentence": "我烘焙过蛋糕。", "error_description": "错误：表示经历的“过”前又加了“了”，写成“烘焙了过”。正确说法是“烘焙过”，表示经历只用“过”，不能同时用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她已经烘焙了完蛋糕。", "corrected_sentence": "她已经烘焙完了蛋糕。", "error_description": "错误：结果补语“完”与“了”的顺序颠倒，写成“烘焙了完”。正确说法是“烘焙完了”，结果补语“完”要紧跟动词，“了”放在最后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
