INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21514, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21514, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一件事之后紧跟着另一件事发生。", "primary_collocate": null, "pronunciation": "suí hòu", "ipa": "suei˧˥ xou˥˩", "syllable_count": 2, "sentences": [{"text": "飞机落了地，随后我们坐车去酒店。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她先洗了手，随后开始做饭。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯突然灭了，随后传来一声大叫。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥先到家，我随后也到了。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先敲了门，随后走了进去。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给朋友发了信息，他随后就回电话了。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束了，随后是颁奖。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板先讲几句话，随后请大家吃饭。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大风吹过，随后下起了大雨。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿起笔，随后在纸上写了名字。", "target_word": "随后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隨後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一件事之后紧跟着另一件事发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1845352-48be-48eb-9b3d-f37709a0cac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随后", "is_correct": true, "explanation": "正确。“随后”表示飞机落地之后紧接着坐车去酒店，与句中的先后顺序相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“飞机落了地”之后的连续动作不符。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不能与“飞机落了地”这种瞬时结果搭配。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从未发生，与句中已安排的具体动作矛盾。"}], "explanations": {"随后": "正确。“随后”表示飞机落地之后紧接着坐车去酒店，与句中的先后顺序相符。", "偶尔": "语义：“偶尔”表示不常发生，与“飞机落了地”之后的连续动作不符。", "一直": "搭配：“一直”表示持续，不能与“飞机落了地”这种瞬时结果搭配。", "从不": "语义：“从不”表示从未发生，与句中已安排的具体动作矛盾。"}, "sentence_index": 0, "correct_answer": "随后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上课以前，他随后把作业交了。", "explanation": "这里应该用〈先〉。“随后”表示在某事之后紧接着发生，“上课以前”指之前，两者矛盾。"}, {"text": "随后，我们先吃了饭。", "explanation": "这里应该用〈首先〉。“随后”需要前面已有事情发生，“先”表示最初，两者矛盾。"}, {"text": "他一边走路，随后一边打电话。", "explanation": "这里应删去〈随后〉，改为“他一边走路，一边打电话”。“随后”表示先后相继，“一边……一边”表示同时进行，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随后", "is_correct": true, "explanation": "正确。“随后”表示比赛结束之后紧接着颁奖，与句中的先后顺序相符。"}, {"text": "事先", "is_correct": false, "explanation": "语义：“事先”表示在某事之前，与“比赛结束了”之后才颁奖的顺序相反。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”表示从未如此，不与即将发生的颁奖搭配。"}, {"text": "原先", "is_correct": false, "explanation": "语义：“原先”指原来的情况，与比赛结束后的颁奖顺序不符。"}], "explanations": {"随后": "正确。“随后”表示比赛结束之后紧接着颁奖，与句中的先后顺序相符。", "事先": "语义：“事先”表示在某事之前，与“比赛结束了”之后才颁奖的顺序相反。", "从来": "搭配：“从来”表示从未如此，不与即将发生的颁奖搭配。", "原先": "语义：“原先”指原来的情况，与比赛结束后的颁奖顺序不符。"}, "sentence_index": 6, "correct_answer": "随后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们俩从小随后是好朋友。", "explanation": "这里应该用〈一直〉。“随后”表示一件事后紧接着另一件事，不能表示长期持续的状态。"}, {"text": "随后，他小时候住在农村。", "explanation": "这里应该用〈以前〉。“随后”要接在前一件事之后，不能用来说过去的情况。"}, {"text": "比赛开始以前，大家随后做了准备活动。", "explanation": "这里应该用〈事先〉。“随后”表示在某事之后，“比赛开始以前”是之前，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我先写完作业，随后的出去散步。", "corrected_sentence": "我先写完作业，随后出去散步。", "error_description": "助词错误：“随后”是副词，作状语后不能加“的”，应说“随后出去散步”，不能说“随后的出去散步”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她关上门，随后的拿起了包。", "corrected_sentence": "她关上门，随后拿起了包。", "error_description": "助词错误：“随后”是副词，作状语后不能加“的”，应说“随后拿起了包”，不能说“随后的拿起了包”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21516, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21516, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21516, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "经过一段过程之后，出现的最后结果。", "primary_collocate": null, "pronunciation": "zuì zhōng", "ipa": "tsuei˥˩ tʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "他努力了很久，最终成功了。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛最终以三比二结束。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们最终找到了回家的路。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想了很久，最终还是同意了。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨最终停了，我们出去玩。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过讨论，大家最终选了这个办法。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明最终没有去那家公司。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最终，他们赢得了比赛。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗最终回到了主人身边。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机最终在晚上十点到了。", "target_word": "最终", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "经过过程之后的最后结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bacc239c-df87-4c0c-a87d-ec7f9978f1b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最终", "is_correct": true, "explanation": "“最终”表示经过努力后的最后结果，符合“努力了很久”之后成功的语境。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立刻，与“努力了很久”的时间过程矛盾。"}, {"text": "先", "is_correct": false, "explanation": "语义：“先”表示先后顺序，句中没有另一个动作，句意不通。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：“赶紧”表示催促，后面接的是要马上做的动作，不能用于已经发生的结果。"}], "explanations": {"最终": "“最终”表示经过努力后的最后结果，符合“努力了很久”之后成功的语境。", "马上": "语义：“马上”表示立刻，与“努力了很久”的时间过程矛盾。", "先": "语义：“先”表示先后顺序，句中没有另一个动作，句意不通。", "赶紧": "搭配：“赶紧”表示催促，后面接的是要马上做的动作，不能用于已经发生的结果。"}, "sentence_index": 0, "correct_answer": "最终"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "最终，他吃了饭，再去工作。", "explanation": "这里应该用〈首先〉。“最终”表示结果出现在最后，后面不能接“再去工作”这样的后续动作。"}, {"text": "他最终一开始就放弃了，我们都很意外。", "explanation": "这里应该用〈一开始〉。“最终”表示结果出现在最后，与“一开始”的起点矛盾，应说“一开始就放弃了”。"}, {"text": "他最终刚才就走了，我没见到他。", "explanation": "这里应该用〈刚才〉。“最终”表示结果出现在最后，与“刚才”的过去时点矛盾，应说“刚才就走了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最终", "is_correct": true, "explanation": "“最终”表示结果在最后，符合“小明没有去那家公司”的结论。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：“赶紧”表示催促，不能与“没有去”组合，句子不通。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作正在进行，不能与“没有去”组合。"}, {"text": "特此", "is_correct": false, "explanation": "语域：“特此”是公文用语，用在日常叙述中不合适。"}], "explanations": {"最终": "“最终”表示结果在最后，符合“小明没有去那家公司”的结论。", "赶紧": "搭配：“赶紧”表示催促，不能与“没有去”组合，句子不通。", "正在": "搭配：“正在”表示动作正在进行，不能与“没有去”组合。", "特此": "语域：“特此”是公文用语，用在日常叙述中不合适。"}, "sentence_index": 6, "correct_answer": "最终"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一听到铃声，他最终飞快地冲出了教室。", "explanation": "这里应该用〈立即〉。“最终”表示结果出现在最后，与“一听到铃声”就行动的即时反应矛盾，应说“立即”。"}, {"text": "他最终在三秒钟内就算出了结果。", "explanation": "这里应该用〈很快〉。“最终”表示结果出现在最后，与“三秒钟内”这样的短时间矛盾，应说“很快”。"}, {"text": "他最终马上回了我的消息。", "explanation": "这里应该用〈随即〉代替“最终马上”。“最终”表示结果出现在最后，与“马上”的即时回应矛盾；“随即”表示紧接着发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经过多次尝试，我们终于最终找到了答案。", "corrected_sentence": "经过多次尝试，我们最终找到了答案。", "error_description": "错误：“终于”和“最终”意思重复，都表示结果出现在最后，不能叠在同一个动词前面。应说“我们最终找到了答案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个小孩终于最终没有回来。", "corrected_sentence": "那个小孩最终没有回来。", "error_description": "错误：“终于”和“最终”意思重复，不能同时用在“没有回来”前面。应说“那个小孩最终没有回来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
