INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21520, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西分开整理。", "primary_collocate": null, "pronunciation": "fēn jiǎn", "ipa": "fən˥ tɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈在分拣旧衣服，哪些留下，哪些送人。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们正在分拣玩具，把积木放在一起。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这些豆子分拣一下，好的放左边。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了一下午分拣书桌里的文件。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在公园里分拣垃圾，分成可回收和不可回收。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以前，我们要先分拣东西，不用的就扔掉。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶坐在桌子旁，慢慢分拣红豆和绿豆。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让大家把卡片分拣好，再交上来。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正在分拣照片，想找出去年的那几张。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些零件太乱了，得先分拣再用。", "target_word": "分拣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分拣了", "label": "体标"}, {"form": "分拣过", "label": "体标"}, {"form": "分拣机", "label": "复合"}], "register": "中性", "sense_fingerprint": "把杂乱的东西分开整理好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1845352-48be-48eb-9b3d-f37709a0cac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "播放", "is_correct": false, "explanation": "搭配：“播放”的对象是影音内容，不能说播放旧衣服。"}, {"text": "灌溉", "is_correct": false, "explanation": "语义：“灌溉”指给田地或植物浇水，旧衣服不能灌溉。"}, {"text": "分拣", "is_correct": true, "explanation": "分拣：把旧衣服分成留下和送人两类，正符合语境。"}, {"text": "眺望", "is_correct": false, "explanation": "搭配：“眺望”的对象是远处的景色，不能说眺望旧衣服。"}], "explanations": {"播放": "搭配：“播放”的对象是影音内容，不能说播放旧衣服。", "灌溉": "语义：“灌溉”指给田地或植物浇水，旧衣服不能灌溉。", "分拣": "分拣：把旧衣服分成留下和送人两类，正符合语境。", "眺望": "搭配：“眺望”的对象是远处的景色，不能说眺望旧衣服。"}, "sentence_index": 0, "correct_answer": "分拣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在书架上分拣了一本书。", "explanation": "这里应该用〈挑选〉。分拣要把一堆东西分开整理，只拿一本书时要用挑选。"}, {"text": "老师把作业本分拣给学生。", "explanation": "这里应该用〈分发〉。分拣只表示把杂乱的东西分开整理，不表示把东西发给别人。"}, {"text": "他认真分拣了这个问题。", "explanation": "这里应该用〈分析〉。分拣针对能拿在手里分开整理的具体东西，问题要用分析。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掷", "is_correct": false, "explanation": "语义：“掷”是抛扔，与慢慢挑拣豆子的动作不符。"}, {"text": "倾听", "is_correct": false, "explanation": "语义：“倾听”的对象是声音或人，红豆不能倾听。"}, {"text": "劈", "is_correct": false, "explanation": "搭配：“劈”多用于木柴等物，不能说劈红豆。"}, {"text": "分拣", "is_correct": true, "explanation": "分拣：慢慢把红豆和绿豆挑开分类，符合语境。"}], "explanations": {"掷": "语义：“掷”是抛扔，与慢慢挑拣豆子的动作不符。", "倾听": "语义：“倾听”的对象是声音或人，红豆不能倾听。", "劈": "搭配：“劈”多用于木柴等物，不能说劈红豆。", "分拣": "分拣：慢慢把红豆和绿豆挑开分类，符合语境。"}, "sentence_index": 6, "correct_answer": "分拣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板分拣了这项任务。", "explanation": "这里应该用〈分配〉。分拣是把具体物品挑拣分开，任务要用分配。"}, {"text": "她分拣了一下心情。", "explanation": "这里应该用〈整理〉。分拣针对能拿在手里分开的具体东西，心情要用整理。"}, {"text": "他分拣了一条路。", "explanation": "这里应该用〈选择〉。分拣要把一堆东西分开整理，一条路只能选择。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把旧衣服分拣两堆。", "corrected_sentence": "我们把旧衣服分拣成两堆。", "error_description": "错误：“分拣”后缺少补语“成”，写成“分拣两堆”。正确说法是“分拣成两堆”，表示分成的结果要用“成”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们把玩具分拣很整齐。", "corrected_sentence": "孩子们把玩具分拣得很整齐。", "error_description": "错误：动词“分拣”后缺少结果补语的助词“得”，写成“分拣很整齐”。正确说法是“分拣得很整齐”，“得”要连接动词和补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12989ea-486a-499c-81a1-eae37efd1757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
