INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21522, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西变得能用或做好。", "primary_collocate": null, "pronunciation": "chǔ lǐ", "ipa": "ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "这块布要先处理一下，才能做衣服。", "target_word": "处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木头要先处理干净，才能做桌子。", "target_word": "处理", "complexity_tier": "T3", "furigana": "zhè kuài mùtou yào xiān chǔlǐ gānjìng, cái néng zuò zhuōzi.", "sentence_source": "generated"}, {"text": "工人用机器处理了脏水。", "target_word": "处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批鱼他处理得很干净，可以直接下锅了。", "target_word": "处理", "complexity_tier": "T3", "furigana": "zhè pī yú tā chǔlǐ de hěn gānjìng, kěyǐ zhíjiē xià guō le.", "sentence_source": "generated"}, {"text": "我想把这些照片处理一下再发给你。", "target_word": "处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，他把垃圾处理好了。", "target_word": "处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水要先处理干净，才能喝。", "target_word": "处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批旧书要先处理一下，才能捐给学校。", "target_word": "处理", "complexity_tier": "T3", "furigana": "zhè pī jiù shū yào xiān chǔlǐ yíxià, cái néng juān gěi xuéxiào.", "sentence_source": "generated"}, {"text": "这条鱼要先处理，再放进锅里。", "target_word": "处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂有专门的机器处理垃圾。", "target_word": "处理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处理了", "label": "体标"}, {"form": "处理过", "label": "体标"}, {"form": "处理处理", "label": "重叠"}, {"form": "处理器", "label": "复合"}], "register": "中性", "sense_fingerprint": "对事物加工、整理或解决，使其可用或妥当", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0532c88-8ee2-41a8-8416-c67566056b85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21522, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "处理", "is_correct": true, "explanation": "处理，指对布料先加工，使它能用来做衣服，与“才能做衣服”相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：布不能吃，“吃”与“布”语义冲突。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语须是饮料，不能接“布”。"}, {"text": "种", "is_correct": false, "explanation": "语义：种植的对象是植物或种子，布不能“种”。"}], "explanations": {"处理": "处理，指对布料先加工，使它能用来做衣服，与“才能做衣服”相合。", "吃": "语义：布不能吃，“吃”与“布”语义冲突。", "喝": "搭配：“喝”的宾语须是饮料，不能接“布”。", "种": "语义：种植的对象是植物或种子，布不能“种”。"}, "sentence_index": 0, "correct_answer": "处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都去公园处理身体。", "explanation": "这里应该用〈锻炼〉。处理指加工或解决事物，锻炼身体要用〈锻炼〉，不能用〈处理〉。"}, {"text": "他常常处理家乡。", "explanation": "这里应该用〈想念〉。处理指加工或解决事物，表达思念家乡的感情要用〈想念〉，不能用〈处理〉。"}, {"text": "他处理了一个微笑，然后转身走了。", "explanation": "这里不能用“处理”，应换成〈露出〉或〈回以〉。处理的对象是事务或物品，不能用于表情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21522, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "处理", "is_correct": true, "explanation": "处理，指对水进行净化或加工，与“干净”“才能喝”相合。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”用于地面、房间等，不用于水。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”后接“干净”不成立，水要说“烧开”。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”用于擦拭表面，不能擦水使之“干净”。"}], "explanations": {"处理": "处理，指对水进行净化或加工，与“干净”“才能喝”相合。", "打扫": "语义：“打扫”用于地面、房间等，不用于水。", "烧": "搭配：“烧”后接“干净”不成立，水要说“烧开”。", "擦": "语义：“擦”用于擦拭表面，不能擦水使之“干净”。"}, "sentence_index": 6, "correct_answer": "处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钥匙处理进了口袋。", "explanation": "这里应该用〈放〉。处理指加工或解决事物，把东西装进口袋要用〈放〉，不能用〈处理〉。"}, {"text": "他一边走路，一边处理着一阵风。", "explanation": "这里不能用“处理”，应换成〈感受〉或〈迎着〉。处理的对象是具体事务，不能用于风。"}, {"text": "他每天都处理清晨的阳光，觉得很舒服。", "explanation": "这里应该用〈享受〉。处理的对象是事务或物品，不能用于阳光，享受阳光要用〈享受〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21522, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把这些旧纸箱处理了好。", "corrected_sentence": "我已经把这些旧纸箱处理好了。", "error_description": "补语位置错误：结果补语“好”应紧跟动词，“了”放在句末，应为“处理好了”，不能说“处理了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21522, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些旧报纸我们已经处理了过。", "corrected_sentence": "这些旧报纸我们已经处理过了。", "error_description": "体标顺序错误：动态助词“过”须紧跟动词，“了”放在句末，应为“处理过了”，不能说“处理了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
