INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21528, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个人说好一起做的事，写在纸上，大家都要遵守。", "primary_collocate": null, "pronunciation": "hé tong", "ipa": "xɤ˧˥ tʰʊŋ", "syllable_count": 2, "sentences": [{"text": "合同是写在纸上的约定，大家都要遵守。", "target_word": "合同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和朋友写了一份合同，一起开小店。", "target_word": "合同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合同上有两个人的名字。", "target_word": "合同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你签名以前，要先看合同写了什么。", "target_word": "合同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们没有照合同做事，所以吵架了。", "target_word": "合同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份合同要保存好，别弄丢了。", "target_word": "合同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板和工人在合同上签了名。", "target_word": "合同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "合同写得很清楚，每个人都知道自己要做什么。", "target_word": "合同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司要做生意，先写了合同。", "target_word": "合同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "租房子的时候，房东给了我一份合同。", "target_word": "合同", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份合同", "label": "量词"}, {"form": "劳动合同", "label": "复合"}], "register": "中性", "sense_fingerprint": "写在纸上、大家都要遵守的约定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae77ee84-c07a-4548-b32e-52b3c05e79c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21528, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合同", "is_correct": true, "explanation": "正确。“合同”指写在纸上、大家都要遵守的约定。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是双方约定，句子说的是写在纸上、大家都要遵守的约定。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是约定，不能说“写在纸上、大家都要遵守”。"}, {"text": "玩笑", "is_correct": false, "explanation": "搭配：“玩笑”一般说出口，不常说“写在纸上的玩笑”。"}], "explanations": {"合同": "正确。“合同”指写在纸上、大家都要遵守的约定。", "歌曲": "语义：歌曲不是双方约定，句子说的是写在纸上、大家都要遵守的约定。", "窗户": "语义：窗户不是约定，不能说“写在纸上、大家都要遵守”。", "玩笑": "搭配：“玩笑”一般说出口，不常说“写在纸上的玩笑”。"}, "sentence_index": 0, "correct_answer": "合同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校发了一份合同，上面写着明天放假。", "explanation": "这里应该用〈通知〉。合同是双方共同遵守的约定，学校发布的告知性文件要用“通知”。"}, {"text": "我在课堂上写了一份合同，记下老师讲的内容。", "explanation": "这里应该用〈笔记〉。合同是双方约定的文件，记录课堂内容要用“笔记”。"}, {"text": "教室墙上贴着一份合同，写着每天谁来打扫。", "explanation": "这里应该用〈值日表〉。合同是双方共同遵守的约定，安排值日的表格要用“值日表”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合同", "is_correct": true, "explanation": "正确。“在合同上签名”指在约定文件上签字。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能作为签名的载体，句子说的是在纸面文件上签名。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能用来签名，这句话的对象是纸面文件。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：“在……上签名”要求可以书写的平面，雨水不能用来签名。"}], "explanations": {"合同": "正确。“在合同上签名”指在约定文件上签字。", "天空": "语义：天空不能作为签名的载体，句子说的是在纸面文件上签名。", "空气": "语义：空气不能用来签名，这句话的对象是纸面文件。", "雨水": "搭配：“在……上签名”要求可以书写的平面，雨水不能用来签名。"}, "sentence_index": 6, "correct_answer": "合同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饭店给我们端上来一份合同，上面写着今天的菜。", "explanation": "这里应该用〈菜单〉。合同是双方约定的协议，列出菜品的单子要用“菜单”。"}, {"text": "妈妈用合同给花浇水。", "explanation": "这里应该用〈水壶〉。合同是写在纸上的约定，不能用来给花浇水，浇水要用水壶。"}, {"text": "他每天早上都喝合同。", "explanation": "这里应该用〈牛奶〉。合同是写在纸上的约定，不能拿来喝，应说“喝牛奶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只合同我看了两遍才签名。", "corrected_sentence": "这份合同我看了两遍才签名。", "error_description": "量词错误：“合同”应搭配量词“份”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这条合同保存好了。", "corrected_sentence": "我把这份合同保存好了。", "error_description": "量词错误：“合同”应搭配量词“份”，不能用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
