INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21530, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21530, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "期货市场是一个地方，人们可以买卖将来才交货的东西。", "primary_collocate": null, "pronunciation": "qī huò shì chǎng", "ipa": "tɕʰi˥ xuo˥˩ ʂɨ˥˩ ʈʂʰɑŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "期货市场是买卖将来货物的地方。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在期货市场，人们先谈好价格，以后再交货。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民想在期货市场先卖掉明年的米。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "期货市场里的人，每天都看着价格。", "target_word": "期货市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次去期货市场，什么都不懂。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "期货市场和一般的市场不一样。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在期货市场买东西，不能马上拿到货。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了期货市场是什么。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作是在期货市场帮客人买卖。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多公司用期货市场来提前定好价格。", "target_word": "期货市场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个期货市场", "label": "量词"}, {"form": "期貨市場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人们买卖将来才交货的东西的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae77ee84-c07a-4548-b32e-52b3c05e79c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21530, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "期货市场", "is_correct": true, "explanation": "正确。定义中“买卖将来才交货的东西”的场所就是期货市场。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市卖的是即时交货的商品，不是买卖将来货物的地方。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“银行”不是买卖货物的场所，不能用“买卖将来货物的地方”来定义。"}, {"text": "农贸市场", "is_correct": false, "explanation": "语义：农贸市场是当场交易、即时交货的场所，与“将来货物”矛盾。"}], "explanations": {"期货市场": "正确。定义中“买卖将来才交货的东西”的场所就是期货市场。", "超市": "语义：超市卖的是即时交货的商品，不是买卖将来货物的地方。", "银行": "搭配：“银行”不是买卖货物的场所，不能用“买卖将来货物的地方”来定义。", "农贸市场": "语义：农贸市场是当场交易、即时交货的场所，与“将来货物”矛盾。"}, "sentence_index": 0, "correct_answer": "期货市场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "期货市场可以当场付钱拿货。", "explanation": "这里应该用〈现货市场〉。期货市场交货在将来，不能当场付钱拿货。"}, {"text": "我去期货市场买了一斤苹果，马上带回家吃了。", "explanation": "这里应该用〈菜市场〉。期货市场买卖的是将来才交货的东西，不能当场买苹果带回家。"}, {"text": "期货市场里的东西可以马上拿走。", "explanation": "这里应该用〈超市〉。期货市场交货在将来，不能马上拿走货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21530, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "期货市场", "is_correct": true, "explanation": "正确。期货市场的交割在将来，所以买了东西不能马上拿到货，符合语境。"}, {"text": "菜市场", "is_correct": false, "explanation": "搭配：在“菜市场”买东西通常当场拿到货，与“不能马上拿到货”矛盾。"}, {"text": "便利店", "is_correct": false, "explanation": "语义：便利店一般当场付款、当场拿货，与“不能马上拿到货”矛盾。"}, {"text": "小卖部", "is_correct": false, "explanation": "语义：小卖部一般当场交易，与句中“不能马上拿到货”不符。"}], "explanations": {"期货市场": "正确。期货市场的交割在将来，所以买了东西不能马上拿到货，符合语境。", "菜市场": "搭配：在“菜市场”买东西通常当场拿到货，与“不能马上拿到货”矛盾。", "便利店": "语义：便利店一般当场付款、当场拿货，与“不能马上拿到货”矛盾。", "小卖部": "语义：小卖部一般当场交易，与句中“不能马上拿到货”不符。"}, "sentence_index": 6, "correct_answer": "期货市场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "期货市场里的拍品当场就能成交。", "explanation": "这里应该用〈拍卖行〉。期货市场交割在将来，不能当场成交。"}, {"text": "期货市场里可以先点菜，等一会儿就能上菜。", "explanation": "这里应该用〈餐厅〉。期货市场不提供菜品，不能点菜上菜。"}, {"text": "期货市场里的药可以当场付钱带走。", "explanation": "这里应该用〈药店〉。期货市场不卖药，交易也不能当场带走商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21530, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他第一次去了一张期货市场。", "corrected_sentence": "他第一次去了一个期货市场。", "error_description": "“张”应改为“个”。“张”用于平面的东西，不能计量市场，应说“一个期货市场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21530, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家农场期货市场卖出了明年的小麦。", "corrected_sentence": "这家农场在期货市场卖出了明年的小麦。", "error_description": "漏掉了“在”。表示动作发生的场所要用“在+地点”，应说“在期货市场卖出了明年的小麦”，不能省去“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
