INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21532, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情前定好的步骤和规则。", "primary_collocate": null, "pronunciation": "chéng xù", "ipa": "tʂʰɤŋ˧˥ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "办护照要走很多程序。", "target_word": "程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个审批程序太复杂了，我不太懂。", "target_word": "程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按程序填写这张表。", "target_word": "程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查病人有固定的程序。", "target_word": "程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前要先完成这些程序。", "target_word": "程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司买东西必须按程序来。", "target_word": "程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个报税程序很简单，几分钟就好了。", "target_word": "程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国留学要经过很多程序。", "target_word": "程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们做实验的程序。", "target_word": "程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有按程序做，结果出了问题。", "target_word": "程序", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个程序", "label": "量词"}, {"form": "一套程序", "label": "量词"}, {"form": "程序员", "label": "复合"}], "register": "中性", "sense_fingerprint": "办事的固定步骤和规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bacc239c-df87-4c0c-a87d-ec7f9978f1b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "程序", "is_correct": true, "explanation": "正确：“程序”指办事的固定步骤，符合“办护照要走很多”的语境。"}, {"text": "包", "is_correct": false, "explanation": "语义：“包”是装东西的容器，不是办事的步骤，“要走很多包”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“走”不能和“颜色”搭配，句子无法成立。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能作“走”的宾语，“要走很多年龄”不成立。"}], "explanations": {"程序": "正确：“程序”指办事的固定步骤，符合“办护照要走很多”的语境。", "包": "语义：“包”是装东西的容器，不是办事的步骤，“要走很多包”说不通。", "颜色": "搭配：“走”不能和“颜色”搭配，句子无法成立。", "年龄": "搭配：“年龄”不能作“走”的宾语，“要走很多年龄”不成立。"}, "sentence_index": 0, "correct_answer": "程序"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在公司的程序很高，大家都很尊敬他。", "explanation": "这里应该用〈地位〉。“程序”指办事的固定步骤和规则，不能表示职位的高低，应说“地位”。"}, {"text": "请大家按身高的程序排好队。", "explanation": "这里应该用〈顺序〉。“程序”指办事的固定步骤和规则，表示先后排列要用“顺序”。"}, {"text": "这次地震造成的破坏程序很大。", "explanation": "这里应该用〈程度〉。“程序”指办事的步骤和规则，表示破坏的轻重要用“程度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "程序", "is_correct": true, "explanation": "正确：“程序”指办事的固定步骤，符合“报税……很简单，几分钟就好了”的语境。"}, {"text": "猫", "is_correct": false, "explanation": "语义：“猫”是动物，不是报税的办事步骤，“报税猫”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“简单”用来形容事情的难易，不能用来形容“天气”。"}, {"text": "湖", "is_correct": false, "explanation": "语义：“湖”是地理事物，不是办事的步骤，“报税湖”说不通。"}], "explanations": {"程序": "正确：“程序”指办事的固定步骤，符合“报税……很简单，几分钟就好了”的语境。", "猫": "语义：“猫”是动物，不是报税的办事步骤，“报税猫”说不通。", "天气": "搭配：“简单”用来形容事情的难易，不能用来形容“天气”。", "湖": "语义：“湖”是地理事物，不是办事的步骤，“报税湖”说不通。"}, "sentence_index": 6, "correct_answer": "程序"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段话的程序很重，大家都很佩服。", "explanation": "这里应该用〈分量〉。“程序”指办事的固定步骤和规则，不能表示言辞的轻重，应说“分量”。"}, {"text": "这段话的程序很清楚，大家都能看懂。", "explanation": "这里应该用〈条理〉。“程序”指办事的固定步骤和规则，说明文章或讲话的层次要用“条理”。"}, {"text": "他是一名程序，每天写代码。", "explanation": "这里应该用〈程序员〉。“程序”指步骤或计算机程序，指人要用“程序员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只程序我们已经全部完成了。", "corrected_sentence": "这个程序我们已经全部完成了。", "error_description": "量词错误：“程序”用量词“个”或“套”，不能用“只”。正确说法是“这个程序”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把报税程序我们已经学会了。", "corrected_sentence": "这套报税程序我们已经学会了。", "error_description": "量词错误：“程序”不用“把”计量（“把”用于有柄的器具）。应改为“这套报税程序”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b051ccd-1c11-44f7-8a18-956edcb783b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
