INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21534, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西不能动。", "primary_collocate": null, "pronunciation": "suǒ dìng", "ipa": "swɔ˨˩˦ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "手机屏幕已经锁定了。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把车门锁定，再离开。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机锁定了方向盘。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把机器的轮子锁定了。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑锁定了，我打不开。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门锁定着，你进不去。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前，我会锁定手机屏幕。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个按键能锁定画面。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮椅停下后，要先锁定轮子。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按一下键，就锁定了窗口。", "target_word": "锁定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "锁定了", "label": "体标（了）"}, {"form": "锁定着", "label": "体标（着）"}, {"form": "锁定过", "label": "体标（过）"}, {"form": "鎖定", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用锁或按键使屏幕、车门、轮子等无法移动或操作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae77ee84-c07a-4548-b32e-52b3c05e79c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "锁定", "is_correct": true, "explanation": "正确。“锁定屏幕”指屏幕被锁住，无法操作。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是可以清洗的东西，屏幕不能说“洗”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能用于屏幕，句子说的是屏幕被锁住。"}, {"text": "盛", "is_correct": false, "explanation": "配价：“盛”需要容器和内容物，屏幕不能被盛。"}], "explanations": {"锁定": "正确。“锁定屏幕”指屏幕被锁住，无法操作。", "洗": "搭配：“洗”的对象是可以清洗的东西，屏幕不能说“洗”。", "唱": "语义：“唱”不能用于屏幕，句子说的是屏幕被锁住。", "盛": "配价：“盛”需要容器和内容物，屏幕不能被盛。"}, "sentence_index": 0, "correct_answer": "锁定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人把机器的噪音锁定了，车间里很安静。", "explanation": "这里应该用〈降低〉。锁定只表示让东西不能动，不能用来表示减小噪音。"}, {"text": "工人把车间锁定干净了。", "explanation": "这里应该用〈收拾〉。锁定只表示让东西不能动，不能表示整理、打扫。"}, {"text": "工人锁定了一个苹果。", "explanation": "这里应该用〈拿〉。锁定只用于门、车、屏幕、轮子等可以上锁或固定的东西，不能用来表示处理苹果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "锁定", "is_correct": true, "explanation": "正确。“睡觉前锁定手机屏幕”指睡前把屏幕锁住。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”的对象不能是手机屏幕，句子说的是睡前锁住屏幕。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”的对象须是能吃东西的生物，手机屏幕不能被喂。"}, {"text": "吸引", "is_correct": false, "explanation": "配价：“吸引”需要能被吸引的对象（人或注意力），屏幕不能被吸引。"}], "explanations": {"锁定": "正确。“睡觉前锁定手机屏幕”指睡前把屏幕锁住。", "咬": "语义：“咬”的对象不能是手机屏幕，句子说的是睡前锁住屏幕。", "喂": "语义：“喂”的对象须是能吃东西的生物，手机屏幕不能被喂。", "吸引": "配价：“吸引”需要能被吸引的对象（人或注意力），屏幕不能被吸引。"}, "sentence_index": 6, "correct_answer": "锁定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用湿布锁定了桌子。", "explanation": "这里应该用〈擦〉。锁定指让东西不能动，不能表示擦拭。"}, {"text": "妈妈每天早上在锅里锁定粥。", "explanation": "这里应该用〈煮〉。锁定指让东西不能动，不能表示烹煮。"}, {"text": "我用打印机锁定了报告。", "explanation": "这里应该用〈复印〉。锁定指让东西不能动，不能表示复制报告，复印报告要用“复印”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚才把屏幕锁定了着。", "corrected_sentence": "我刚才把屏幕锁定了。", "error_description": "体标冲突：“了”与“着”不能同时用在“锁定”之后，应只用“了”，即“我刚才把屏幕锁定了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我先锁定把车门。", "corrected_sentence": "我先锁定车门。", "error_description": "语序错误：“把”和它的宾语要放在动词前面，不能放在“锁定”后面。应说“我先把车门锁定”，或者不用“把”，说“我先锁定车门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61651596-81db-4e4b-a90d-76eb0b00ffa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21538, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短期", "is_correct": true, "explanation": "正确：“短期”与“长期”是反义词，指时间很短。"}, {"text": "频繁", "is_correct": false, "explanation": "与“长期”没有反义关系，“频繁”指次数多。"}, {"text": "迅速", "is_correct": false, "explanation": "与“长期”没有反义关系，“迅速”指速度快。"}, {"text": "偶然", "is_correct": false, "explanation": "与“长期”没有反义关系，“偶然”指出于意外、偶尔发生。"}], "correct_answer": "短期", "explanations": {"短期": "正确：“短期”与“长期”是反义词，指时间很短。", "频繁": "与“长期”没有反义关系，“频繁”指次数多。", "迅速": "与“长期”没有反义关系，“迅速”指速度快。", "偶然": "与“长期”没有反义关系，“偶然”指出于意外、偶尔发生。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21538, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短期", "is_correct": true, "explanation": "正确：“短期”与“长期”是反义词，指时间很短。"}, {"text": "仓促", "is_correct": false, "explanation": "与“长期”没有反义关系，“仓促”指匆忙、来不及细想。"}, {"text": "罕见", "is_correct": false, "explanation": "与“长期”没有反义关系，“罕见”指很少见。"}, {"text": "轻松", "is_correct": false, "explanation": "与“长期”没有反义关系，“轻松”指不费力、不紧张。"}], "correct_answer": "短期", "explanations": {"短期": "正确：“短期”与“长期”是反义词，指时间很短。", "仓促": "与“长期”没有反义关系，“仓促”指匆忙、来不及细想。", "罕见": "与“长期”没有反义关系，“罕见”指很少见。", "轻松": "与“长期”没有反义关系，“轻松”指不费力、不紧张。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21538, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "时间过去很多，很久。", "primary_collocate": null, "pronunciation": "cháng qī", "ipa": "ʈʂʰaŋ˧˥ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "他长期住在国外，很少回家。", "target_word": "长期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期不运动对身体不好。", "target_word": "长期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要一个长期的计划。", "target_word": "长期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她长期工作到很晚，非常累。", "target_word": "长期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司和我们有长期合作。", "target_word": "长期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期坐着看电脑，眼睛会不舒服。", "target_word": "长期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长期吃这种药，医生让他换一种。", "target_word": "长期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学语言是一件长期的事，不能着急。", "target_word": "长期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期睡得太少，人会没有精神。", "target_word": "长期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李长期帮助山区的孩子。", "target_word": "长期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词：时间跨度很长，持续很久", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54dc7929-d038-45aa-8c18-bc8b7ecc58a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21538, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长期", "is_correct": true, "explanation": "正确：“长期”表示时间很久，与“住在国外，很少回家”的持续状态相符。"}, {"text": "漫长", "is_correct": false, "explanation": "搭配：“漫长”多修饰时间、道路，不能直接修饰“住”。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：“偶然”指偶尔发生，与持续住在国外的状态矛盾。"}, {"text": "迅速", "is_correct": false, "explanation": "语义：“迅速”指速度快，与长期住在国外的持续状态不合。"}], "explanations": {"长期": "正确：“长期”表示时间很久，与“住在国外，很少回家”的持续状态相符。", "漫长": "搭配：“漫长”多修饰时间、道路，不能直接修饰“住”。", "偶然": "语义：“偶然”指偶尔发生，与持续住在国外的状态矛盾。", "迅速": "语义：“迅速”指速度快，与长期住在国外的持续状态不合。"}, "sentence_index": 0, "correct_answer": "长期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我长期等了你五分钟，你怎么才来？", "explanation": "这里应该用〈一会儿〉。“长期”指持续很久，等五分钟只是短暂的时间，应说“等了五分钟”或“等了一会儿”。"}, {"text": "请长期停一下。", "explanation": "这里应该用〈暂时〉。“长期”指持续很久，“停一下”是短暂的动作，二者矛盾；短暂的停顿要用“暂时”。"}, {"text": "他长期去过一次北京。", "explanation": "这里应该用〈曾经〉。“长期”强调持续很久，去过一次北京是一次性的经历，应说“曾经去过北京”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长期", "is_correct": true, "explanation": "正确：“长期”表示时间很久，与“吃这种药”的持续用药相符。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指忽然发生，与持续很久的用药不合。"}, {"text": "有限", "is_correct": false, "explanation": "搭配：“有限”多修饰数量、范围，不能直接修饰“吃”。"}, {"text": "短暂", "is_correct": false, "explanation": "语义：“短暂”指时间很短，与“长期吃这种药”的持续性矛盾。"}], "explanations": {"长期": "正确：“长期”表示时间很久，与“吃这种药”的持续用药相符。", "突然": "语义：“突然”指忽然发生，与持续很久的用药不合。", "有限": "搭配：“有限”多修饰数量、范围，不能直接修饰“吃”。", "短暂": "语义：“短暂”指时间很短，与“长期吃这种药”的持续性矛盾。"}, "sentence_index": 6, "correct_answer": "长期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老李长期帮了山区的孩子几分钟。", "explanation": "这里应该用〈只〉。“长期”指时间很久，“几分钟”是很短的时间，二者矛盾；应说“老李只帮了山区的孩子几分钟”。"}, {"text": "老李长期休息了一会儿，就继续帮忙。", "explanation": "这里应该用〈片刻〉。“长期”指时间很久，休息一会儿是短暂的，要用“片刻”表示短时间。"}, {"text": "老李长期看了一眼山区的风景。", "explanation": "这里应该用〈匆匆〉。“长期”指持续很久，“看了一眼”是瞬间动作，二者矛盾；应说“老李匆匆看了一眼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店长期了营业，很多人都知道。", "corrected_sentence": "这家店长期营业，很多人都知道。", "error_description": "助词错误：“长期”后不能加“了”，“了”表示完成，与“长期”的持续义不合；正确为“长期营业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他长期得练习游泳，身体越来越好。", "corrected_sentence": "他长期练习游泳，身体越来越好。", "error_description": "助词错误：“长期”后不应接“得”，“得”用于动词或形容词之后引出补语；这里直接说“长期练习”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
