INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21546, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说到或跟某件事有关系。", "primary_collocate": null, "pronunciation": "shè jí", "ipa": "ʂɤ˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这件事涉及很多人。", "target_word": "涉及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话涉及了学习方法。", "target_word": "涉及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书涉及历史和地理。", "target_word": "涉及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想谈涉及钱的问题。", "target_word": "涉及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题涉及公司的秘密。", "target_word": "涉及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上没有涉及这个话题。", "target_word": "涉及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试涉及的内容很多。", "target_word": "涉及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作涉及很多国家。", "target_word": "涉及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说的事涉及到我的朋友。", "target_word": "涉及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告里涉及过环境问题。", "target_word": "涉及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "涉及了", "label": "体标"}, {"form": "涉及过", "label": "体标"}, {"form": "涉及到", "label": "复合"}], "register": "中性", "sense_fingerprint": "说到或跟某事有关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e21988-a24b-41f5-92fd-a20a131657a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21546, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场地或物品，“这件事打扫很多人”不通。"}, {"text": "涉及", "is_correct": true, "explanation": "“涉及”指牵连到，与“很多人”搭配，表示这件事牵连到很多人。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”的对象是有过错的人，“这件事”不能原谅人，句意不通。"}, {"text": "参与", "is_correct": false, "explanation": "搭配：“参与”的宾语多是活动、工作，不说“参与很多人”，而且事件不能参与。"}], "explanations": {"打扫": "搭配：“打扫”的对象是场地或物品，“这件事打扫很多人”不通。", "涉及": "“涉及”指牵连到，与“很多人”搭配，表示这件事牵连到很多人。", "原谅": "语义：“原谅”的对象是有过错的人，“这件事”不能原谅人，句意不通。", "参与": "搭配：“参与”的宾语多是活动、工作，不说“参与很多人”，而且事件不能参与。"}, "sentence_index": 0, "correct_answer": "涉及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们周末涉及了一场电影。", "explanation": "这里应该用〈看〉。“涉及”指事情与某方面有关系，不用来说人观看电影，观看要用“看”。"}, {"text": "我昨天涉及了那场比赛。", "explanation": "这里应该用〈参加〉。“涉及”不用于说人加入某项活动，人要用“参加”。"}, {"text": "他今天涉及了一顿午饭。", "explanation": "这里应该用〈吃〉。“涉及”指跟某件事有关系，不用来说吃饭，吃饭要用“吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21546, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跳", "is_correct": false, "explanation": "搭配：“跳”不能与“内容”搭配，“这次考试跳的内容很多”不通。"}, {"text": "涉及", "is_correct": true, "explanation": "“涉及”指牵连到，这里表示考试内容的范围，与“内容很多”搭配。"}, {"text": "责骂", "is_correct": false, "explanation": "语义：“责骂”与考试内容无关，“责骂的内容”句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是不及物的运动动作，“这次考试游泳的内容很多”不通。"}], "explanations": {"跳": "搭配：“跳”不能与“内容”搭配，“这次考试跳的内容很多”不通。", "涉及": "“涉及”指牵连到，这里表示考试内容的范围，与“内容很多”搭配。", "责骂": "语义：“责骂”与考试内容无关，“责骂的内容”句意不通。", "游泳": "语义：“游泳”是不及物的运动动作，“这次考试游泳的内容很多”不通。"}, "sentence_index": 6, "correct_answer": "涉及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们终于涉及了山顶。", "explanation": "这里应该用〈到达〉。“涉及”指牵扯到某事，不用于说人走到某个地方，要用“到达”。"}, {"text": "他涉及了很多次失败。", "explanation": "这里应该用〈经历〉。“涉及”不表示人亲身遇到某事，应说“经历”。"}, {"text": "学生涉及了那道数学题。", "explanation": "这里应该用〈解答〉。“涉及”不表示动手解题，学生解题要用“解答”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次调查很涉及很多学校。", "corrected_sentence": "这次调查涉及很多学校。", "error_description": "“涉及”是动词，前面不能直接加程度副词“很”，应说“涉及很多学校”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划没有涉及了很多部门。", "corrected_sentence": "这个计划没有涉及很多部门。", "error_description": "“没有”否定时，动词后面不能再加“了”，应说“没有涉及很多部门”。“了”要去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
