INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21548, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物表现出的样子或形式。", "primary_collocate": null, "pronunciation": "xíng tài", "ipa": "ɕiŋ˧˥ tʰai̯˥˩", "syllable_count": 2, "sentences": [{"text": "水有三种形态：固体、液体和气体。", "target_word": "形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰是水的固体形态。", "target_word": "形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花在春天的形态最美。", "target_word": "形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生通过照片看病人身体的形态。", "target_word": "形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有各种动物的形态模型。", "target_word": "形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云的形态每天都不一样。", "target_word": "形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢画不同形态的小动物。", "target_word": "形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶从虫到蝶，形态变化很大。", "target_word": "形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山的形态像一只睡着的大象。", "target_word": "形态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了树叶的不同形态。", "target_word": "形态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "形态学", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物所表现出来的样子或存在的形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b4bed82-fa15-4388-b52a-548bab14ed95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形态", "is_correct": true, "explanation": "形态：指事物呈现的外在形式，固体、液体、气体正是水的三种形态。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：外貌指人或动物的外表，不能用来说明水的存在形式。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色指色彩，与固体、液体、气体的分类无关。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度指冷热程度，不是事物的存在形式。"}], "explanations": {"形态": "形态：指事物呈现的外在形式，固体、液体、气体正是水的三种形态。", "外貌": "语义：外貌指人或动物的外表，不能用来说明水的存在形式。", "颜色": "语义：颜色指色彩，与固体、液体、气体的分类无关。", "温度": "语义：温度指冷热程度，不是事物的存在形式。"}, "sentence_index": 0, "correct_answer": "形态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他最近的形态很低落。", "explanation": "这里应该用〈心情〉。形态指事物表现出的外在样子，人的情绪低落应用〈心情〉。"}, {"text": "他对工作的形态很认真。", "explanation": "这里应该用〈态度〉。形态不能说明做事的认真程度，对工作的态度应用〈态度〉。"}, {"text": "她的形态很开朗。", "explanation": "这里应该用〈性格〉。形态是外在形式，开朗属于性格，应用〈性格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形态", "is_correct": true, "explanation": "形态：指动物等事物呈现的外在样子，正是“画”的对象。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是听觉对象，不能用“画”来表现。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道属于味觉，画不出来。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“画”的对象是形象，不能说画“价格”。"}], "explanations": {"形态": "形态：指动物等事物呈现的外在样子，正是“画”的对象。", "声音": "语义：声音是听觉对象，不能用“画”来表现。", "味道": "语义：味道属于味觉，画不出来。", "价格": "搭配：“画”的对象是形象，不能说画“价格”。"}, "sentence_index": 6, "correct_answer": "形态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在大家心中的形态很好。", "explanation": "这里应该用〈形象〉。形态指外在形式，人在他人心中的印象应用〈形象〉。"}, {"text": "她保持着积极的形态。", "explanation": "这里应该用〈心态〉。形态指外在形式，内心的态度和想法应用〈心态〉。"}, {"text": "这位歌手的形态很好听。", "explanation": "这里应该用〈声音〉。形态指外在形式，好听的是声音，形态与听觉无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看到了一只奇怪的形态。", "corrected_sentence": "我看到了一种奇怪的形态。", "error_description": "“形态”的量词应用“种”，写作“一种奇怪的形态”；“只”用于动物等个体，不能修饰“形态”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从没见过这只形态的花。", "corrected_sentence": "我从没见过这种形态的花。", "error_description": "“形态”应搭配量词“种”，写作“这种形态”；“只”用于动物等个体，不能修饰“形态”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
