INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21550, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对每个人都一样对待，不偏袒任何一方，没有谁多谁少。", "primary_collocate": null, "pronunciation": "gōng píng", "ipa": "kʊŋ˥ pʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "老师把奖品公平地分给每个学生。", "target_word": "公平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样分蛋糕不公平，我的太小了。", "target_word": "公平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分配工作要公平，每个人做得一样多。", "target_word": "公平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得这件事对他不公平。", "target_word": "公平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公平的老板会给每个人一样的机会。", "target_word": "公平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥有两个，我只有一个，太不公平了。", "target_word": "公平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试很公平，题目对大家都一样。", "target_word": "公平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，分东西要公平。", "target_word": "公平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样做对别人不公平。", "target_word": "公平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱要公平地分，每人一份。", "target_word": "公平", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不公平", "label": "否定"}, {"form": "公平地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "形容词：对每个人一样，不偏向任何人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40c6bb68-9edb-4a24-ad31-cf0cde640a3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公平", "is_correct": true, "explanation": "公平：按同样的标准分给每个学生，符合句意。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”描写人或物的外形，不能用来修饰“分”这个动作。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”形容温度，不能修饰分奖品的动作。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容声音，不能用来修饰分东西。"}], "explanations": {"公平": "公平：按同样的标准分给每个学生，符合句意。", "瘦小": "体貌：“瘦小”描写人或物的外形，不能用来修饰“分”这个动作。", "滚烫": "搭配：“滚烫”形容温度，不能修饰分奖品的动作。", "沙哑": "搭配：“沙哑”形容声音，不能用来修饰分东西。"}, "sentence_index": 0, "correct_answer": "公平"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这个消息，他的心情很公平。", "explanation": "这里应该用〈平静〉。公平指对待人或事一样、不偏袒，不用来形容心情。"}, {"text": "饮食要公平，蔬菜和肉都要吃。", "explanation": "这里应该用〈均衡〉。公平用于对待人或分配，不用于说饮食的搭配。"}, {"text": "这条路很公平。", "explanation": "这里应该用〈平坦〉。公平指对待或分配一样，不用来形容路面是否平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公平", "is_correct": true, "explanation": "公平：题目对大家都一样，符合“考试很公平”的描述。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体型，不能用来形容考试。"}, {"text": "冰凉", "is_correct": false, "explanation": "搭配：“冰凉”形容温度或触感，不能用来形容考试。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”表示幸福的感觉，与“题目对大家都一样”所描述的考试情况不符。"}], "explanations": {"公平": "公平：题目对大家都一样，符合“考试很公平”的描述。", "高大": "体貌：“高大”形容人或物的体型，不能用来形容考试。", "冰凉": "搭配：“冰凉”形容温度或触感，不能用来形容考试。", "甜蜜": "语义：“甜蜜”表示幸福的感觉，与“题目对大家都一样”所描述的考试情况不符。"}, "sentence_index": 6, "correct_answer": "公平"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家的身高很公平。", "explanation": "这里应该用〈平均〉。公平指对待或分配一样，不用来形容身高是否相近。"}, {"text": "这道题的答案很公平。", "explanation": "这里应该用〈正确〉。公平形容对待人的态度，不用来判断答案的对错。"}, {"text": "这件衣服很公平。", "explanation": "这里应该用〈漂亮〉。公平指对待或分配一样，不用来形容衣服的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把钱分很公平。", "corrected_sentence": "他把钱分得很公平。", "error_description": "“分”后面缺少补语标记“得”。正确形式是“分得很公平”，“得”引出对分的情况的描写。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他公平的安排了值日。", "corrected_sentence": "他公平地安排了值日。", "error_description": "错误：修饰动词「安排」的状语应用「地」，不用「的」。正确是「公平地安排了值日」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
