INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21552, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "调整各方的关系或安排，使彼此配合，工作顺利进行。", "primary_collocate": null, "pronunciation": "xié tiáo", "ipa": "ɕjɛ˧˥ tʰjɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "经理想协调大家的时间。", "target_word": "协调", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们需要协调一下工作。", "target_word": "协调", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他负责协调两个部门。", "target_word": "协调", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师来协调同学们的活动。", "target_word": "协调", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你帮我们协调一下。", "target_word": "协调", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会议前，她先协调好了时间。", "target_word": "协调", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事要由小王来协调。", "target_word": "协调", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很会协调同事的关系。", "target_word": "协调", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的工作需要有人协调。", "target_word": "协调", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把各方的意见协调了一下。", "target_word": "协调", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "协调了", "label": "体标"}, {"form": "协调过", "label": "体标"}, {"form": "协调一下", "label": "动量"}], "register": "中性", "sense_fingerprint": "动词，指调整各方的关系或安排，使工作配合顺利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7679ce6-7410-49f6-bfdd-e5891d0d533a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "协调", "is_correct": true, "explanation": "协调：使各方配合、安排妥当，与“经理”“大家的时间”搭配，符合句意。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”的对象是人的言行，不能批评时间，“批评大家的时间”说不通。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”的对象是人，“欺骗大家的时间”说不通。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”搭配器物，不能说“修理时间”。"}], "explanations": {"协调": "协调：使各方配合、安排妥当，与“经理”“大家的时间”搭配，符合句意。", "批评": "语义：“批评”的对象是人的言行，不能批评时间，“批评大家的时间”说不通。", "欺骗": "语义：“欺骗”的对象是人，“欺骗大家的时间”说不通。", "修理": "搭配：“修理”搭配器物，不能说“修理时间”。"}, "sentence_index": 0, "correct_answer": "协调"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈协调了一杯果汁。", "explanation": "这里应该用〈调制〉。协调指使各方配合，不能用于调配饮料；调配饮料要说“调制”。"}, {"text": "我们认真协调了一遍试卷。", "explanation": "这里应该用〈检查〉。协调指使各方配合、理顺关系，不指审阅；检查试卷要用“检查”。"}, {"text": "空调可以协调室内温度。", "explanation": "这里应该用〈调节〉。协调用于人、工作、关系，调节温度要用“调节”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饲养", "is_correct": false, "explanation": "语义：“饲养”的对象是动物，“这件事要由小王来饲养”说不通。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”的对象是食物，“这件事要由小王来烹饪”说不通。"}, {"text": "制作", "is_correct": false, "explanation": "搭配：“制作”搭配物品或作品，不说“制作事情”。"}, {"text": "协调", "is_correct": true, "explanation": "协调：使各方配合、安排妥当，与“这件事”搭配，符合句意。"}], "explanations": {"饲养": "语义：“饲养”的对象是动物，“这件事要由小王来饲养”说不通。", "烹饪": "语义：“烹饪”的对象是食物，“这件事要由小王来烹饪”说不通。", "制作": "搭配：“制作”搭配物品或作品，不说“制作事情”。", "协调": "协调：使各方配合、安排妥当，与“这件事”搭配，符合句意。"}, "sentence_index": 6, "correct_answer": "协调"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司想办法协调了成本。", "explanation": "这里应该用〈降低〉。协调用于人、事之间的配合，成本要用“降低”。"}, {"text": "妈妈认真协调生病的孩子。", "explanation": "这里应该用〈照顾〉。协调指使各方配合，照料人要用“照顾”。"}, {"text": "他协调了那台旧电脑。", "explanation": "这里应该用〈修理〉。协调不用于修理器物，修电脑要用“修理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把各部门的工作协调。", "corrected_sentence": "我把各部门的工作协调好了。", "error_description": "错误：“把”字句里“协调”后缺少补语，应说“把各部门的工作协调好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动由她负责协调一个。", "corrected_sentence": "这次活动由她负责协调一下。", "error_description": "错误：动量补语应说“一下”，“一个”是量词短语，需要搭配名词，不能用来表示动作的次数。应说“协调一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
