INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21554, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "认证就是证明一个东西是真的、对的。", "primary_collocate": null, "pronunciation": "rèn zhèng", "ipa": "ɻən˥˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "网站要认证你的身份。", "target_word": "认证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先认证，再进入这个网站。", "target_word": "认证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种牛奶已经认证过了，可以放心喝。", "target_word": "认证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行需要认证你的电话号码。", "target_word": "认证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家机构正在认证这批古董。", "target_word": "认证", "complexity_tier": "T3", "furigana": "rèn zhèng", "sentence_source": "generated"}, {"text": "专家认证了这件青铜器。", "target_word": "认证", "complexity_tier": "T3", "furigana": "rèn zhèng", "sentence_source": "generated"}, {"text": "这家公司要认证每位员工的资格。", "target_word": "认证", "complexity_tier": "T3", "furigana": "rèn zhèng", "sentence_source": "generated"}, {"text": "手机号认证以后，你才能买东西。", "target_word": "认证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们要用两天认证所有的文件。", "target_word": "认证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用手机号认证一下这个账号。", "target_word": "认证", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "认证了", "label": "体标"}, {"form": "认证过", "label": "体标"}, {"form": "認證", "label": "繁体"}, {"form": "认证中心", "label": "复合"}], "register": "书面", "sense_fingerprint": "检查并证明某人或某物是真的、合格的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ebcdd33-4c2b-4870-aa27-7ac3753dba86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21554, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "认证", "is_correct": true, "explanation": "正确答案：认证，指经过检验确认某人或某物真实、合格。"}, {"text": "认真", "is_correct": false, "explanation": "zhēn（第一声）与 zhèng（第四声）韵母与声调都不同，意思是认真、不马虎。"}, {"text": "人证", "is_correct": false, "explanation": "rén（第二声）与 rèn（第四声）声调不同，意思是人作的证词。"}, {"text": "认知", "is_correct": false, "explanation": "zhī（第一声）与 zhèng（第四声）韵母与声调都不同，意思是认识、知道。"}, {"text": "任职", "is_correct": false, "explanation": "zhí（第二声）与 zhèng（第四声）韵母与声调不同，意思是担任职务。"}, {"text": "认成", "is_correct": false, "explanation": "chéng（第二声）与 zhèng（第四声）声母与声调都不同，意思是把甲错当成乙。"}], "explanations": {"认证": "正确答案：认证，指经过检验确认某人或某物真实、合格。", "认真": "zhēn（第一声）与 zhèng（第四声）韵母与声调都不同，意思是认真、不马虎。", "人证": "rén（第二声）与 rèn（第四声）声调不同，意思是人作的证词。", "认知": "zhī（第一声）与 zhèng（第四声）韵母与声调都不同，意思是认识、知道。", "任职": "zhí（第二声）与 zhèng（第四声）韵母与声调不同，意思是担任职务。", "认成": "chéng（第二声）与 zhèng（第四声）声母与声调都不同，意思是把甲错当成乙。"}, "sentence_index": null, "correct_answer": "认证"}, "level_3": {"options": [{"text": "认证", "is_correct": true, "explanation": "正确：“认证”指经过核验确认身份，网站需要确认你是真人。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是舍弃、不要的意思，与网站需要核实身份的目的相反。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”接的是纪录、局面、限制，不说打破“身份”。"}, {"text": "通知", "is_correct": false, "explanation": "配价：“通知”的对象是人，“你的身份”不能作为通知的内容。"}], "explanations": {"认证": "正确：“认证”指经过核验确认身份，网站需要确认你是真人。", "放弃": "语义：“放弃”是舍弃、不要的意思，与网站需要核实身份的目的相反。", "打破": "搭配：“打破”接的是纪录、局面、限制，不说打破“身份”。", "通知": "配价：“通知”的对象是人，“你的身份”不能作为通知的内容。"}, "sentence_index": 0, "correct_answer": "认证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法院认证他有罪。", "explanation": "这里应该用〈认定〉。认证是经检验确认真实或合格，多用于身份、资格、产品；判定罪责要用认定。"}, {"text": "老师认证了他的进步。", "explanation": "这里应该用〈认可〉。认证针对的是资格或产品是否合格，评价别人的进步要用认可。"}, {"text": "这张收据可以认证我付过钱。", "explanation": "这里应该用〈证明〉。认证必须由有权机构正式确认合格，不用来证明个人行为，应说证明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21554, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "认证", "is_correct": true, "explanation": "正确答案：认证，指经过检验确认真实或合格。"}, {"text": "认账", "is_correct": false, "explanation": "zhàng（第四声）与 zhèng（第四声）声调相同，韵母不同（ang 与 eng），意思是承认自己欠的账或做过的事。"}, {"text": "认生", "is_correct": false, "explanation": "shēng（第一声）与 zhèng（第四声）声母与声调都不同，意思是小孩见了陌生人害羞。"}, {"text": "任重", "is_correct": false, "explanation": "zhòng（第四声）与 zhèng（第四声）韵母不同（ong 与 eng），意思是责任重大。"}], "explanations": {"认证": "正确答案：认证，指经过检验确认真实或合格。", "认账": "zhàng（第四声）与 zhèng（第四声）声调相同，韵母不同（ang 与 eng），意思是承认自己欠的账或做过的事。", "认生": "shēng（第一声）与 zhèng（第四声）声母与声调都不同，意思是小孩见了陌生人害羞。", "任重": "zhòng（第四声）与 zhèng（第四声）韵母不同（ong 与 eng），意思是责任重大。"}, "sentence_index": null, "correct_answer": "认证"}, "level_3": {"options": [{"text": "认证", "is_correct": true, "explanation": "正确：“认证”指核定员工的资格，与句子语境相符。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”指白白耗费，与核定资格的意思不符。"}, {"text": "嫌弃", "is_correct": false, "explanation": "搭配：“嫌弃”的对象是人或事物，不说嫌弃“资格”。"}, {"text": "辞退", "is_correct": false, "explanation": "配价：“辞退”的宾语是人，不能说辞退“资格”。"}], "explanations": {"认证": "正确：“认证”指核定员工的资格，与句子语境相符。", "浪费": "语义：“浪费”指白白耗费，与核定资格的意思不符。", "嫌弃": "搭配：“嫌弃”的对象是人或事物，不说嫌弃“资格”。", "辞退": "配价：“辞退”的宾语是人，不能说辞退“资格”。"}, "sentence_index": 6, "correct_answer": "认证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一下子认证了他。", "explanation": "这里应该用〈认出〉。认证是确认资格或真实性，不表示凭样貌辨认出人。"}, {"text": "他终于认证了错误。", "explanation": "这里应该用〈承认〉。认证是有权机构对合格性的正式确认，承认错误要用承认。"}, {"text": "我认证他是对的。", "explanation": "这里应该用〈认为〉。认证是官方确认合格，个人的看法不能用认证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "游戏账号要先了认证手机号，才能充值。", "corrected_sentence": "游戏账号要先认证手机号，才能充值。", "error_description": "“了”只能放在动词后表示完成，“了认证”的语序是错误的；此句应写作“要先认证手机号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批证书需要重新了认证。", "corrected_sentence": "这批证书需要重新认证。", "error_description": "错误：“重新了认证”。正确：“重新认证”。“了”表示完成，只能放在动词后，不能插在“认证”之前，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
