INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21556, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21556, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西不会随便变来变去，一直保持一样。", "primary_collocate": null, "pronunciation": "wěn dìng xìng", "ipa": "wən˨˩˦ tiŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这张桌子的稳定性很好，不会晃。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子刚学走路，身体的稳定性还不够。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机信号的稳定性不好，常常断线。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把梯子一站上去就晃，稳定性不好。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宽底的杯子稳定性高，不容易倒。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买车时，爸爸很看重车的稳定性。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小船的稳定性差，风一大就晃。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气的稳定性不好，一会儿晴一会儿雨。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台秤的稳定性很高，每次称出来的数都一样。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书架的稳定性不够，放太多书会倒。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "穩定性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西不乱变、不摇晃，一直保持一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578294a7-0823-4619-bc2b-d5210b7acc13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21556, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指外观，与“不会晃”无关，“颜色很好，不会晃”不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”指气味或滋味，不能用来说桌子。"}, {"text": "稳定性", "is_correct": true, "explanation": "稳定性指东西不晃、一直保持一样，与“不会晃”的语境相符。"}, {"text": "长度", "is_correct": false, "explanation": "语义：“长度”说的是尺寸，与桌子是否晃动无关，“长度很好，不会晃”不通。"}], "explanations": {"颜色": "语义：“颜色”指外观，与“不会晃”无关，“颜色很好，不会晃”不通。", "味道": "搭配：“味道”指气味或滋味，不能用来说桌子。", "稳定性": "稳定性指东西不晃、一直保持一样，与“不会晃”的语境相符。", "长度": "语义：“长度”说的是尺寸，与桌子是否晃动无关，“长度很好，不会晃”不通。"}, "sentence_index": 0, "correct_answer": "稳定性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子的稳定性很大，两个人才抬得动。", "explanation": "这里应该用〈重量〉。稳定性指东西不随便变化，不指轻重；“两个人才抬得动”说的是重量。"}, {"text": "这块石头的稳定性是红色的。", "explanation": "这里应该用〈颜色〉。稳定性指东西不随便变化，不指颜色；“是红色的”说的是颜色。"}, {"text": "这一张稳定性不好，一站就晃。", "explanation": "这里应该用〈种〉或不加量词。“张”用于平面的东西，稳定性是抽象性质，不能用“张”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21556, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "语义：“声音”指声响，与“差”和“风一大就晃”无关，“声音差”不通。"}, {"text": "名声", "is_correct": false, "explanation": "语义：“名声”指社会评价，不指船的晃动，与句意不符。"}, {"text": "稳定性", "is_correct": true, "explanation": "稳定性指东西不晃、不乱变的特性，与“差，风一大就晃”的语境相符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”说人或物的重量，不能和“差”搭配来描述船是否晃动。"}], "explanations": {"声音": "语义：“声音”指声响，与“差”和“风一大就晃”无关，“声音差”不通。", "名声": "语义：“名声”指社会评价，不指船的晃动，与句意不符。", "稳定性": "稳定性指东西不晃、不乱变的特性，与“差，风一大就晃”的语境相符。", "体重": "搭配：“体重”说人或物的重量，不能和“差”搭配来描述船是否晃动。"}, "sentence_index": 6, "correct_answer": "稳定性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一扇稳定性不够，放太多书会倒。", "explanation": "这里应该用〈种〉或不加量词。“扇”用于门窗，稳定性是抽象性质，不能用“扇”计量。"}, {"text": "这辆车的稳定性很快，十分钟就能到机场。", "explanation": "这里应该用〈速度〉。稳定性指东西不随便变，不指快慢；“很快，十分钟就能到机场”说的是速度。"}, {"text": "书架的稳定性很多，放太多书会倒。", "explanation": "这里应该用〈很高〉或〈很好〉。稳定性是抽象性质，不可数，不能用“很多”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台洗衣机的稳定性好很，脱水时也不晃。", "corrected_sentence": "这台洗衣机的稳定性很好，脱水时也不晃。", "error_description": "错误：“好很”。“很”应放在形容词前面，正确说法是“稳定性很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个书柜得稳定性很好，装满书也不会倒。", "corrected_sentence": "这个书柜的稳定性很好，装满书也不会倒。", "error_description": "错误：“得”。“稳定性”前的定语应用“的”，不能用“得”。正确说法是“书柜的稳定性很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21558, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21558, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21558, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西是从哪里来的，比如苹果的产地是果园。", "primary_collocate": null, "pronunciation": "chǎn dì", "ipa": "ʈʂʰan˨˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这个苹果的产地是山东。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道这种大米的产地吗？", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "瓶子上写着葡萄酒的产地。", "target_word": "产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种橙子的产地很远，所以有点贵。", "target_word": "产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买菜时总是看产地。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋的产地是哪里？", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "茶叶的产地不同，价格也不同。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想知道这块肉的产地。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛奶包装上有产地和日期。", "target_word": "产地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了香蕉的产地。", "target_word": "产地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "產地", "label": "繁体"}, {"form": "原产地", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "产地：东西从哪里来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50c9095a-030e-4bc4-9e56-90be58a29a83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产地", "is_correct": true, "explanation": "产地：物品出产的地方，山东是苹果的产地，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是金额，不能是地名山东，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”描述外观，不能是地名山东，句意不通。"}, {"text": "保质期", "is_correct": false, "explanation": "搭配：“保质期”说的是时长，不说“保质期是山东”。"}], "explanations": {"产地": "产地：物品出产的地方，山东是苹果的产地，符合句意。", "价格": "语义：“价格”是金额，不能是地名山东，句意不通。", "颜色": "语义：“颜色”描述外观，不能是地名山东，句意不通。", "保质期": "搭配：“保质期”说的是时长，不说“保质期是山东”。"}, "sentence_index": 0, "correct_answer": "产地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行的产地是上海。", "explanation": "这里应该用〈出发地〉。产地指物品出产的地方，旅行的起点不能说产地。"}, {"text": "他的产地是农民。", "explanation": "这里应该用〈出身〉。产地是物品出产的地方，人的出身不能说产地。"}, {"text": "我想去一条有名的产地参观。", "explanation": "这里应该用〈个〉。产地是地方，量词用个或处，〈条〉用于长的东西，不能修饰产地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产地", "is_correct": true, "explanation": "产地：茶叶出产的地方，产地不同则价格不同，符合句意。"}, {"text": "性别", "is_correct": false, "explanation": "语义：茶叶没有性别，“性别不同”说不通。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：“寿命”指生物的存活年限，不是茶叶的属性，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”用于人和动物，不说茶叶的体重。"}], "explanations": {"产地": "产地：茶叶出产的地方，产地不同则价格不同，符合句意。", "性别": "语义：茶叶没有性别，“性别不同”说不通。", "寿命": "语义：“寿命”指生物的存活年限，不是茶叶的属性，句意不通。", "体重": "搭配：“体重”用于人和动物，不说茶叶的体重。"}, "sentence_index": 6, "correct_answer": "产地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个会议的产地在北京。", "explanation": "这里应该用〈地点〉。产地指物品出产的地方，会议举行的场所不能说产地。"}, {"text": "这本书的产地是《红楼梦》。", "explanation": "这里应该用〈书名〉。产地指物品出产的地方，书的名称不能说产地。"}, {"text": "我的产地是小明。", "explanation": "这里应该用〈名字〉。产地只用于物品，人的名字不能说产地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想去一只有名的产地，看看那里的果园。", "corrected_sentence": "我想去一个有名的产地，看看那里的果园。", "error_description": "错误在量词：产地是地方，应说「一个产地」或「一处产地」；「只」用于动物等，不能修饰产地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些茶叶得产地不同，口感也不同。", "corrected_sentence": "这些茶叶的产地不同，口感也不同。", "error_description": "错误在修饰标记：修饰名词「产地」要用「的」，「得」用于动词或形容词后的补语，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
