INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21560, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西是自然长出来的，没有用化学东西去改变它。", "primary_collocate": null, "pronunciation": "yǒu jī", "ipa": "joʊ˨˩˦ tɕi˥", "syllable_count": 2, "sentences": [{"text": "有机西红柿是自然长大的，没有用化学肥料。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些有机鸡蛋来自小农场。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只吃有机水果。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机蔬菜长得慢，但是味道好。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在阳台上种有机青菜。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的有机面包很受欢迎。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机大米没有用过农药。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外婆家的菜地不用化肥，种的是有机菜。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买有机牛肉的人越来越多。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅用的米和菜都是有机的。", "target_word": "有机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有机食品", "label": "复合"}, {"form": "有机蔬菜", "label": "复合"}], "register": "中性", "sense_fingerprint": "有机:自然长成、没有用化学东西改变的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50c9095a-030e-4bc4-9e56-90be58a29a83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21560, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有机", "is_correct": true, "explanation": "正确答案。有机 yǒujī，指自然长成、没有用化学东西改变。"}, {"text": "游击", "is_correct": false, "explanation": "游击 yóujī：第一个音节声调不同（第二声，有机为第三声），意思是游击。"}, {"text": "幼鸡", "is_correct": false, "explanation": "幼鸡 yòujī：第一个音节声调不同（第四声，有机为第三声），意思是小鸡。"}, {"text": "优级", "is_correct": false, "explanation": "优级 yōují：两个音节的声调都不同（第一声、第二声），意思是优等级别。"}], "explanations": {"有机": "正确答案。有机 yǒujī，指自然长成、没有用化学东西改变。", "游击": "游击 yóujī：第一个音节声调不同（第二声，有机为第三声），意思是游击。", "幼鸡": "幼鸡 yòujī：第一个音节声调不同（第四声，有机为第三声），意思是小鸡。", "优级": "优级 yōují：两个音节的声调都不同（第一声、第二声），意思是优等级别。"}, "sentence_index": null, "correct_answer": "有机"}, "level_3": {"options": [{"text": "有机", "is_correct": true, "explanation": "有机：自然长成、没有用化学东西改变，与“自然长大”“没有用化学肥料”相符。"}, {"text": "人工", "is_correct": false, "explanation": "语义：“人工”与“自然长大”相反，人工西红柿不可能是自然长大的。"}, {"text": "速成", "is_correct": false, "explanation": "语义：“速成”指人为催促快速长成，与“自然长大”矛盾。"}, {"text": "手工", "is_correct": false, "explanation": "搭配：“手工”说的是制作方式，不用来说作物是怎样长成的。"}], "explanations": {"有机": "有机：自然长成、没有用化学东西改变，与“自然长大”“没有用化学肥料”相符。", "人工": "语义：“人工”与“自然长大”相反，人工西红柿不可能是自然长大的。", "速成": "语义：“速成”指人为催促快速长成，与“自然长大”矛盾。", "手工": "搭配：“手工”说的是制作方式，不用来说作物是怎样长成的。"}, "sentence_index": 0, "correct_answer": "有机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个玩具是有机的，很结实。", "explanation": "这里应该用〈人工制造〉。有机指自然长成、未用化学东西改变；玩具是人工制造的，不能用有机修饰。"}, {"text": "这眼温泉是有机的，水温很高。", "explanation": "这里应该用〈天然〉。有机用于自然长成、没有化学东西改变的作物，不用来形容温泉。"}, {"text": "这个电站用有机能源发电。", "explanation": "这里应该用〈绿色〉。有机只用于自然长成的农产品，能源不能用有机修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21560, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "有机", "is_correct": true, "explanation": "正确答案。有机 yǒujī，指自然长成、没有用化学东西改变。"}, {"text": "有几", "is_correct": false, "explanation": "有几 yǒujǐ：末字声调不同（第三声，有机末字为第一声），意思是有多少。"}, {"text": "游记", "is_correct": false, "explanation": "游记 yóujì：两个音节的声调都不同（第二声、第四声），意思是旅行记录。"}, {"text": "邮寄", "is_correct": false, "explanation": "邮寄 yóujì：两个音节的声调都不同（第二声、第四声），意思是通过邮局寄送。"}], "explanations": {"有机": "正确答案。有机 yǒujī，指自然长成、没有用化学东西改变。", "有几": "有几 yǒujǐ：末字声调不同（第三声，有机末字为第一声），意思是有多少。", "游记": "游记 yóujì：两个音节的声调都不同（第二声、第四声），意思是旅行记录。", "邮寄": "邮寄 yóujì：两个音节的声调都不同（第二声、第四声），意思是通过邮局寄送。"}, "sentence_index": null, "correct_answer": "有机"}, "level_3": {"options": [{"text": "有机", "is_correct": true, "explanation": "有机：自然长成、没有用化学东西改变，与“没有用过农药”相符。"}, {"text": "咸", "is_correct": false, "explanation": "语义：大米不是咸的，“咸大米”说不通。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”说的是温度，与后面“没有用过农药”说的种植方式无关。"}, {"text": "辣", "is_correct": false, "explanation": "语义：大米不辣，“辣大米”与句子所说的大米不相符。"}], "explanations": {"有机": "有机：自然长成、没有用化学东西改变，与“没有用过农药”相符。", "咸": "语义：大米不是咸的，“咸大米”说不通。", "烫": "语义：“烫”说的是温度，与后面“没有用过农药”说的种植方式无关。", "辣": "语义：大米不辣，“辣大米”与句子所说的大米不相符。"}, "sentence_index": 6, "correct_answer": "有机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌是有机的，很好听。", "explanation": "这里应该用〈原创〉。有机只用于自然长成的作物，歌曲不能用有机修饰。"}, {"text": "这把椅子是有机的，很精致。", "explanation": "这里应该用〈手工〉。有机指自然长成、未用化学东西改变，椅子是手工做的，不能用有机修饰。"}, {"text": "这辆汽车是有机的，跑得很快。", "explanation": "这里应该用〈新型〉。有机只用于自然长成、没有用化学东西改变的农产品，汽车不能用有机修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家阳台上种的青菜是不有机的，从来不用化肥。", "corrected_sentence": "我家阳台上种的青菜是有机的，从来不用化肥。", "error_description": "错误在于多加了“不”：「是有机的」表示肯定，「是不有机的」自相矛盾，应去掉“不”，说「青菜是有机的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块地里的菜是有机的，种的时候用过很多化肥。", "corrected_sentence": "这块地里的菜不是有机的，种的时候用过很多化肥。", "error_description": "错误在「有机」的用法：用过化肥的菜不能说「是有机的」，有机指没有用化学东西改变，应改为「不是有机的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
