INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21562, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21562, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "放东西的大房子或大空间。", "primary_collocate": null, "pronunciation": "cāng kù", "ipa": "tsʰɑŋ˥ kʰu˥˩", "syllable_count": 2, "sentences": [{"text": "爸爸把不用的东西放进了仓库。", "target_word": "仓库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家后面有一个小仓库。", "target_word": "仓库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "仓库里很黑，我们带着手电筒进去。", "target_word": "仓库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的仓库里放着很多饮料。", "target_word": "仓库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板让我去仓库拿一箱水。", "target_word": "仓库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "仓库的门锁着，我进不去。", "target_word": "仓库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个仓库很大，能放一百辆自行车。", "target_word": "仓库", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天仓库里很热，大家不想进去。", "target_word": "仓库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店的仓库在二楼。", "target_word": "仓库", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在仓库里找到了旧自行车。", "target_word": "仓库", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倉庫", "label": "繁体"}, {"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "仓库：放东西的大房子或大空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50c9095a-030e-4bc4-9e56-90be58a29a83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21562, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仓库", "is_correct": true, "explanation": "正确答案：仓库，指放东西的大房子或大空间。"}, {"text": "长裤", "is_correct": false, "explanation": "长裤 chángkù：声母 ch 与 c 不同，声调也不同（第二声），意思是长的裤子。"}, {"text": "仓促", "is_correct": false, "explanation": "第二音节 cù 与 kù 声母不同（c 与 k），仓促意为匆忙。"}, {"text": "残酷", "is_correct": false, "explanation": "cán（第二声）与 cāng 韵尾不同（an 与 ang）且声调不同，残酷意为残忍。"}], "explanations": {"仓库": "正确答案：仓库，指放东西的大房子或大空间。", "长裤": "长裤 chángkù：声母 ch 与 c 不同，声调也不同（第二声），意思是长的裤子。", "仓促": "第二音节 cù 与 kù 声母不同（c 与 k），仓促意为匆忙。", "残酷": "cán（第二声）与 cāng 韵尾不同（an 与 ang）且声调不同，残酷意为残忍。"}, "sentence_index": null, "correct_answer": "仓库"}, "level_3": {"options": [{"text": "仓库", "is_correct": true, "explanation": "正确：仓库是放不用东西的大房子，符合语境。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是能装东西的地方，「放进了天空」不成立。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：「放进」所接的宾语是可以装进去的东西，「名字」是抽象的，不能被放进去。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被当作容器装东西，「放进了空气」不合逻辑。"}], "explanations": {"仓库": "正确：仓库是放不用东西的大房子，符合语境。", "天空": "语义：天空不是能装东西的地方，「放进了天空」不成立。", "名字": "搭配：「放进」所接的宾语是可以装进去的东西，「名字」是抽象的，不能被放进去。", "空气": "语义：空气不能被当作容器装东西，「放进了空气」不合逻辑。"}, "sentence_index": 0, "correct_answer": "仓库"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们在仓库里看书。", "explanation": "这里应该用〈图书馆〉。看书要去图书馆，仓库是存放东西的大空间，不供人读书。"}, {"text": "医生每天在仓库里看病。", "explanation": "这里应该用〈诊室〉。看病要在诊室，仓库是存放东西的大空间。"}, {"text": "老师在仓库里讲课。", "explanation": "这里应该用〈教室〉。讲课要在教室，仓库是存放东西的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仓库", "is_correct": true, "explanation": "正确：仓库是大空间，能放一百辆自行车。"}, {"text": "口袋", "is_correct": false, "explanation": "语义：口袋很小，放不下一百辆自行车。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包很小，装不下一百辆自行车。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不是可以放东西的容器，「能放一百辆自行车」的说法不成立。"}], "explanations": {"仓库": "正确：仓库是大空间，能放一百辆自行车。", "口袋": "语义：口袋很小，放不下一百辆自行车。", "书包": "语义：书包很小，装不下一百辆自行车。", "大海": "语义：大海不是可以放东西的容器，「能放一百辆自行车」的说法不成立。"}, "sentence_index": 6, "correct_answer": "仓库"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在仓库里读书，找到了旧自行车。", "explanation": "这里应该用〈图书馆〉。读书要去图书馆，仓库是存放东西的大空间，不供人读书。"}, {"text": "他在仓库里看病，找到了旧自行车。", "explanation": "这里应该用〈诊室〉。看病要在诊室，仓库是存放东西的大空间。"}, {"text": "他在仓库里上课，找到了旧自行车。", "explanation": "这里应该用〈教室〉。上课要在教室，仓库是存放东西的大空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去着仓库。", "corrected_sentence": "他去过仓库。", "error_description": "错误在体标记：表示曾经去过要用「过」，「去着」的「着」表示持续，不用于这里，应说「他去过仓库」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们租下了一只仓库。", "corrected_sentence": "我们租下了一座仓库。", "error_description": "量词用错：仓库应用量词「座」，不能用「只」。错误形式「一只仓库」应改为「一座仓库」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
