INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21568, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "消费国就是买很多东西用的国家。", "primary_collocate": null, "pronunciation": "xiāo fèi guó", "ipa": "ɕiɑʊ˥ feɪ˥˩ ku̯ɔ˧˥", "syllable_count": 3, "sentences": [{"text": "日本是很大的茶叶消费国。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消费国的人买很多东西。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消费国每年进口大量手机。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巧克力的主要消费国在欧洲。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国既是生产国，也是重要的消费国。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家人多钱多，是最大的汽车消费国。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡从产地运到消费国，价格会变高。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消费国的人们爱喝咖啡，所以进口很多咖啡豆。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多水果从南方的国家卖到北方的消费国。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小国不种大米，是大米消费国。", "target_word": "消费国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "消费国:买很多东西用的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50c9095a-030e-4bc4-9e56-90be58a29a83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消费国", "is_correct": true, "explanation": "消费国指买很多东西的国家，日本是大量买茶叶的国家，符合句意。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：国家不能是工厂，“很大的茶叶工厂”与句意不符。"}, {"text": "老外", "is_correct": false, "explanation": "语义：“老外”指外国人，不指国家，日本不能是“茶叶老外”。"}, {"text": "茶馆", "is_correct": false, "explanation": "语义：国家不是茶馆，“很大的茶叶茶馆”说的是店铺，与句中国家主体不符。"}], "explanations": {"消费国": "消费国指买很多东西的国家，日本是大量买茶叶的国家，符合句意。", "工厂": "语义：国家不能是工厂，“很大的茶叶工厂”与句意不符。", "老外": "语义：“老外”指外国人，不指国家，日本不能是“茶叶老外”。", "茶馆": "语义：国家不是茶馆，“很大的茶叶茶馆”说的是店铺，与句中国家主体不符。"}, "sentence_index": 0, "correct_answer": "消费国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "日本每年向海外大量出口汽车，国内却几乎不买车，是重要的消费国。", "explanation": "这里应该用〈出口国〉。句中说国内几乎不买车，却称消费国，应说出口国；消费国指大量买入、消耗商品的国家。"}, {"text": "这家贸易公司每年大量买进茶叶，是重要的消费国。", "explanation": "这里应该用〈采购商〉。消费国指国家，公司买进茶叶应说〈采购商〉，不能作为消费国。"}, {"text": "这位老师是个很大的消费国。", "explanation": "这里指人不妥：〈消费国〉指国家，不能指个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消费国", "is_correct": true, "explanation": "消费国是买入商品的国家，咖啡运到它那里价格会变高，符合句意。"}, {"text": "产地", "is_correct": false, "explanation": "语义：咖啡本来就从产地出发，不能再“运到产地”，运输终点应是买入的一方。"}, {"text": "银行", "is_correct": false, "explanation": "语义：咖啡不会被运到银行，句中运输的终点应是买入咖啡的国家。"}, {"text": "大爷", "is_correct": false, "explanation": "语域：“大爷”是口语词，与本句语体不协调；且它指人，不指国家。"}], "explanations": {"消费国": "消费国是买入商品的国家，咖啡运到它那里价格会变高，符合句意。", "产地": "语义：咖啡本来就从产地出发，不能再“运到产地”，运输终点应是买入的一方。", "银行": "语义：咖啡不会被运到银行，句中运输的终点应是买入咖啡的国家。", "大爷": "语域：“大爷”是口语词，与本句语体不协调；且它指人，不指国家。"}, "sentence_index": 6, "correct_answer": "消费国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司每年大量买进大米，是大米消费国。", "explanation": "这里指公司不妥：〈消费国〉指国家，公司不能作为消费国。"}, {"text": "这个小国大量种植大米，却从来不吃大米，是大米消费国。", "explanation": "这里应该用〈生产国〉。大量种植大米是生产，且从不吃大米，不符合消费国的定义。"}, {"text": "这个小国每年向邻国供应大量大米，本国却几乎不买大米，是重要的大米消费国。", "explanation": "这里应该用〈出口国〉。句中说本国几乎不买大米、只向邻国供应，应说出口国；消费国指大量买入、消耗商品的国家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小国每年大量买进茶叶，是一座重要的消费国。", "corrected_sentence": "这个小国每年大量买进茶叶，是一个重要的消费国。", "error_description": "量词错误：国家应用“个”，不用“座”。“座”多用于山、桥、楼等，应改为“一个重要的消费国”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只消费国的人喜欢买进口的咖啡。", "corrected_sentence": "那个消费国的人喜欢买进口的咖啡。", "error_description": "量词错误：国家应用“个”，不用“只”。“只”多用于动物等，应改为“那个消费国”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cd61532-1005-4957-8f74-703e67d82132') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21570, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "推卸", "is_correct": true, "explanation": "正确。推卸指推开自己应负的责任，与承担正好相反。"}, {"text": "修建", "is_correct": false, "explanation": "修建指建造房屋或道路，与承担没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察指仔细看，与承担没有反义关系。"}, {"text": "欢迎", "is_correct": false, "explanation": "欢迎指表示接待或喜爱，与承担没有反义关系。"}], "correct_answer": "推卸", "explanations": {"推卸": "正确。推卸指推开自己应负的责任，与承担正好相反。", "修建": "修建指建造房屋或道路，与承担没有反义关系。", "观察": "观察指仔细看，与承担没有反义关系。", "欢迎": "欢迎指表示接待或喜爱，与承担没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21570, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "推卸", "is_correct": true, "explanation": "正确。推卸指推开自己应负的责任，与“大哥承担起照顾弟弟的责任”正好相反。"}, {"text": "批评", "is_correct": false, "explanation": "批评指指出错误，与承担没有反义关系。"}, {"text": "询问", "is_correct": false, "explanation": "询问指提出问题请人回答，与承担没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫指清除脏物，与承担没有反义关系。"}], "correct_answer": "推卸", "explanations": {"推卸": "正确。推卸指推开自己应负的责任，与“大哥承担起照顾弟弟的责任”正好相反。", "批评": "批评指指出错误，与承担没有反义关系。", "询问": "询问指提出问题请人回答，与承担没有反义关系。", "打扫": "打扫指清除脏物，与承担没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21570, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己把应该做的事情接过来做。", "primary_collocate": null, "pronunciation": "chéng dān", "ipa": "ʈʂʰɤŋ˧˥ tan˥", "syllable_count": 2, "sentences": [{"text": "这件事我来承担。", "target_word": "承担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他愿意承担这个责任。", "target_word": "承担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一个人承担了所有的工作。", "target_word": "承担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来承担这次的费用？", "target_word": "承担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你做错了事，就要自己承担后果。", "target_word": "承担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈承担了家里的大部分家务。", "target_word": "承担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司承担了我们的旅行费用。", "target_word": "承担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承担着一家人的生计。", "target_word": "承担", "complexity_tier": "T3", "furigana": "tā chéngdān zhe yì jiā rén de shēngjì.", "sentence_source": "generated"}, {"text": "这个错误由我承担。", "target_word": "承担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大哥承担起照顾弟弟的责任。", "target_word": "承担", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "承担了", "label": "体标"}, {"form": "承担过", "label": "体标"}, {"form": "承担着", "label": "体标"}, {"form": "承擔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "承担：主动接下责任、工作或费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f562dea-1484-4d6c-8f48-09986f773a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21570, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "承担", "is_correct": true, "explanation": "正确。“这件事我来承担”中，承担表示自己接过来负责，与“我来”的语境吻合。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：逃避是躲开、回避，与“我来”主动接手的语境相反。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记是记不住，与“我来”接手事情的意思不符。"}, {"text": "发生", "is_correct": false, "explanation": "配价：发生指事情自然出现，主语是事情而非人，“我来发生”搭配不通。"}], "explanations": {"承担": "正确。“这件事我来承担”中，承担表示自己接过来负责，与“我来”的语境吻合。", "逃避": "语义：逃避是躲开、回避，与“我来”主动接手的语境相反。", "忘记": "语义：忘记是记不住，与“我来”接手事情的意思不符。", "发生": "配价：发生指事情自然出现，主语是事情而非人，“我来发生”搭配不通。"}, "sentence_index": 0, "correct_answer": "承担"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他承担了班长。", "explanation": "这里应该用〈担任〉。承担用于任务、责任或费用，职位要说担任班长。"}, {"text": "他承担了这场比赛的第一名。", "explanation": "这里应该用〈获得〉。承担指接下责任、工作或费用，名次要靠比赛赢得，应说获得第一名。"}, {"text": "他承担了一次午睡。", "explanation": "这里应该用〈享受〉。承担指接下责任或费用，午睡是享受的，不能承担，应说享受午睡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "承担", "is_correct": true, "explanation": "正确。“公司承担了我们的旅行费用”中，承担表示公司接过费用，搭配自然。"}, {"text": "访问", "is_correct": false, "explanation": "语义：访问是拜访、探问，不能用来指费用，与“承担费用”的意思不符。"}, {"text": "恳求", "is_correct": false, "explanation": "配价：恳求要带请求的内容或对象，不能直接以“费用”作宾语。"}, {"text": "执行", "is_correct": false, "explanation": "搭配：执行常与计划、命令搭配，不说“执行费用”。"}], "explanations": {"承担": "正确。“公司承担了我们的旅行费用”中，承担表示公司接过费用，搭配自然。", "访问": "语义：访问是拜访、探问，不能用来指费用，与“承担费用”的意思不符。", "恳求": "配价：恳求要带请求的内容或对象，不能直接以“费用”作宾语。", "执行": "搭配：执行常与计划、命令搭配，不说“执行费用”。"}, "sentence_index": 6, "correct_answer": "承担"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根柱子承担了整个屋顶的费用。", "explanation": "这里承担用错了对象。承担的是责任、工作或费用，费用要由人或机构承担，柱子不能承担费用，应说支撑屋顶。"}, {"text": "地基承担了整栋楼的后果。", "explanation": "这里承担用错了对象。承担后果是人接下责任的说法，地基不能承担后果，应说支撑整栋楼。"}, {"text": "这座桥承担了每天的会议。", "explanation": "这里承担用错了对象。承担指接下任务，会议要由人组织，桥不能承担会议，应说承受车流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔损失由公司正在承担了。", "corrected_sentence": "这笔损失由公司承担了。", "error_description": "错误：“正在承担了”，正确：“承担了”。“正在”表示动作进行中，与“了”表示完成相冲突，应去掉“正在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父亲承担上了全家的开销。", "corrected_sentence": "父亲承担起了全家的开销。", "error_description": "错误：“承担上”，正确：“承担起”。接过责任或负担时要用“起”作补语，“上”不能与承担搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
