INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21578, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得到自己想要的东西。", "primary_collocate": null, "pronunciation": "huò", "ipa": "xwo˥˩", "syllable_count": 1, "sentences": [{"text": "他等了很久，终于获自由。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她努力工作，终于获老板信任。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店终于获政府批准。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的请求获老师同意。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的申请获学校批准，可以去北京学习了。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的计划获很多人支持。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一生善良，获大家尊重。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画在比赛中获一等奖。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法获经理支持，大家很高兴。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的建议获公司采纳。", "target_word": "获", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "獲", "label": "繁体"}], "register": "书面", "sense_fingerprint": "书面语，经过努力或请求，得到自己想要的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578294a7-0823-4619-bc2b-d5210b7acc13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21578, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "获", "is_correct": true, "explanation": "获（huò）即得到自己想要的东西，是本词的读音和意思。"}, {"text": "火", "is_correct": false, "explanation": "huǒ（第三声）与 huò（第四声）声调不同，意思是火。"}, {"text": "活", "is_correct": false, "explanation": "huó（第二声）与 huò（第四声）声调不同，意思是活。"}, {"text": "户", "is_correct": false, "explanation": "hù（第四声）与 huò 韵母不同（u 与 uo），意思是户。"}, {"text": "伙", "is_correct": false, "explanation": "huǒ（第三声）与 huò（第四声）声调不同，意思是伙（伙伴）。"}], "explanations": {"获": "获（huò）即得到自己想要的东西，是本词的读音和意思。", "火": "huǒ（第三声）与 huò（第四声）声调不同，意思是火。", "活": "huó（第二声）与 huò（第四声）声调不同，意思是活。", "户": "hù（第四声）与 huò 韵母不同（u 与 uo），意思是户。", "伙": "huǒ（第三声）与 huò（第四声）声调不同，意思是伙（伙伴）。"}, "sentence_index": null, "correct_answer": "获"}, "level_3": {"options": [{"text": "获", "is_correct": true, "explanation": "获：得到想要的东西，与“自由”搭配，符合“等了很久，终于得到”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃自由。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物，不能说穿自由。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢掉，与“终于得到”的意思相反，句意不通。"}], "explanations": {"获": "获：得到想要的东西，与“自由”搭配，符合“等了很久，终于得到”的语境。", "吃": "搭配：“吃”的对象是食物，不能说吃自由。", "穿": "搭配：“穿”的对象是衣物，不能说穿自由。", "扔": "语义：“扔”是丢掉，与“终于得到”的意思相反，句意不通。"}, "sentence_index": 0, "correct_answer": "获"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师很快获了我的请求。", "explanation": "这里应该用〈答应〉。获指得到想要的东西，回应别人的请求要用“答应”。"}, {"text": "他昨天获了一个电话，很惊讶。", "explanation": "这里应该用〈接到〉。获不用于接电话，接到电话要用“接到”。"}, {"text": "他把那只旧鞋获了。", "explanation": "这里应该用〈扔〉。获指得到自己想要的东西，丢掉不要的旧东西要用“扔”，不能用获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21578, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "获", "is_correct": true, "explanation": "获（huò）即得到自己想要的东西，是本词的读音和意思。"}, {"text": "活", "is_correct": false, "explanation": "huó（第二声）与 huò（第四声）声调不同，意思是活。"}, {"text": "伙", "is_correct": false, "explanation": "huǒ（第三声）与 huò（第四声）声调不同，意思是伙（伙伴）。"}, {"text": "护", "is_correct": false, "explanation": "hù（第四声）与 huò 只差韵母中的一个 o，声调相同，意思是保护。"}, {"text": "互", "is_correct": false, "explanation": "hù（第四声）与 huò 只差韵母中的一个 o，声调相同，意思是相互。"}], "explanations": {"获": "获（huò）即得到自己想要的东西，是本词的读音和意思。", "活": "huó（第二声）与 huò（第四声）声调不同，意思是活。", "伙": "huǒ（第三声）与 huò（第四声）声调不同，意思是伙（伙伴）。", "护": "hù（第四声）与 huò 只差韵母中的一个 o，声调相同，意思是保护。", "互": "hù（第四声）与 huò 只差韵母中的一个 o，声调相同，意思是相互。"}, "sentence_index": null, "correct_answer": "获"}, "level_3": {"options": [{"text": "获", "is_correct": true, "explanation": "获：得到，与“尊重”搭配，表示得到大家的尊重，符合语境。"}, {"text": "挡", "is_correct": false, "explanation": "语义：“挡”是阻拦，与“尊重”意思不合，句意不通。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象是球等，不能说踢尊重。"}, {"text": "抽", "is_correct": false, "explanation": "搭配：“抽”的对象是烟、签等，不能说抽尊重。"}], "explanations": {"获": "获：得到，与“尊重”搭配，表示得到大家的尊重，符合语境。", "挡": "语义：“挡”是阻拦，与“尊重”意思不合，句意不通。", "踢": "搭配：“踢”的对象是球等，不能说踢尊重。", "抽": "搭配：“抽”的对象是烟、签等，不能说抽尊重。"}, "sentence_index": 6, "correct_answer": "获"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆获给我三本书。", "explanation": "这里应该用〈借给〉。获指得到想要的东西，把书借出去要用“借给”。"}, {"text": "他终于获了这个难题。", "explanation": "这里应该用〈解决〉。获不能用于难题，解决问题要用“解决”。"}, {"text": "公司获了他的损失。", "explanation": "这里应该用〈赔偿〉。获指得到想要的东西，补偿别人的损失要用“赔偿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划获被经理支持。", "corrected_sentence": "这个计划获经理支持。", "error_description": "多余成分：“获”后直接接对象，不能加“被”，“获被”不对，正确形式是“获经理支持”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个申请终于了获批准。", "corrected_sentence": "这个申请终于获批准。", "error_description": "体标错误：“了”不能放在“获”之前，“了获”不对；书面语直接说“获批准”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21580, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "损失", "is_correct": true, "explanation": "反义：“收益”指得到的好处，“损失”指失去的好处，二者意思相反。"}, {"text": "地图", "is_correct": false, "explanation": "无关：“地图”是指示方向的图纸，与“收益”没有反义关系。"}, {"text": "绳子", "is_correct": false, "explanation": "无关：“绳子”是用来捆扎的物品，与“收益”没有反义关系。"}, {"text": "花园", "is_correct": false, "explanation": "无关：“花园”是种植花草的场所，与“收益”没有反义关系。"}], "correct_answer": "损失", "explanations": {"损失": "反义：“收益”指得到的好处，“损失”指失去的好处，二者意思相反。", "地图": "无关：“地图”是指示方向的图纸，与“收益”没有反义关系。", "绳子": "无关：“绳子”是用来捆扎的物品，与“收益”没有反义关系。", "花园": "无关：“花园”是种植花草的场所，与“收益”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21580, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "损失", "is_correct": true, "explanation": "反义：句中说“得到了不少收益”，与之相反的是“损失”。"}, {"text": "钟表", "is_correct": false, "explanation": "无关：“钟表”是计时的器具，与“收益”没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "无关：“石头”是自然物体，与“收益”没有反义关系。"}, {"text": "教室", "is_correct": false, "explanation": "无关：“教室”是学习的场所，与“收益”没有反义关系。"}], "correct_answer": "损失", "explanations": {"损失": "反义：句中说“得到了不少收益”，与之相反的是“损失”。", "钟表": "无关：“钟表”是计时的器具，与“收益”没有反义关系。", "石头": "无关：“石头”是自然物体，与“收益”没有反义关系。", "教室": "无关：“教室”是学习的场所，与“收益”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21580, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "得到的好处。", "primary_collocate": null, "pronunciation": "shōu yì", "ipa": "ʂoʊ⁵⁵ i⁵¹", "syllable_count": 2, "sentences": [{"text": "读书的收益，不只是考试成绩。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次实习，我的收益比想象中大得多。", "target_word": "收益", "complexity_tier": "T3", "furigana": "shōu yì", "sentence_source": "generated"}, {"text": "这次培训的收益很大，大家都学到了新方法。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坚持锻炼的收益很明显，身体更健康了。", "target_word": "收益", "complexity_tier": "T3", "furigana": "shōu yì", "sentence_source": "generated"}, {"text": "学外语的收益，过几年才能看到。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书，收益会一点点积累。", "target_word": "收益", "complexity_tier": "T3", "furigana": "shōu yì", "sentence_source": "generated"}, {"text": "这个办法的收益比成本大。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛，对我来说最大的收益是经验。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小小的改变也会带来收益。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从这次合作中得到了不少收益。", "target_word": "收益", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收益率", "label": "复合"}], "register": "书面语", "sense_fingerprint": "做某事之后得到的一般好处、帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45fe73ad-99b7-41e9-9b37-32d47e8af85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收益", "is_correct": true, "explanation": "正确：读书带来的是知识、能力等一般好处，“收益”符合“不只是考试成绩”的语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能作为读书带来的好处，与句意不符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是物理量，不能说“读书的温度”，与句意冲突。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”口语随意，与这句书面的论述不相称。"}], "explanations": {"收益": "正确：读书带来的是知识、能力等一般好处，“收益”符合“不只是考试成绩”的语境。", "颜色": "语义：颜色不能作为读书带来的好处，与句意不符。", "温度": "语义：温度是物理量，不能说“读书的温度”，与句意冲突。", "玩意儿": "语域：“玩意儿”口语随意，与这句书面的论述不相称。"}, "sentence_index": 0, "correct_answer": "收益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次失误的收益很严重，大家都很担心。", "explanation": "这里应该用〈后果〉。收益指得到的好处，不能说“很严重”；表示不好的结果应说〈后果〉。"}, {"text": "这次实习给我带来了一头收益。", "explanation": "这里应该用〈点〉。“收益”这类抽象事物用量词“点”，“头”多用于牲畜等具体事物。"}, {"text": "这段时间我白白浪费了很多收益。", "explanation": "这里应该用〈时间〉。收益指得到的好处，不能说“浪费”；被浪费的应是时间、精力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收益", "is_correct": true, "explanation": "正确：比较办法的好处与成本，“收益比成本大”指得到的好处超过付出，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能与“成本”比较大小，与句意冲突。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“比……大”可用于效果、数量，不能说“性格比成本大”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能与成本相比较大小，与评价办法的语境不相容。"}], "explanations": {"收益": "正确：比较办法的好处与成本，“收益比成本大”指得到的好处超过付出，符合语境。", "天气": "语义：天气是自然现象，不能与“成本”比较大小，与句意冲突。", "性格": "搭配：“比……大”可用于效果、数量，不能说“性格比成本大”。", "玩具": "语义：玩具不能与成本相比较大小，与评价办法的语境不相容。"}, "sentence_index": 6, "correct_answer": "收益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次合作付出了不少收益。", "explanation": "这里应该用〈代价〉。收益是得到的好处，不能与“付出”搭配。"}, {"text": "这次事故给他带来了很大的收益。", "explanation": "这里应该用〈伤害〉。收益是好的结果，不能用来描述事故带来的不好影响。"}, {"text": "他从银行借到了一大笔收益。", "explanation": "这里应该用〈资金〉。收益不能用“借”，“借”的是钱款或资金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次实习给我带来了一场收益。", "corrected_sentence": "这次实习给我带来了一点收益。", "error_description": "量词错误：“场”用于比赛、活动等，“收益”应用“点”，正确说法是“一点收益”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次实习的收益的很大。", "corrected_sentence": "这次实习的收益很大。", "error_description": "“收益”后多出一个“的”，应去掉，正确说法是“这次实习的收益很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
