INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21588, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可以代表同一类事物中特点最明显的那个。", "primary_collocate": null, "pronunciation": "diǎn xíng", "ipa": "tjɛn˨˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这座房子是北京四合院的典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个病例是这种病的典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老虎是猫科动物中的典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首诗是唐诗中山水诗的典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道菜是四川菜的典型，又麻又辣。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "苏州是江南水乡的典型。", "target_word": "典型", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他上课总迟到，是懒散的典型。", "target_word": "典型", "complexity_tier": "T3", "furigana": "tā shàng kè zǒng chí dào, shì lǎn sǎn de diǎn xíng.", "sentence_source": "generated"}, {"text": "这个案例是老师给我们挑的典型。", "target_word": "典型", "complexity_tier": "T3", "furigana": "zhè ge àn lì shì lǎo shī gěi wǒ men tiāo de diǎn xíng.", "sentence_source": "generated"}, {"text": "这个例子很简单，是这类问题的典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器是同类产品中的典型。", "target_word": "典型", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "典型性", "label": "复合"}], "register": "中性", "sense_fingerprint": "同类事物中特点最明显的代表", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7cbd58c-699e-471e-90b4-643ce1bb9923') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21588, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "典型", "is_correct": true, "explanation": "正确答案。典型（diǎn xíng）：同类事物中特点最明显的代表。"}, {"text": "点醒", "is_correct": false, "explanation": "点醒（diǎn xǐng）与典型末字声调不同：xǐng（第三声）与 xíng（第二声），意思是提醒、点拨。"}, {"text": "脸型", "is_correct": false, "explanation": "脸型（liǎn xíng）与典型首字声母不同：l 与 d，意思是脸的形状。"}, {"text": "显形", "is_correct": false, "explanation": "显形（xiǎn xíng）与典型首字声母不同：x 与 d，意思是显露出原形。"}], "explanations": {"典型": "正确答案。典型（diǎn xíng）：同类事物中特点最明显的代表。", "点醒": "点醒（diǎn xǐng）与典型末字声调不同：xǐng（第三声）与 xíng（第二声），意思是提醒、点拨。", "脸型": "脸型（liǎn xíng）与典型首字声母不同：l 与 d，意思是脸的形状。", "显形": "显形（xiǎn xíng）与典型首字声母不同：x 与 d，意思是显露出原形。"}, "sentence_index": null, "correct_answer": "典型"}, "level_3": {"options": [{"text": "典型", "is_correct": true, "explanation": "正确。“典型”指同类中有代表性的事物，放在“北京四合院的___”处，句意通顺。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指买卖时的钱数，房子不能是某种建筑的价格，句意不通。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口指一个地区的居民总数，与建筑类型无关，句意不通。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是庆祝的日子，房子不能是某种建筑的节日，句意不通。"}], "explanations": {"典型": "正确。“典型”指同类中有代表性的事物，放在“北京四合院的___”处，句意通顺。", "价格": "语义：价格指买卖时的钱数，房子不能是某种建筑的价格，句意不通。", "人口": "语义：人口指一个地区的居民总数，与建筑类型无关，句意不通。", "节日": "语义：节日是庆祝的日子，房子不能是某种建筑的节日，句意不通。"}, "sentence_index": 0, "correct_answer": "典型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两本书的典型不同，一本是小说，一本是诗集。", "explanation": "这里应该用〈类型〉。“典型”指同类中最有代表性的实例，不指作品的种类，这句应说“类型不同”。"}, {"text": "这首诗用了很多典型，读起来有些难懂。", "explanation": "这里应该用〈典故〉。“典型”指同类中有代表性的实例，不指诗中引用的历史故事，这里应说“典故”。"}, {"text": "这首诗的典型是大量描写山水。", "explanation": "这里应该用〈特征〉。“典型”指同类中最有代表性的事物本身，不能用来表示事物的特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21588, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "典型", "is_correct": true, "explanation": "正确答案。典型（diǎn xíng）：同类事物中特点最明显的代表。"}, {"text": "电刑", "is_correct": false, "explanation": "电刑（diàn xíng）与典型首字声调不同：diàn（第四声）与 diǎn（第三声），指用电流执行的刑罚。"}, {"text": "脸型", "is_correct": false, "explanation": "脸型（liǎn xíng）与典型首字声母不同：l 与 d，意思是脸的形状。"}, {"text": "扁形", "is_correct": false, "explanation": "扁形（biǎn xíng）与典型首字声母不同：b 与 d，声调相同，意思是扁平的形状。"}], "explanations": {"典型": "正确答案。典型（diǎn xíng）：同类事物中特点最明显的代表。", "电刑": "电刑（diàn xíng）与典型首字声调不同：diàn（第四声）与 diǎn（第三声），指用电流执行的刑罚。", "脸型": "脸型（liǎn xíng）与典型首字声母不同：l 与 d，意思是脸的形状。", "扁形": "扁形（biǎn xíng）与典型首字声母不同：b 与 d，声调相同，意思是扁平的形状。"}, "sentence_index": null, "correct_answer": "典型"}, "level_3": {"options": [{"text": "典型", "is_correct": true, "explanation": "正确。“典型”指同类中有代表性的人，放在“懒散的___”处，句意通顺。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“懒散”修饰的是人的作风或性格，“懒散的寿命”不成词，不能与“懒散”搭配。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是工具书，不能指人的懒散程度，句意不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是教学用书，不能用来形容一个人的懒散，句意不通。"}], "explanations": {"典型": "正确。“典型”指同类中有代表性的人，放在“懒散的___”处，句意通顺。", "寿命": "搭配：“懒散”修饰的是人的作风或性格，“懒散的寿命”不成词，不能与“懒散”搭配。", "词典": "语义：词典是工具书，不能指人的懒散程度，句意不通。", "课本": "语义：课本是教学用书，不能用来形容一个人的懒散，句意不通。"}, "sentence_index": 6, "correct_answer": "典型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的典型很有名，每天都要排队。", "explanation": "这里应该用〈招牌〉。“典型”指同类中有代表性的实例，不指店里最出名的招牌菜。"}, {"text": "这次比赛他拿到了一个典型，非常开心。", "explanation": "这里应该用〈奖牌〉。“典型”指同类中有代表性的人或事物，不指比赛的奖项。"}, {"text": "他送给我一个飞机典型。", "explanation": "这里应该用〈模型〉。“典型”指同类中有代表性的实例，不指仿制的缩小品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位画家是印象派的一只典型。", "corrected_sentence": "这位画家是印象派的一个典型。", "error_description": "量词错误：“典型”指有代表性的人或事物，应与“个”搭配，写作“一个典型”；“只”多用于动物，不能修饰“典型”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座山是中国北方高山典型。", "corrected_sentence": "这座山是中国北方高山的典型。", "error_description": "漏掉“的”：“中国北方高山”作定语修饰“典型”，应写作“中国北方高山的典型”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21590, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21590, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21590, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示“但是”，用来连接前后不一样的事情。", "primary_collocate": null, "pronunciation": "què", "ipa": "tɕʰɥɛ˥˩", "syllable_count": 1, "sentences": [{"text": "他很想去，却没有时间。", "target_word": "却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很冷，他却只穿了一件衬衫。", "target_word": "却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给她打了电话，她却没接。", "target_word": "却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服很漂亮，价格却不贵。", "target_word": "却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得很好，做起来却很难。", "target_word": "却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在笑，他却哭了。", "target_word": "却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟年纪小，却懂很多事。", "target_word": "却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我等了他一个小时，他却没来。", "target_word": "却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下着大雨，她却高兴地跑了出去。", "target_word": "却", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆不大，菜却很好吃。", "target_word": "却", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，表示转折，前后两件事情相反或不合预期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f511cdf7-32fc-4ebd-97bd-19cfb744bda7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21590, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "却", "is_correct": true, "explanation": "却（第四声）表示“但是”，用来连接前后不一样的事情。"}, {"text": "缺", "is_correct": false, "explanation": "缺（第一声）与却 què 声调不同，意思是缺少、不足。"}, {"text": "取", "is_correct": false, "explanation": "取（第三声）与却 què 声调不同，意思是拿、获得。"}, {"text": "去", "is_correct": false, "explanation": "去（第四声）与却 què 只差韵母一个音（ü 与 üe），意思是离开、前往。"}, {"text": "区", "is_correct": false, "explanation": "区（第一声）与却 què 声调不同，意思是地区、区域。"}], "explanations": {"却": "却（第四声）表示“但是”，用来连接前后不一样的事情。", "缺": "缺（第一声）与却 què 声调不同，意思是缺少、不足。", "取": "取（第三声）与却 què 声调不同，意思是拿、获得。", "去": "去（第四声）与却 què 只差韵母一个音（ü 与 üe），意思是离开、前往。", "区": "区（第一声）与却 què 声调不同，意思是地区、区域。"}, "sentence_index": null, "correct_answer": "却"}, "level_3": {"options": [{"text": "却", "is_correct": true, "explanation": "正确：“却”表示转折，连接“很想去”与“没有时间”这两件相反的事。"}, {"text": "就", "is_correct": false, "explanation": "语义：“就”表示顺接或结果，“很想去”与“没有时间”之间不是因果关系，这里不能用“就”。"}, {"text": "都", "is_correct": false, "explanation": "语义：“都”表示全部或连同，与前后的转折关系不符，“他很想去，都没有时间”不通。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示“只有到……才”或时间刚好，与前后的对立关系不符，“才没有时间”不通。"}], "explanations": {"却": "正确：“却”表示转折，连接“很想去”与“没有时间”这两件相反的事。", "就": "语义：“就”表示顺接或结果，“很想去”与“没有时间”之间不是因果关系，这里不能用“就”。", "都": "语义：“都”表示全部或连同，与前后的转折关系不符，“他很想去，都没有时间”不通。", "才": "语义：“才”表示“只有到……才”或时间刚好，与前后的对立关系不符，“才没有时间”不通。"}, "sentence_index": 0, "correct_answer": "却"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不仅聪明，却很努力。", "explanation": "这里是递进关系，应该用〈而且〉。〈却〉表示前后相反，“聪明”与“努力”并不对立，所以不能用“却”。"}, {"text": "因为下雨，我们却没去公园。", "explanation": "这里是因果关系，应该用〈所以〉。“因为下雨”与“没去公园”是顺理成章的因果，不是相反的情况，不能用“却”。"}, {"text": "他会英语，却会法语。", "explanation": "这里是并列补充的关系，应该用〈还〉。〈却〉表示前后相反，而会英语与会法语并不对立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21590, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "却", "is_correct": true, "explanation": "却（第四声）表示“但是”，用来连接前后不一样的事情。"}, {"text": "曲", "is_correct": false, "explanation": "曲（第三声）与却 què 声调不同，意思是弯曲、曲子。"}, {"text": "趣", "is_correct": false, "explanation": "趣（第四声）与却 què 只差韵母一个音（ü 与 üe），意思是趣味、兴趣。"}, {"text": "屈", "is_correct": false, "explanation": "屈（第一声）与却 què 声调不同，意思是弯曲、屈服。"}, {"text": "娶", "is_correct": false, "explanation": "娶（第三声）与却 què 声调不同，意思是男子结婚时取妻。"}], "explanations": {"却": "却（第四声）表示“但是”，用来连接前后不一样的事情。", "曲": "曲（第三声）与却 què 声调不同，意思是弯曲、曲子。", "趣": "趣（第四声）与却 què 只差韵母一个音（ü 与 üe），意思是趣味、兴趣。", "屈": "屈（第一声）与却 què 声调不同，意思是弯曲、屈服。", "娶": "娶（第三声）与却 què 声调不同，意思是男子结婚时取妻。"}, "sentence_index": null, "correct_answer": "却"}, "level_3": {"options": [{"text": "却", "is_correct": true, "explanation": "正确：“却”表示转折，连接“年纪小”与“懂很多事”这两件相反的事。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示限定，“只懂很多事”与“年纪小”之间的意思不通，不符合语境。"}, {"text": "最", "is_correct": false, "explanation": "搭配：“最”要求有比较的范围，这里前面没有可比较的对象，“最懂很多事”不通。"}, {"text": "太", "is_correct": false, "explanation": "语义：“太”表示过分，多修饰形容词，“太懂很多事”不通，与“年纪小”的转折无关。"}], "explanations": {"却": "正确：“却”表示转折，连接“年纪小”与“懂很多事”这两件相反的事。", "只": "语义：“只”表示限定，“只懂很多事”与“年纪小”之间的意思不通，不符合语境。", "最": "搭配：“最”要求有比较的范围，这里前面没有可比较的对象，“最懂很多事”不通。", "太": "语义：“太”表示过分，多修饰形容词，“太懂很多事”不通，与“年纪小”的转折无关。"}, "sentence_index": 6, "correct_answer": "却"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他吃完晚饭，却去图书馆了。", "explanation": "这里只是先后顺序，应该用〈然后〉。〈却〉表示前后相反，这里没有相反的意思。"}, {"text": "他很聪明，却很帅。", "explanation": "这里是并列补充的关系，应该用〈还〉。“聪明”与“帅”并不对立，所以不能用“却”。"}, {"text": "他一边看书，却一边听音乐。", "explanation": "这里应该用〈同时〉。〈却〉表示前后相反，而这两件事同时进行，并不对立，不能用“却”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很累，却他坚持跑完了。", "corrected_sentence": "他很累，他却坚持跑完了。", "error_description": "错误：“却”放在了主语“他”之前。正确：“却”是副词，应放在主语之后、谓语之前，写作“他却坚持跑完了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很年轻，很却有经验。", "corrected_sentence": "他很年轻，却很有经验。", "error_description": "错误：“却”放在了“很”之后。正确：“却”应放在“很”之前，写作“却很有经验”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21594, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顺境", "is_correct": true, "explanation": "反义：“顺境”指顺利的境遇，与“困境”构成反义。"}, {"text": "厨房", "is_correct": false, "explanation": "无反义关系：“厨房”指做饭的房间，与“困境”的意思不相对。"}, {"text": "粉笔", "is_correct": false, "explanation": "无反义关系：“粉笔”指写字用的条状物，与“困境”没有对立关系。"}, {"text": "田野", "is_correct": false, "explanation": "无反义关系：“田野”指广阔的田地，与“困境”不构成反义。"}], "correct_answer": "顺境", "explanations": {"顺境": "反义：“顺境”指顺利的境遇，与“困境”构成反义。", "厨房": "无反义关系：“厨房”指做饭的房间，与“困境”的意思不相对。", "粉笔": "无反义关系：“粉笔”指写字用的条状物，与“困境”没有对立关系。", "田野": "无反义关系：“田野”指广阔的田地，与“困境”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21594, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顺境", "is_correct": true, "explanation": "反义：“顺境”指顺利的境遇，与“困境”构成反义。"}, {"text": "书架", "is_correct": false, "explanation": "无反义关系：“书架”指放书的家具，与“困境”没有对立关系。"}, {"text": "草地", "is_correct": false, "explanation": "无反义关系：“草地”指长满草的地面，与“困境”的意思不相对。"}, {"text": "公园", "is_correct": false, "explanation": "无反义关系：“公园”指供人游览休息的场所，与“困境”不构成反义。"}], "correct_answer": "顺境", "explanations": {"顺境": "反义：“顺境”指顺利的境遇，与“困境”构成反义。", "书架": "无反义关系：“书架”指放书的家具，与“困境”没有对立关系。", "草地": "无反义关系：“草地”指长满草的地面，与“困境”的意思不相对。", "公园": "无反义关系：“公园”指供人游览休息的场所，与“困境”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21594, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "艰难、难以摆脱的处境。", "primary_collocate": null, "pronunciation": "kùn jìng", "ipa": "kʰwən˥˩ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他丢了工作又生了病，陷入了困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人在国外，钱也花完了，陷入困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对这样的困境，她不知道该怎么办。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到困境时，可以找朋友商量。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨把路冲断了，我们陷入了困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的困境让老板几天睡不着觉。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想不出办法，只好向老师说明自己的困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们现在的困境，谁也解决不了。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要不放弃，总能走出困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他钱包丢了，手机也没电，一时陷入困境。", "target_word": "困境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生存困境", "label": "复合"}, {"form": "经济困境", "label": "复合"}], "register": "中性", "sense_fingerprint": "困境：艰难的处境；陷入/走出困境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e4321f-de6e-46a4-8743-02c784fb0964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21594, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "困境", "is_correct": true, "explanation": "正确：“陷入了困境”指陷入难以应付的处境，符合丢工作、生病的语境。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸是具体的物件，不能“陷入”，与丢工作、生病的处境不符。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“陷入”的宾语须是状况或境地，不能带“人数”这类表示数量的名词。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是一顿饭，不是可以“陷入”的状况，句意讲不通。"}], "explanations": {"困境": "正确：“陷入了困境”指陷入难以应付的处境，符合丢工作、生病的语境。", "报纸": "语义：报纸是具体的物件，不能“陷入”，与丢工作、生病的处境不符。", "人数": "搭配：“陷入”的宾语须是状况或境地，不能带“人数”这类表示数量的名词。", "早餐": "语义：早餐是一顿饭，不是可以“陷入”的状况，句意讲不通。"}, "sentence_index": 0, "correct_answer": "困境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她现在的困境很好，同事都很照顾她。", "explanation": "这里应该用〈处境〉。困境指艰难的处境，不能用来形容良好的情况。"}, {"text": "这位老师的教学达到了很高的困境。", "explanation": "这里应该用〈境界〉。困境指艰难的处境，不指教学所达到的水平。"}, {"text": "这次比赛的困境很好，他很满意。", "explanation": "这里应该用〈情况〉。困境指艰难的处境，不能用来形容比赛顺利的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21594, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "困境", "is_correct": true, "explanation": "正确：“向老师说明自己的困境”指说明自己所处的艰难情况，与“想不出办法”的语境相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是外部的自然状况，不是可以向老师“说明”的个人处境，句意讲不通。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是一顿饭，不是需要向老师说明的处境，句意讲不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指身体外形特征，与“想不出办法”的困难情境无关。"}], "explanations": {"困境": "正确：“向老师说明自己的困境”指说明自己所处的艰难情况，与“想不出办法”的语境相合。", "天气": "语义：天气是外部的自然状况，不是可以向老师“说明”的个人处境，句意讲不通。", "早饭": "语义：早饭是一顿饭，不是需要向老师说明的处境，句意讲不通。", "身高": "体貌：“身高”指身体外形特征，与“想不出办法”的困难情境无关。"}, "sentence_index": 6, "correct_answer": "困境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他现在的困境不错，钱也够用了。", "explanation": "这里应该用〈境况〉。困境指艰难的处境，不能用来形容不错、钱够用的状况。"}, {"text": "这道数学题的困境不大，很快就做完了。", "explanation": "这里应该用〈困难〉。困难可指事情难做的程度，困境指人所处的艰难处境，不能用来说题目的难度。"}, {"text": "他晚年的困境很舒服，每天都去公园散步。", "explanation": "这里应该用〈生活〉。困境指艰难的处境，不能用来形容舒服的晚年生活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她小时候也遇到困境过，所以很理解别人。", "corrected_sentence": "她小时候也遇到困境，所以很理解别人。", "error_description": "体标位置错误：“过”只能紧跟动词，不能紧跟宾语“困境”。删去“过”即可，也可改为“遇到过困境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次意外让他们的旅行陷入了很困境。", "corrected_sentence": "这次意外让他们的旅行陷入了困境。", "error_description": "错误在“很”：“困境”是名词，不能被“很”修饰。应说“陷入了困境”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
