INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21598, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "还没加工过的东西，比如地里刚摘的菜。", "primary_collocate": null, "pronunciation": "chū jí chǎn pǐn", "ipa": "ʈʂʰu˥ tɕi˧˥ ʈʂʰan˨˩˦ pʰin˨˩˦", "syllable_count": 4, "sentences": [{"text": "刚从地里摘的菜是初级产品。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些苹果刚摘下来，还是初级产品。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛奶加工以前，只是初级产品。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民把初级产品拉到工厂去加工。", "target_word": "初级产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没洗没切的菜都是初级产品。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把初级产品做成了罐头。", "target_word": "初级产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚收来的棉花还没加工，是初级产品。", "target_word": "初级产品", "complexity_tier": "T3", "furigana": "gāng shōu lái de mián huā hái méi jiā gōng, shì chū jí chǎn pǐn.", "sentence_source": "generated"}, {"text": "初级产品便宜，加工以后就贵了。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店卖的是初级产品，比如新鲜的菜和肉。", "target_word": "初级产品", "complexity_tier": "T3", "furigana": "zhè jiā diàn mài de shì chū jí chǎn pǐn, bǐ rú xīn xiān de cài hé ròu.", "sentence_source": "generated"}, {"text": "麦子磨成面粉以前，是初级产品。", "target_word": "初级产品", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "初級產品", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常说法：还没加工的东西，如刚摘的菜、刚收的棉花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7cbd58c-699e-471e-90b4-643ce1bb9923') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21598, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初级产品", "is_correct": true, "explanation": "正确。刚从地里摘的菜还没加工，属于“初级产品”，放在“是___”处，句意通顺。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指钱数，菜不能是价格，句意不通。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产场所，菜不能是工厂，句意不通。"}, {"text": "夜晚", "is_correct": false, "explanation": "搭配：“夜晚”是时间词，不能用来说明菜的性质，这里不搭配。"}], "explanations": {"初级产品": "正确。刚从地里摘的菜还没加工，属于“初级产品”，放在“是___”处，句意通顺。", "价格": "语义：价格指钱数，菜不能是价格，句意不通。", "工厂": "语义：工厂是生产场所，菜不能是工厂，句意不通。", "夜晚": "搭配：“夜晚”是时间词，不能用来说明菜的性质，这里不搭配。"}, "sentence_index": 0, "correct_answer": "初级产品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌是初级产品，大家都喜欢听。", "explanation": "这里应该用〈作品〉。“初级产品”指还没加工过的东西，不能用来指歌曲这类作品。"}, {"text": "这盒饼干已经烤好包装，是初级产品。", "explanation": "这里应该用〈成品〉。饼干已经烤好、包装完成，是加工过的东西，不再是“初级产品”。"}, {"text": "这桌菜都是初级产品，已经做好了。", "explanation": "这里应该用〈熟菜〉。“初级产品”指还没加工过的东西，做好的菜已经不是初级产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初级产品", "is_correct": true, "explanation": "正确。刚收来的棉花还没加工，属于“初级产品”，放在“是___”处，句意通顺。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是特定的日子，棉花不能是节日，句意不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是教学用书，棉花不能是课本，句意不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”用于人的性情，不能用来说明棉花，这里不搭配。"}], "explanations": {"初级产品": "正确。刚收来的棉花还没加工，属于“初级产品”，放在“是___”处，句意通顺。", "节日": "语义：节日是特定的日子，棉花不能是节日，句意不通。", "课本": "语义：课本是教学用书，棉花不能是课本，句意不通。", "脾气": "搭配：“脾气”用于人的性情，不能用来说明棉花，这里不搭配。"}, "sentence_index": 6, "correct_answer": "初级产品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱鸡蛋已经做成了蛋糕，是初级产品。", "explanation": "这里应该用〈成品〉。蛋糕是做好的东西，不是还没加工过的东西，不能称为“初级产品”。"}, {"text": "棉花做成衣服以后，是初级产品。", "explanation": "这里应该用〈成品〉。衣服已经加工完成，“初级产品”指加工前的东西。"}, {"text": "这批菜已经洗好切好、装进了盒子，是初级产品。", "explanation": "这里应该用〈净菜〉。“初级产品”指还没加工过的东西，洗切装盒的菜已经加工过了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这筐草莓是刚摘下来初级产品。", "corrected_sentence": "这筐草莓是刚摘下来的初级产品。", "error_description": "漏掉“的”：“刚摘下来”修饰“初级产品”时要加“的”，应为“刚摘下来的初级产品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些芒果是刚摘下的初级产品的。", "corrected_sentence": "这些芒果是刚摘下的初级产品。", "error_description": "多加了一个“的”：“是……的初级产品”结构已完整，句末不需要再加“的”，应为“这些芒果是刚摘下的初级产品。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
