INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21600, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西做成最初步的样子。", "primary_collocate": null, "pronunciation": "chū jiā gōng", "ipa": "ʈʂʰu˥ tɕja˥ kʊŋ˥", "syllable_count": 3, "sentences": [{"text": "茶叶摘下来以后，要先进行初加工。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂只做水果的初加工。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把牛奶初加工后，卖给大工厂。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初加工以后，鱼可以放很久。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里新建了一个初加工的小厂。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些木头已经初加工过了。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肉类初加工要注意卫生。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡豆先经过初加工，再运到国外。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在初加工车间工作了五年。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不做成品，只做初加工。", "target_word": "初加工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "初加工产品", "label": "复合"}], "register": "中性", "sense_fingerprint": "对原料做最初步的处理，还不是成品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578294a7-0823-4619-bc2b-d5210b7acc13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21600, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "初加工", "is_correct": true, "explanation": "正确。茶叶摘下来以后要先进行初加工，符合把原料做最初步处理的意思。"}, {"text": "深加工", "is_correct": false, "explanation": "语义：深加工是后续的深入处理，与“先”以及“摘下来以后”的先后顺序矛盾。"}, {"text": "精加工", "is_correct": false, "explanation": "语义：精加工也是后续工序，不能放在“先”的位置。"}, {"text": "采摘", "is_correct": false, "explanation": "搭配：茶叶已经“摘下来”，再说“进行采摘”搭配不当。"}], "explanations": {"初加工": "正确。茶叶摘下来以后要先进行初加工，符合把原料做最初步处理的意思。", "深加工": "语义：深加工是后续的深入处理，与“先”以及“摘下来以后”的先后顺序矛盾。", "精加工": "语义：精加工也是后续工序，不能放在“先”的位置。", "采摘": "搭配：茶叶已经“摘下来”，再说“进行采摘”搭配不当。"}, "sentence_index": 0, "correct_answer": "初加工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用慢火把排骨初加工，直到骨头酥烂。", "explanation": "这里应该用〈炖〉。初加工只是最初步的处理，把排骨用慢火炖到骨头酥烂属于烹饪，应该用〈炖〉。"}, {"text": "稻子还长在田里，农民就开始初加工了。", "explanation": "这里应该用〈收割〉。初加工是对已经收下来的原料做最初步的处理，稻子还在田里时要做的是〈收割〉。"}, {"text": "果农每天初加工草莓，一颗一颗地摘。", "explanation": "这里应该用〈采摘〉。初加工是对已经采下来的原料做最初步的处理，一颗颗地摘草莓是采摘，应该用〈采摘〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初加工", "is_correct": true, "explanation": "正确。肉类初加工是对肉类做最初步的处理，所以要注意卫生。"}, {"text": "种植", "is_correct": false, "explanation": "语义：肉类不能种植，“种植”与句中的肉类对象不相符。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”用于农作物，不与“肉类”搭配。"}, {"text": "设计", "is_correct": false, "explanation": "语义：肉类不能设计，“设计”与“肉类”的对象不符。"}], "explanations": {"初加工": "正确。肉类初加工是对肉类做最初步的处理，所以要注意卫生。", "种植": "语义：肉类不能种植，“种植”与句中的肉类对象不相符。", "收割": "搭配：“收割”用于农作物，不与“肉类”搭配。", "设计": "语义：肉类不能设计，“设计”与“肉类”的对象不符。"}, "sentence_index": 6, "correct_answer": "初加工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "师傅亲手初加工了这件木雕。", "explanation": "这里应该用〈制作〉。木雕是做好的工艺品，“初加工”只是最初步的处理，应该用〈制作〉。"}, {"text": "妈妈每天初加工碗筷。", "explanation": "这里应该用〈清洗〉。碗筷不是原料，初加工针对原料，清洗餐具应该用〈清洗〉。"}, {"text": "工人在初加工房子。", "explanation": "这里应该用〈装修〉。房子不是原料，初加工针对原料，装修房屋应该用〈装修〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些大豆已经好初加工了，可以拿去榨油。", "corrected_sentence": "这些大豆已经初加工了，可以拿去榨油。", "error_description": "错误形式“好初加工”，多出了结果补语“好”。“好”只能放在动词之后，不能放在动词前；这句只需“已经初加工了”，不需要补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批肉已经初加工着了。", "corrected_sentence": "这批肉已经初加工了。", "error_description": "体标错误：“已经……了”表示动作已完成，不能再用表示持续的“着”，“初加工着了”不对，正确形式是“已经初加工了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21602, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "窗户", "is_correct": false, "explanation": "无关：窗户与“收入”的任何义项都没有反义关系。"}, {"text": "支出", "is_correct": true, "explanation": "反义：“收入”指进账的钱，“支出”指花出去的钱，二者相对。"}, {"text": "河流", "is_correct": false, "explanation": "无关：河流是地理事物，与钱的收入没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "无关：天气不是钱的进出，与“收入”没有反义关系。"}], "correct_answer": "支出", "explanations": {"窗户": "无关：窗户与“收入”的任何义项都没有反义关系。", "支出": "反义：“收入”指进账的钱，“支出”指花出去的钱，二者相对。", "河流": "无关：河流是地理事物，与钱的收入没有反义关系。", "天气": "无关：天气不是钱的进出，与“收入”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21602, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "书架", "is_correct": false, "explanation": "无关：书架是家具，与“收入”没有反义关系。"}, {"text": "支出", "is_correct": true, "explanation": "反义：“收入”指进账的钱，“支出”指花出去的钱，二者相对。"}, {"text": "雨伞", "is_correct": false, "explanation": "无关：雨伞是日用品，与钱的收入没有关系。"}, {"text": "海洋", "is_correct": false, "explanation": "无关：海洋是地理事物，与“收入”没有反义关系。"}], "correct_answer": "支出", "explanations": {"书架": "无关：书架是家具，与“收入”没有反义关系。", "支出": "反义：“收入”指进账的钱，“支出”指花出去的钱，二者相对。", "雨伞": "无关：雨伞是日用品，与钱的收入没有关系。", "海洋": "无关：海洋是地理事物，与“收入”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21602, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工作或做生意时得到的钱。", "primary_collocate": null, "pronunciation": "shōu rù", "ipa": "ʂou˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "他的收入很高，住大房子。", "target_word": "收入", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸做生意，每个月收入不一样。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我刚工作，收入不多，不能买贵东西。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王每天送快递，收入比以前多了。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小店的收入够一家人生活。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈有两份工作，收入多一些。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有工作，所以没有收入。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天卖冰激凌，小店的收入特别好。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把一个月的收入都寄给了家里。", "target_word": "收入", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的收入少，就要少花钱。", "target_word": "收入", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "高收入", "label": "复合"}, {"form": "低收入", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常说法：工作或做生意时得到的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7cbd58c-699e-471e-90b4-643ce1bb9923') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "搭配：“体重”说重或轻，不说“很高”。"}, {"text": "收入", "is_correct": true, "explanation": "正确：“收入”指工作或做生意得到的钱，与“很高”“住大房子”相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人的所得或状况，“他的天气很高”不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是人的所得，“他的颜色很高”不通，也与“住大房子”无关。"}], "explanations": {"体重": "搭配：“体重”说重或轻，不说“很高”。", "收入": "正确：“收入”指工作或做生意得到的钱，与“很高”“住大房子”相合。", "天气": "语义：天气不是人的所得或状况，“他的天气很高”不通。", "颜色": "语义：颜色不是人的所得，“他的颜色很高”不通，也与“住大房子”无关。"}, "sentence_index": 0, "correct_answer": "收入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年的庄稼收入很好。", "explanation": "这里应该用〈收成〉。收入指工作或经营得到的钱，庄稼的产出要说收成。"}, {"text": "他们收入了一个女儿。", "explanation": "这里应该用〈收养〉。收入指工作或经营得到的钱，领养孩子要说收养。"}, {"text": "这家公司收入了一家小工厂。", "explanation": "这里应该用〈收购〉。收入指工作或经营得到的钱，买下别的企业要说收购。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "搭配：“身高”是人天生的特征，不说“没有”。"}, {"text": "房价", "is_correct": false, "explanation": "语义：房价指房子的价钱，“没有工作，所以没有房价”不通。"}, {"text": "收入", "is_correct": true, "explanation": "正确：“收入”指工作得到的钱，与“没有工作”相合。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔指地势的高度，用于地点，不用于人的经济状况。"}], "explanations": {"身高": "搭配：“身高”是人天生的特征，不说“没有”。", "房价": "语义：房价指房子的价钱，“没有工作，所以没有房价”不通。", "收入": "正确：“收入”指工作得到的钱，与“没有工作”相合。", "海拔": "语义：海拔指地势的高度，用于地点，不用于人的经济状况。"}, "sentence_index": 6, "correct_answer": "收入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "读了这本书，我的收入很大。", "explanation": "这里应该用〈收获〉。收入指工作或经营得到的钱，读书、学习的所得要说收获。"}, {"text": "这家孤儿院收入了三十个孩子。", "explanation": "这里应该用〈收留〉。收入指工作或经营得到的钱，接纳并照顾流浪的人或孩子要说收留。"}, {"text": "这位老人收入了很多古画。", "explanation": "这里应该用〈收藏〉。收入指工作或经营得到的钱，珍藏古玩字画要说收藏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年有一场不小的收入。", "corrected_sentence": "他去年有一笔不小的收入。", "error_description": "量词错误：收入应用量词“笔”，不说“场”。正确说法是“一笔不小的收入”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每个月都有一次固定的收入。", "corrected_sentence": "他每个月都有一笔固定的收入。", "error_description": "量词错误：“次”用于动作的次数，收入应用量词“笔”计量。正确说法是“一笔固定的收入”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21604, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏高", "is_correct": true, "explanation": "正确：“偏高”与“偏低”构成反义，指高度比一般的高。"}, {"text": "结实", "is_correct": false, "explanation": "与“偏低”没有反义关系，“结实”指坚固耐用。"}, {"text": "大方", "is_correct": false, "explanation": "与“偏低”没有反义关系，“大方”指不拘小节或举止自然。"}, {"text": "整齐", "is_correct": false, "explanation": "与“偏低”没有反义关系，“整齐”指有秩序、不杂乱。"}], "correct_answer": "偏高", "explanations": {"偏高": "正确：“偏高”与“偏低”构成反义，指高度比一般的高。", "结实": "与“偏低”没有反义关系，“结实”指坚固耐用。", "大方": "与“偏低”没有反义关系，“大方”指不拘小节或举止自然。", "整齐": "与“偏低”没有反义关系，“整齐”指有秩序、不杂乱。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21604, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "偏高", "is_correct": true, "explanation": "正确：“偏高”与“偏低”构成反义，指高度比一般的高。"}, {"text": "活泼", "is_correct": false, "explanation": "与“偏低”没有反义关系，“活泼”指性格开朗、爱动。"}, {"text": "安静", "is_correct": false, "explanation": "与“偏低”没有反义关系，“安静”指没有声音或很少动静。"}, {"text": "严肃", "is_correct": false, "explanation": "与“偏低”没有反义关系，“严肃”指态度庄重、不随便。"}], "correct_answer": "偏高", "explanations": {"偏高": "正确：“偏高”与“偏低”构成反义，指高度比一般的高。", "活泼": "与“偏低”没有反义关系，“活泼”指性格开朗、爱动。", "安静": "与“偏低”没有反义关系，“安静”指没有声音或很少动静。", "严肃": "与“偏低”没有反义关系，“严肃”指态度庄重、不随便。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21604, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "高度比一般的矮。", "primary_collocate": null, "pronunciation": "piān dī", "ipa": "pʰjɛn˥ ti˥", "syllable_count": 2, "sentences": [{"text": "这把小凳子偏低，适合小朋友坐。", "target_word": "偏低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子偏低，我写字不舒服。", "target_word": "偏低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这扇门偏低，高个子要弯腰。", "target_word": "偏低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个窗台偏低，小孩容易爬上去。", "target_word": "偏低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子偏低，坐着腿不舒服。", "target_word": "偏低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的台面偏低，做饭要弯着腰。", "target_word": "偏低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的身高偏低，所以想穿高跟鞋。", "target_word": "偏低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个篮球架偏低，比赛时不能用。", "target_word": "偏低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆自行车的座椅偏低，适合小孩骑。", "target_word": "偏低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的栏杆偏低，孩子走在上面不安全。", "target_word": "偏低", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "个子或物体的高度比一般的矮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7cbd58c-699e-471e-90b4-643ce1bb9923') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21604, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偏低", "is_correct": true, "explanation": "正确：“偏低”指高度比一般的矮，适合小朋友坐。"}, {"text": "偏大", "is_correct": false, "explanation": "语义：句中已说“小凳子”，“偏大”与之矛盾，也不适合小朋友坐。"}, {"text": "偏胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体形，不能用来形容凳子。"}, {"text": "偏远", "is_correct": false, "explanation": "语义：“偏远”指地方离城市远，不能形容凳子的高矮。"}], "explanations": {"偏低": "正确：“偏低”指高度比一般的矮，适合小朋友坐。", "偏大": "语义：句中已说“小凳子”，“偏大”与之矛盾，也不适合小朋友坐。", "偏胖": "体貌：“胖”形容人或动物的体形，不能用来形容凳子。", "偏远": "语义：“偏远”指地方离城市远，不能形容凳子的高矮。"}, "sentence_index": 0, "correct_answer": "偏低"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块木板的厚度偏低，承受不了重东西。", "explanation": "这里应该用〈偏薄〉。厚薄要说“厚”或“薄”，“偏低”指高度，不用于厚度。"}, {"text": "这扇门的宽度偏低，我的行李箱进不去。", "explanation": "这里应该用〈偏窄〉。“偏低”指高度，宽度只说宽或窄。"}, {"text": "这根绳子的长度偏低，绑不住箱子。", "explanation": "这里应该用〈偏短〉。长短要说“长”或“短”，“偏低”指高度，不用于长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏低", "is_correct": true, "explanation": "正确：身高比一般的矮，所以她想穿高跟鞋。"}, {"text": "偏高", "is_correct": false, "explanation": "语义：身高高就不需要靠高跟鞋增高，与“所以想穿高跟鞋”的因果相矛盾。"}, {"text": "偏宽", "is_correct": false, "explanation": "搭配：“宽”说的是宽度，不能用来形容身高。"}, {"text": "偏重", "is_correct": false, "explanation": "搭配：“重”说的是重量，身高不能用重量来形容。"}], "explanations": {"偏低": "正确：身高比一般的矮，所以她想穿高跟鞋。", "偏高": "语义：身高高就不需要靠高跟鞋增高，与“所以想穿高跟鞋”的因果相矛盾。", "偏宽": "搭配：“宽”说的是宽度，不能用来形容身高。", "偏重": "搭配：“重”说的是重量，身高不能用重量来形容。"}, "sentence_index": 6, "correct_answer": "偏低"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子的体积偏低，能装下两件大衣。", "explanation": "这里应该用〈偏大〉。体积只说大或小，“偏低”不能用于体积。"}, {"text": "这间屋子的面积偏低，放不下两张床。", "explanation": "这里应该用〈偏小〉。面积只说大或小，“偏低”指高度，不用于面积。"}, {"text": "这碗汤的味道偏低，要再加点盐。", "explanation": "这里应该用〈偏淡〉。味道只说咸或淡，“偏低”指高度，不能形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张沙发偏低着，老人坐起来很吃力。", "corrected_sentence": "这张沙发偏低，老人坐起来很吃力。", "error_description": "错误：“偏低着”。正确：“偏低”。形容词不能加“着”表示状态，应直接说“偏低”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个洗手台被偏低，孩子用起来很方便。", "corrected_sentence": "这个洗手台偏低，孩子用起来很方便。", "error_description": "错误：“被偏低”。正确：“偏低”。“偏低”是形容词，不能直接放在“被”后构成被动句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f67b950b-d084-43f4-ab6a-fee2900780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
