INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21608, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个地方或国家里大家一起赚钱、花钱的整体。", "primary_collocate": null, "pronunciation": "jīng jì tǐ", "ipa": "tɕiŋ˥ tɕi˥˩ tʰi˨˩˦", "syllable_count": 3, "sentences": [{"text": "日本是一个很大的经济体。", "target_word": "经济体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个经济体里的人都很努力工作。", "target_word": "经济体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小国家也可以是很强的经济体。", "target_word": "经济体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个经济体里，大家买东西很方便。", "target_word": "经济体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的经济体让人们有工作，也有钱花。", "target_word": "经济体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个经济体今年发展得很快。", "target_word": "经济体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想了解世界上最大的经济体。", "target_word": "经济体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济体变好了，大家的生活也变好了。", "target_word": "经济体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有些经济体很小，但是很有钱。", "target_word": "经济体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们介绍了亚洲的经济体。", "target_word": "经济体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "新兴经济体", "label": "复合"}, {"form": "发达经济体", "label": "复合"}], "register": "中性", "sense_fingerprint": "经济体：一个地方或国家里大家一起赚钱、花钱的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd34bc2cc-089b-431f-93cf-0515a2573957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21608, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人", "is_correct": false, "explanation": "搭配：“很大的”修饰国家或地区时不能用于“人”，“日本是一个很大的人”搭配不当。"}, {"text": "房子", "is_correct": false, "explanation": "语义：日本是国家，不是房子，句子描述的是国家的规模，与“房子”不符。"}, {"text": "经济体", "is_correct": true, "explanation": "正确。“一个很大的经济体”指一个地方或国家大家一起赚钱、花钱的整体，句意合适。"}, {"text": "学校", "is_correct": false, "explanation": "语义：日本是国家，“学校”指教育机构，与描述国家规模的句意不合。"}], "explanations": {"人": "搭配：“很大的”修饰国家或地区时不能用于“人”，“日本是一个很大的人”搭配不当。", "房子": "语义：日本是国家，不是房子，句子描述的是国家的规模，与“房子”不符。", "经济体": "正确。“一个很大的经济体”指一个地方或国家大家一起赚钱、花钱的整体，句意合适。", "学校": "语义：日本是国家，“学校”指教育机构，与描述国家规模的句意不合。"}, "sentence_index": 0, "correct_answer": "经济体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个经济体每年培养很多律师。", "explanation": "这里应该用〈学校〉。经济体指一个地方大家赚钱、花钱的整体，不是教育机构，不能培养人才。"}, {"text": "他学的是经济体。", "explanation": "这里应该用〈经济学〉。经济体指一个地方大家赚钱、花钱的整体，不是学科；所学的学科应说「经济学」。"}, {"text": "这个经济体是木头做的。", "explanation": "这里应该用〈桌子〉。经济体是抽象的整体，不是实物，不能说它用什么材料做成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21608, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：“世界上最大的”用于地方、国家或事物的规模比较，“学生”不能这样比较，句意不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：句中要了解的是经济方面的对象，“歌曲”与“了解”的内容无关。"}, {"text": "经济体", "is_correct": true, "explanation": "正确。“世界上最大的经济体”指全世界经济规模最大的国家或地区，与“了解”的对象相符。"}, {"text": "妈妈", "is_correct": false, "explanation": "搭配：“世界上最大的”修饰“妈妈”不是常用搭配，句意不通。"}], "explanations": {"学生": "语义：“世界上最大的”用于地方、国家或事物的规模比较，“学生”不能这样比较，句意不通。", "歌曲": "语义：句中要了解的是经济方面的对象，“歌曲”与“了解”的内容无关。", "经济体": "正确。“世界上最大的经济体”指全世界经济规模最大的国家或地区，与“了解”的对象相符。", "妈妈": "搭配：“世界上最大的”修饰“妈妈”不是常用搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "经济体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个经济体昨天感冒了，没来上课。", "explanation": "这里应该用〈学生〉。经济体是一个地方大家赚钱、花钱的整体，不会感冒，也不会上课。"}, {"text": "这个经济体每天要唱两首歌。", "explanation": "这里应该用〈歌手〉。经济体是整体系统，不会唱歌，唱歌的是人。"}, {"text": "这个经济体的头发很长。", "explanation": "这里应该用〈人〉。经济体是抽象的整体系统，没有头发，不能说它的头发长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条经济体的人都有工作，生活很好。", "corrected_sentence": "这个经济体的人都有工作，生活很好。", "error_description": "量词错误：经济体应配量词「个」，「这条」应改为「这个」，正确说法为「这个经济体的人都有工作，生活很好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "许多亚洲条经济体都在快速发展。", "corrected_sentence": "许多亚洲经济体都在快速发展。", "error_description": "错误：「亚洲」与「经济体」之间多出量词「条」。「条」用于长条形事物，不能修饰「经济体」；此处直接说「许多亚洲经济体」即可，不需要量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c70347ad-27a5-41a9-9ada-627dc309d573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21610, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "矮", "is_correct": true, "explanation": "矮：与“高”构成反义，指从下到上的距离小，适用于“这座楼”。"}, {"text": "快", "is_correct": false, "explanation": "快与“高”不构成反义，快的反义是慢。"}, {"text": "窄", "is_correct": false, "explanation": "窄与“高”不构成反义，窄的反义是宽。"}, {"text": "远", "is_correct": false, "explanation": "远与“高”不构成反义，远的反义是近。"}], "correct_answer": "矮", "explanations": {"矮": "矮：与“高”构成反义，指从下到上的距离小，适用于“这座楼”。", "快": "快与“高”不构成反义，快的反义是慢。", "窄": "窄与“高”不构成反义，窄的反义是宽。", "远": "远与“高”不构成反义，远的反义是近。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21610, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "矮", "is_correct": true, "explanation": "矮：与“高”构成反义，指墙的高度小。"}, {"text": "粗", "is_correct": false, "explanation": "粗与“高”不构成反义，粗的反义是细。"}, {"text": "厚", "is_correct": false, "explanation": "厚与“高”不构成反义，厚的反义是薄。"}, {"text": "圆", "is_correct": false, "explanation": "圆与“高”不构成反义，圆的反义是方。"}], "correct_answer": "矮", "explanations": {"矮": "矮：与“高”构成反义，指墙的高度小。", "粗": "粗与“高”不构成反义，粗的反义是细。", "厚": "厚与“高”不构成反义，厚的反义是薄。", "圆": "圆与“高”不构成反义，圆的反义是方。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21610, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "高表示从下到上的距离大。", "primary_collocate": null, "pronunciation": "gāo", "ipa": "kau˥", "syllable_count": 1, "sentences": [{"text": "这座山很高，我们爬了三个小时。", "target_word": "高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个子很高，很适合打篮球。", "target_word": "高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那棵树太高了，我够不到树上的苹果。", "target_word": "高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座楼很高，从窗户往下看有点怕。", "target_word": "高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有多高？我一米七五。", "target_word": "高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞得很高，下面的云像白棉花。", "target_word": "高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盏灯挂得太高，我够不到开关。", "target_word": "高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥有五十米高，下面是河。", "target_word": "高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踮着脚，把手举得很高。", "target_word": "高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙太高了，小狗跳不过去。", "target_word": "高", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高高的", "label": "重叠"}], "register": "中性", "sense_fingerprint": "从下到上的距离大，指人或物体的高度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: contains vocabulary far above tier T1: 踮 (Zipf 2.12)']::text[], '911ce2b6-7d1d-4794-8ddb-56c9662d33c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21610, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高", "is_correct": true, "explanation": "高（gāo）：从下到上的距离大，如“这座山很高”。"}, {"text": "告", "is_correct": false, "explanation": "gào（第四声）与 gāo（第一声）声调不同，意思是告诉。"}, {"text": "搞", "is_correct": false, "explanation": "gǎo（第三声）与 gāo 声调不同，意思是做、弄。"}, {"text": "该", "is_correct": false, "explanation": "gāi 与 gāo 韵母不同（ai 与 ao），声调相同，意思是应该。"}, {"text": "刚", "is_correct": false, "explanation": "gāng 与 gāo 韵母不同（ang 与 ao），声调相同，意思是刚才。"}, {"text": "稿", "is_correct": false, "explanation": "gǎo（第三声）与 gāo 声调不同，意思是文稿。"}, {"text": "干", "is_correct": false, "explanation": "gān 与 gāo 韵母不同（an 与 ao），声调相同，意思是干燥。"}], "explanations": {"高": "高（gāo）：从下到上的距离大，如“这座山很高”。", "告": "gào（第四声）与 gāo（第一声）声调不同，意思是告诉。", "搞": "gǎo（第三声）与 gāo 声调不同，意思是做、弄。", "该": "gāi 与 gāo 韵母不同（ai 与 ao），声调相同，意思是应该。", "刚": "gāng 与 gāo 韵母不同（ang 与 ao），声调相同，意思是刚才。", "稿": "gǎo（第三声）与 gāo 声调不同，意思是文稿。", "干": "gān 与 gāo 韵母不同（an 与 ao），声调相同，意思是干燥。"}, "sentence_index": null, "correct_answer": "高"}, "level_3": {"options": [{"text": "高", "is_correct": true, "explanation": "高：“这座山很高，我们爬了三个小时”说明从下到上的距离大，符合句意。"}, {"text": "轻", "is_correct": false, "explanation": "语义：“轻”说分量，山的高度不能用“轻”来形容。"}, {"text": "胖", "is_correct": false, "explanation": "语义：“胖”形容身体，不能用来形容山。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”形容质地，不能用来形容山的高度。"}], "explanations": {"高": "高：“这座山很高，我们爬了三个小时”说明从下到上的距离大，符合句意。", "轻": "语义：“轻”说分量，山的高度不能用“轻”来形容。", "胖": "语义：“胖”形容身体，不能用来形容山。", "软": "搭配：“软”形容质地，不能用来形容山的高度。"}, "sentence_index": 0, "correct_answer": "高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个洞很高，别往下跳。", "explanation": "这里应该用〈深〉。高指从下到上的距离，洞的深度是从上到下，要用深。"}, {"text": "这里离车站很高，走路要一个小时。", "explanation": "这里应该用〈远〉。高说从下到上的距离，离车站的距离是水平距离，要用远。"}, {"text": "这条皮带很高，正好系在腰上。", "explanation": "这里应该用〈长〉。高指从下到上的距离，皮带的长短要用长，不说皮带很高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21610, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "高", "is_correct": true, "explanation": "高（gāo）：从下到上的距离大，如“墙太高了”。"}, {"text": "镐", "is_correct": false, "explanation": "gǎo（第三声）与 gāo 声调不同，声母与韵母相同，意思是镐头（一种农具）。"}, {"text": "糟", "is_correct": false, "explanation": "zāo（第一声）与 gāo 声母不同（z 与 g），韵母与声调相同，意思是糟糕、腐坏。"}, {"text": "沟", "is_correct": false, "explanation": "gōu（第一声）与 gāo 韵母不同（ou 与 ao），声母与声调相同，意思是水沟。"}, {"text": "操", "is_correct": false, "explanation": "cāo（第一声）与 gāo 声母不同（c 与 g），韵母与声调相同，意思是操练、操作。"}, {"text": "包", "is_correct": false, "explanation": "bāo（第一声）与 gāo 声母不同（b 与 g），韵母与声调相同，意思是包裹、包子。"}, {"text": "猫", "is_correct": false, "explanation": "māo（第一声）与 gāo 声母不同（m 与 g），韵母与声调相同，意思是猫。"}], "explanations": {"高": "高（gāo）：从下到上的距离大，如“墙太高了”。", "镐": "gǎo（第三声）与 gāo 声调不同，声母与韵母相同，意思是镐头（一种农具）。", "糟": "zāo（第一声）与 gāo 声母不同（z 与 g），韵母与声调相同，意思是糟糕、腐坏。", "沟": "gōu（第一声）与 gāo 韵母不同（ou 与 ao），声母与声调相同，意思是水沟。", "操": "cāo（第一声）与 gāo 声母不同（c 与 g），韵母与声调相同，意思是操练、操作。", "包": "bāo（第一声）与 gāo 声母不同（b 与 g），韵母与声调相同，意思是包裹、包子。", "猫": "māo（第一声）与 gāo 声母不同（m 与 g），韵母与声调相同，意思是猫。"}, "sentence_index": null, "correct_answer": "高"}, "level_3": {"options": [{"text": "高", "is_correct": true, "explanation": "高：“这盏灯挂得太高，我够不到开关”说明位置高，符合句意。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”说速度，灯挂得快与够不到开关无关。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说速度，灯挂得慢与够不到开关无关。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”不能用来形容灯的挂放位置。"}], "explanations": {"高": "高：“这盏灯挂得太高，我够不到开关”说明位置高，符合句意。", "快": "语义：“快”说速度，灯挂得快与够不到开关无关。", "慢": "语义：“慢”说速度，灯挂得慢与够不到开关无关。", "硬": "搭配：“硬”不能用来形容灯的挂放位置。"}, "sentence_index": 6, "correct_answer": "高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这口井很高，打水要用很长的绳子。", "explanation": "这里应该用〈深〉。高指从下到上的距离，井的深浅要用深，不说井很高。"}, {"text": "这个操场很高，跑步很方便。", "explanation": "这里应该用〈宽〉。高说从下到上的距离，操场的宽窄要用宽，不说操场很高。"}, {"text": "他的腿很高，跑起来很快。", "explanation": "这里应该用〈长〉。高指从下到上的距离，腿的长短要说长，不说腿很高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风筝飞很高，孩子很开心。", "corrected_sentence": "风筝飞得很高，孩子很开心。", "error_description": "助词错误：动词“飞”后带表示结果的补语“很高”时，中间要用“得”，应说“飞得很高”，不能说“飞很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这堵很高得墙挡住了风。", "corrected_sentence": "这堵很高的墙挡住了风。", "error_description": "助词错误：“高”修饰名词“墙”时要用“的”，不能用“得”。应说“很高的墙”，不说“很高得墙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
