INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21612, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某个牌子比别的牌子更受欢迎、更厉害的特点。", "primary_collocate": null, "pronunciation": "pǐn pái yōu shì", "ipa": "pʰin˨˩˦ pʰaɪ˧˥ joʊ˥ ʂɻ̩˥˩", "syllable_count": 4, "sentences": [{"text": "大品牌有品牌优势，人们更相信它。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子很有名，这就是它的品牌优势。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的品牌优势是很多人都知道这个牌子。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店没有品牌优势，要多做宣传。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饮料公司的品牌优势很大。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋卖得快，靠的是品牌优势。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得老牌子有品牌优势。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "品牌优势让这家店的生意一直很好。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新公司想慢慢建立品牌优势。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了品牌优势，卖东西就容易多了。", "target_word": "品牌优势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "竞争优势", "label": "复合"}, {"form": "价格优势", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：牌子比别的牌子更受欢迎、更厉害的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1de80df8-30f4-4a4d-832e-d5d2f03764c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21612, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "品牌优势", "is_correct": true, "explanation": "正确：「大品牌有品牌优势，人们更相信它」指品牌的长处。"}, {"text": "缺点", "is_correct": false, "explanation": "语义：「缺点」与后文「人们更相信它」语义相反。"}, {"text": "电话", "is_correct": false, "explanation": "语义：「电话」与品牌的长处无关，「大品牌有电话」不构成人们相信它的理由。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：大品牌不说「有工资」，「有」后应接长处，不接薪酬。"}], "explanations": {"品牌优势": "正确：「大品牌有品牌优势，人们更相信它」指品牌的长处。", "缺点": "语义：「缺点」与后文「人们更相信它」语义相反。", "电话": "语义：「电话」与品牌的长处无关，「大品牌有电话」不构成人们相信它的理由。", "工资": "搭配：大品牌不说「有工资」，「有」后应接长处，不接薪酬。"}, "sentence_index": 0, "correct_answer": "品牌优势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的朋友把品牌优势装进了箱子里。", "explanation": "〈品牌优势〉指品牌相对其他品牌的长处，是抽象概念，不能装进箱子。"}, {"text": "小店有一只品牌优势。", "explanation": "〈品牌优势〉是抽象名词，量词用〈种〉，不说〈只〉。"}, {"text": "小店把品牌优势磨成了粉。", "explanation": "〈品牌优势〉是抽象的长处，不能像物质一样磨成粉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "品牌优势", "is_correct": true, "explanation": "正确：「老牌子有品牌优势」指老品牌的长处。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：牌子不说「体重」，这个词只能用于人或动物。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」与品牌的竞争长处无关，不能与「有」搭配作长处。"}, {"text": "雨量", "is_correct": false, "explanation": "语义：「雨量」指降雨的多少，与品牌无关。"}], "explanations": {"品牌优势": "正确：「老牌子有品牌优势」指老品牌的长处。", "体重": "体貌：牌子不说「体重」，这个词只能用于人或动物。", "颜色": "语义：「颜色」与品牌的竞争长处无关，不能与「有」搭配作长处。", "雨量": "语义：「雨量」指降雨的多少，与品牌无关。"}, "sentence_index": 6, "correct_answer": "品牌优势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把品牌优势挂在墙上，卖东西就容易了。", "explanation": "〈品牌优势〉是抽象的长处，不能挂在墙上，也不能作为具体物品陈列。"}, {"text": "这座品牌优势很大，卖东西很容易。", "explanation": "〈座〉用于山、桥等大型物体，不用于抽象的〈品牌优势〉。"}, {"text": "他把品牌优势借给了朋友。", "explanation": "〈品牌优势〉是品牌的长处，不能借出或转让。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新产品很难把建立品牌优势。", "corrected_sentence": "新产品很难建立品牌优势。", "error_description": "「把」字句的结构错误：「把」后须接宾语再接动词，这里只有动词没有宾语，应删去「把」，说「新产品很难建立品牌优势」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只品牌优势很有用。", "corrected_sentence": "那种品牌优势很有用。", "error_description": "「品牌优势」是抽象名词，量词用「种」，不说「只」。错误：那只；正确：那种。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
