INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21614, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人们买卖东西的地方，比如买菜、买玩具的地方。", "primary_collocate": null, "pronunciation": "shì chǎng", "ipa": "ʂʐ̩˥˩ ʈʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我每天早上去市场买菜。", "target_word": "市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场里有很多卖水果的人。", "target_word": "市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末，市场里特别热闹。", "target_word": "市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在市场买了一条鱼。", "target_word": "市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个市场离我家很近。", "target_word": "市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在市场上给孩子买玩具。", "target_word": "市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场里的东西很便宜。", "target_word": "市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，市场里人不多。", "target_word": "市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去市场看看有没有新鲜的菜。", "target_word": "市场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个市场早上六点就开门了。", "target_word": "市场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "市場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人们买卖东西的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b72803e1-d339-466f-98b7-61dea376201f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21614, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "市场", "is_correct": true, "explanation": "正确：“市场”指人们买卖东西的地方。"}, {"text": "市长", "is_correct": false, "explanation": "shì zhǎng 与 shì chǎng 只有声母不同（zh 与 ch），意思是城市的行政首长，不是买卖的地方。"}, {"text": "时常", "is_correct": false, "explanation": "shí cháng 的两个音节声调都与 shì chǎng 不同（第二声），意思是经常。"}, {"text": "四场", "is_correct": false, "explanation": "sì chǎng 与 shì chǎng 只有声母不同（s 与 sh），意思是四场（比赛）。"}], "explanations": {"市场": "正确：“市场”指人们买卖东西的地方。", "市长": "shì zhǎng 与 shì chǎng 只有声母不同（zh 与 ch），意思是城市的行政首长，不是买卖的地方。", "时常": "shí cháng 的两个音节声调都与 shì chǎng 不同（第二声），意思是经常。", "四场": "sì chǎng 与 shì chǎng 只有声母不同（s 与 sh），意思是四场（比赛）。"}, "sentence_index": null, "correct_answer": "市场"}, "level_3": {"options": [{"text": "市场", "is_correct": true, "explanation": "正确：“市场”指买卖东西的地方，早上去那里买菜很自然。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不卖菜，与“买菜”的语境不合。"}, {"text": "价格", "is_correct": false, "explanation": "配价：“去”后要接处所名词，“价格”不是处所。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园不是买菜的地方，与句子的意思不合。"}], "explanations": {"市场": "正确：“市场”指买卖东西的地方，早上去那里买菜很自然。", "医院": "语义：医院不卖菜，与“买菜”的语境不合。", "价格": "配价：“去”后要接处所名词，“价格”不是处所。", "公园": "语义：公园不是买菜的地方，与句子的意思不合。"}, "sentence_index": 0, "correct_answer": "市场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上去市场看病。", "explanation": "这里应该用〈医院〉。“看病”要去医院，“市场”是买卖东西的地方，不是看病的场所。"}, {"text": "周末我们去市场玩滑梯。", "explanation": "这里应该用〈游乐场〉。“市场”是买卖东西的地方，不是玩滑梯的场所。"}, {"text": "我家住在市场，很方便。", "explanation": "这里应该用〈市区〉。“市场”指买卖东西的地方，不是居住的区域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21614, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市场", "is_correct": true, "explanation": "正确：“市场”指买卖东西的地方，句子说那里的东西便宜。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不是买卖东西的地方，与“东西很便宜”的语境冲突。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“便宜”不能用来形容“天空”。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛不是存放或出售东西的地方，与句子的意思不合。"}], "explanations": {"市场": "正确：“市场”指买卖东西的地方，句子说那里的东西便宜。", "教室": "语义：教室不是买卖东西的地方，与“东西很便宜”的语境冲突。", "天空": "搭配：“便宜”不能用来形容“天空”。", "眼睛": "语义：眼睛不是存放或出售东西的地方，与句子的意思不合。"}, "sentence_index": 6, "correct_answer": "市场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家市场早上六点就开工了。", "explanation": "这里应该用〈工厂〉。“开工”多用于工厂、工地，“市场”应说“开门”或“营业”。"}, {"text": "我每个月都去市场取钱。", "explanation": "这里应该用〈银行〉。“取钱”要去银行，“市场”是买卖东西的地方，不是取钱的场所。"}, {"text": "同学们每天在市场里上课。", "explanation": "这里应该用〈教室〉。“上课”要在教室，“市场”是买卖东西的地方，不是上课的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21614, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小区门口新开了一条市场。", "corrected_sentence": "我们小区门口新开了一个市场。", "error_description": "错误形式：“一条市场”。正确形式：“一个市场”。“条”多用于细长的物件，“市场”的量词应为“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21614, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我市场买了一些菜。", "corrected_sentence": "我在市场买了一些菜。", "error_description": "漏掉介词：“市场”作处所状语时要用介词“在”引出，应为“在市场买了一些菜”，不能直接说“我市场买了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21616, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "圆", "is_correct": true, "explanation": "正确：圆与方相对，指形状是圆形，是「方」的反义词。"}, {"text": "大", "is_correct": false, "explanation": "大指体积或范围，与方、圆的形状对立无关。"}, {"text": "长", "is_correct": false, "explanation": "长指长度，不是「方」的反义词。"}, {"text": "尖", "is_correct": false, "explanation": "尖指末端细窄，与方形无关。"}], "correct_answer": "圆", "explanations": {"圆": "正确：圆与方相对，指形状是圆形，是「方」的反义词。", "大": "大指体积或范围，与方、圆的形状对立无关。", "长": "长指长度，不是「方」的反义词。", "尖": "尖指末端细窄，与方形无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21616, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "圆", "is_correct": true, "explanation": "正确：圆与方相对，指形状是圆形，是「方」的反义词。"}, {"text": "软", "is_correct": false, "explanation": "软指质地，与形状的方、圆无关。"}, {"text": "厚", "is_correct": false, "explanation": "厚指厚度，与方形不构成反义。"}, {"text": "亮", "is_correct": false, "explanation": "亮指光线，与形状的方、圆无关。"}], "correct_answer": "圆", "explanations": {"圆": "正确：圆与方相对，指形状是圆形，是「方」的反义词。", "软": "软指质地，与形状的方、圆无关。", "厚": "厚指厚度，与方形不构成反义。", "亮": "亮指光线，与形状的方、圆无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21616, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "方是四个角一样大的形状。", "primary_collocate": null, "pronunciation": "fāng", "ipa": "faŋ˥", "syllable_count": 1, "sentences": [{"text": "这张桌子是方的，不是圆的。", "target_word": "方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要圆的盘子，还是方的盘子？", "target_word": "方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子是方的，很好放。", "target_word": "方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇窗是方的，那扇窗是圆的。", "target_word": "方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢圆的饼干，不喜欢方的。", "target_word": "方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "方的杯子不太好拿。", "target_word": "方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那块糖是方的，很小。", "target_word": "方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的饭桌是方的。", "target_word": "方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盘子不是圆的，是方的。", "target_word": "方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "方的蛋糕切起来很容易。", "target_word": "方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "方形", "label": "复合"}, {"form": "正方形", "label": "复合"}, {"form": "方桌", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词：形状四个角一样大，与“圆”相对（方的）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1de80df8-30f4-4a4d-832e-d5d2f03764c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21616, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "方", "is_correct": true, "explanation": "正确答案：方（fāng），形容四个角一样大的形状。"}, {"text": "房", "is_correct": false, "explanation": "fáng（第二声）与 fāng（第一声）声调不同，意思是房子。"}, {"text": "放", "is_correct": false, "explanation": "fàng（第四声）与 fāng（第一声）声调不同，意思是放置。"}, {"text": "仿", "is_correct": false, "explanation": "fǎng（第三声）与 fāng（第一声）声调不同，意思是模仿。"}], "explanations": {"方": "正确答案：方（fāng），形容四个角一样大的形状。", "房": "fáng（第二声）与 fāng（第一声）声调不同，意思是房子。", "放": "fàng（第四声）与 fāng（第一声）声调不同，意思是放置。", "仿": "fǎng（第三声）与 fāng（第一声）声调不同，意思是模仿。"}, "sentence_index": null, "correct_answer": "方"}, "level_3": {"options": [{"text": "方", "is_correct": true, "explanation": "正确：「这张桌子是方的」描述桌子的形状，与「圆的」相对。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：「甜」说味道，不能用来描述桌子。"}, {"text": "香", "is_correct": false, "explanation": "语义：「香」说气味，桌子不会是香的。"}, {"text": "烫", "is_correct": false, "explanation": "语义：「烫」说温度，与「不是圆的」所说的形状不相关。"}], "explanations": {"方": "正确：「这张桌子是方的」描述桌子的形状，与「圆的」相对。", "甜": "搭配：「甜」说味道，不能用来描述桌子。", "香": "语义：「香」说气味，桌子不会是香的。", "烫": "语义：「烫」说温度，与「不是圆的」所说的形状不相关。"}, "sentence_index": 0, "correct_answer": "方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这扇窗是方的，又是圆的。", "explanation": "〈方〉与〈圆〉相对，同一扇窗不能既方又圆。"}, {"text": "这扇窗方得圆圆的。", "explanation": "〈方〉与〈圆〉相对，「方得圆圆的」自相矛盾。"}, {"text": "这扇窗是方的，但它的四个角不一样大。", "explanation": "〈方〉指四个角一样大的形状，角不一样大就不是方的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21616, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "方", "is_correct": true, "explanation": "正确答案：方（fāng），形容四个角一样大的形状。"}, {"text": "防", "is_correct": false, "explanation": "fáng（第二声）与 fāng（第一声）声调不同，意思是防守。"}, {"text": "帮", "is_correct": false, "explanation": "bāng 与 fāng 声母不同（b 与 f），意思是帮助。"}, {"text": "访", "is_correct": false, "explanation": "fǎng（第三声）与 fāng（第一声）声调不同，意思是访问。"}], "explanations": {"方": "正确答案：方（fāng），形容四个角一样大的形状。", "防": "fáng（第二声）与 fāng（第一声）声调不同，意思是防守。", "帮": "bāng 与 fāng 声母不同（b 与 f），意思是帮助。", "访": "fǎng（第三声）与 fāng（第一声）声调不同，意思是访问。"}, "sentence_index": null, "correct_answer": "方"}, "level_3": {"options": [{"text": "方", "is_correct": true, "explanation": "正确：「那块糖是方的」描述糖的形状。"}, {"text": "大", "is_correct": false, "explanation": "语义：「大」与后文「很小」矛盾。"}, {"text": "满", "is_correct": false, "explanation": "搭配：糖不说「满」，「满」不用于描述糖的形状。"}, {"text": "高", "is_correct": false, "explanation": "语义：「高」与后文「很小」矛盾。"}], "explanations": {"方": "正确：「那块糖是方的」描述糖的形状。", "大": "语义：「大」与后文「很小」矛盾。", "满": "搭配：糖不说「满」，「满」不用于描述糖的形状。", "高": "语义：「高」与后文「很小」矛盾。"}, "sentence_index": 6, "correct_answer": "方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕是方的，又是圆的。", "explanation": "〈方〉与〈圆〉相对，同一块蛋糕不能既方又圆。"}, {"text": "这块蛋糕方得圆圆的。", "explanation": "〈方〉与〈圆〉相对，「方得圆圆的」自相矛盾。"}, {"text": "这块蛋糕是方的，但它的四个角不一样大。", "explanation": "〈方〉指四个角一样大的形状，角不一样大就不是方的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地毯是的方。", "corrected_sentence": "这块地毯是方的。", "error_description": "「方」作形容词谓语时要说「方的」，不能说「的方」。错误：的方；正确：方的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那张纸是方。", "corrected_sentence": "那张纸是方的。", "error_description": "「方」说形状作谓语时要用「是方的」，不能只说「是方」。错误：是方；正确：是方的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
