INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21618, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指东西从下到上的距离。", "primary_collocate": null, "pronunciation": "gāo dù", "ipa": "kɑʊ˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这座山的高度是三千米。", "target_word": "高度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞到了一万米的高度。", "target_word": "高度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子的高度正好，孩子坐着很舒服。", "target_word": "高度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请量一下这棵树的高度。", "target_word": "高度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋楼的高度有一百米，顶层的风很大。", "target_word": "高度", "complexity_tier": "T3", "furigana": "gāo dù", "sentence_source": "generated"}, {"text": "这座塔的高度有五十米。", "target_word": "高度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跳起来的高度超过了一米。", "target_word": "高度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们站在不同的高度看这座城市。", "target_word": "高度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面墙的高度是两米，小孩爬不上去。", "target_word": "高度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架的高度不够，放不下大书。", "target_word": "高度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高度计", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体从下到上的距离，如山、楼、桌子的高度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ebcdd33-4c2b-4870-aa27-7ac3753dba86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21618, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高度", "is_correct": true, "explanation": "正确答案：高度，指物体从下到上的距离。"}, {"text": "高地", "is_correct": false, "explanation": "dì（第四声）与 dù（第四声）韵母不同（i 与 u），意思是地势高的地面。"}, {"text": "高低", "is_correct": false, "explanation": "dī（第一声）与 dù（第四声）韵母与声调都不同，意思是高和低。"}, {"text": "国度", "is_correct": false, "explanation": "guó（第二声）与 gāo（第一声）韵母与声调都不同，意思是国家。"}, {"text": "高毒", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）声调不同，意思是毒性很强。"}], "explanations": {"高度": "正确答案：高度，指物体从下到上的距离。", "高地": "dì（第四声）与 dù（第四声）韵母不同（i 与 u），意思是地势高的地面。", "高低": "dī（第一声）与 dù（第四声）韵母与声调都不同，意思是高和低。", "国度": "guó（第二声）与 gāo（第一声）韵母与声调都不同，意思是国家。", "高毒": "dú（第二声）与 dù（第四声）声调不同，意思是毒性很强。"}, "sentence_index": null, "correct_answer": "高度"}, "level_3": {"options": [{"text": "高度", "is_correct": true, "explanation": "正确：“高度”指从下到上的距离，与“三千米”相符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热程度，不能用“三千米”来表示。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”说的是运动的快慢，不说山的速度。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”用“元”来计算，不能用“三千米”来表示。"}], "explanations": {"高度": "正确：“高度”指从下到上的距离，与“三千米”相符。", "温度": "语义：“温度”指冷热程度，不能用“三千米”来表示。", "速度": "搭配：“速度”说的是运动的快慢，不说山的速度。", "价格": "搭配：“价格”用“元”来计算，不能用“三千米”来表示。"}, "sentence_index": 0, "correct_answer": "高度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这口井的高度有十米。", "explanation": "这里应该用〈深度〉。高度是从下往上的距离，井是从上往下量的，要说深度。"}, {"text": "这条路的高度是十公里。", "explanation": "这里应该用〈长度〉。高度指竖直方向的距离，道路是横向延伸的，要说长度。"}, {"text": "这袋面粉的高度是五十斤。", "explanation": "这里应该用〈重量〉。高度指竖向距离，不能用斤计量，应说重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21618, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "高度", "is_correct": true, "explanation": "正确答案：高度，指物体从下到上的距离。"}, {"text": "过度", "is_correct": false, "explanation": "guò（第四声）与 gāo（第一声）韵母与声调都不同，意思是超过适当的程度。"}, {"text": "高徒", "is_correct": false, "explanation": "tú（第二声）与 dù（第四声）声母与声调不同，意思是优秀的学生。"}, {"text": "高速", "is_correct": false, "explanation": "sù（第四声）与 dù（第四声）声母不同（s 与 d），意思是速度快。"}], "explanations": {"高度": "正确答案：高度，指物体从下到上的距离。", "过度": "guò（第四声）与 gāo（第一声）韵母与声调都不同，意思是超过适当的程度。", "高徒": "tú（第二声）与 dù（第四声）声母与声调不同，意思是优秀的学生。", "高速": "sù（第四声）与 dù（第四声）声母不同（s 与 d），意思是速度快。"}, "sentence_index": null, "correct_answer": "高度"}, "level_3": {"options": [{"text": "高度", "is_correct": true, "explanation": "正确：“高度”指跳起后离地的距离，与“超过一米”相符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”以千克计算，不能说超过一米。"}, {"text": "形貌", "is_correct": false, "explanation": "语域：“形貌”偏书面，指外形，不能用来描述跳起的距离。"}, {"text": "力量", "is_correct": false, "explanation": "语义：“力量”指力的大小，不能用“超过一米”来计量。"}], "explanations": {"高度": "正确：“高度”指跳起后离地的距离，与“超过一米”相符。", "体重": "搭配：“体重”以千克计算，不能说超过一米。", "形貌": "语域：“形貌”偏书面，指外形，不能用来描述跳起的距离。", "力量": "语义：“力量”指力的大小，不能用“超过一米”来计量。"}, "sentence_index": 6, "correct_answer": "高度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的高度是红色。", "explanation": "这里应该用〈颜色〉。高度指从下到上的距离，红色是颜色，不能说衣服的高度是红色。"}, {"text": "这个角的高度是九十度。", "explanation": "这里应该用〈角度〉。角的大小用角度表示，高度是竖向距离，不能用于角。"}, {"text": "今天的高度是三十度。", "explanation": "这里应该用〈温度〉。高度指物体从下到上的距离，说气温要用温度，不能说“今天的高度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座灯塔很高度。", "corrected_sentence": "这座灯塔很高。", "error_description": "“高度”是名词，不能被副词“很”修饰；形容灯塔的高，应说“很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子的高度是三个，很通风。", "corrected_sentence": "这间屋子的高度是三米，很通风。", "error_description": "“高度”的数值要用长度单位，应写作“三米”；“三个”是个体量词，不能表示高度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
