INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21620, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西露出来让人看见了。", "primary_collocate": null, "pronunciation": "chéng xiàn chū", "ipa": "tʂʰɤŋ˧˥ ɕjɛn˥˩ tʂʰu˥", "syllable_count": 3, "sentences": [{"text": "雨后的山呈现出一片绿色。", "target_word": "呈现出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片呈现出老城的样子。", "target_word": "呈现出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，树叶呈现出红色和黄色。", "target_word": "呈现出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水在阳光下呈现出蓝色。", "target_word": "呈现出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市呈现出新的面貌。", "target_word": "呈现出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脸上呈现出高兴的样子。", "target_word": "呈现出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些数据呈现出上升的趋势。", "target_word": "呈现出", "complexity_tier": "T3", "furigana": "zhèxiē shùjù chéngxiàn chū shàngshēng de qūshì。", "sentence_source": "generated"}, {"text": "傍晚的天空呈现出美丽的颜色。", "target_word": "呈现出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画呈现出冬天的安静。", "target_word": "呈现出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的作品呈现出不同的想法。", "target_word": "呈现出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "呈现", "label": "复合"}, {"form": "呈现着", "label": "体标"}, {"form": "呈现出来", "label": "复合"}], "register": "中性", "sense_fingerprint": "呈现出：事物显出某种样子、颜色或面貌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8c9982-2261-4a26-bafc-a41b87d5771d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呈现出", "is_correct": true, "explanation": "呈现出指事物显出某种样子，符合「山呈现出一片绿色」。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：「打碎」的对象是有形的物体，山不能打碎一片绿色。"}, {"text": "赠送", "is_correct": false, "explanation": "配价：「赠送」需要接受者（如「赠送给某人」），后面不能直接接颜色。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：「绿色」不能被吃掉，句意不通。"}], "explanations": {"呈现出": "呈现出指事物显出某种样子，符合「山呈现出一片绿色」。", "打碎": "语义：「打碎」的对象是有形的物体，山不能打碎一片绿色。", "赠送": "配价：「赠送」需要接受者（如「赠送给某人」），后面不能直接接颜色。", "吃掉": "语义：「绿色」不能被吃掉，句意不通。"}, "sentence_index": 0, "correct_answer": "呈现出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我弟弟今天呈现出很多作业。", "explanation": "这里应该用〈写〉。呈现出指显出样子，不能用来指做作业，应该说「写作业」。"}, {"text": "汽车呈现出很大的噪音。", "explanation": "这里应该用〈发出〉。呈现出指视觉上显出的样子，声音应该用〈发出〉。"}, {"text": "他一天呈现出三次电话。", "explanation": "这里应该用〈打〉。呈现出指显出样子，不能用来指打电话，应该说「打电话」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呈现出", "is_correct": true, "explanation": "呈现出指数据显出某种趋势，符合「呈现出上升的趋势」。"}, {"text": "咬断", "is_correct": false, "explanation": "语义：「咬断」用于绳索等有形之物，趋势不能被咬断。"}, {"text": "掀开", "is_correct": false, "explanation": "语义：「掀开」用于遮盖之物，趋势不能被掀开。"}, {"text": "寄给", "is_correct": false, "explanation": "配价：「寄给」需要收件人，「上升的趋势」不能充当收件人。"}], "explanations": {"呈现出": "呈现出指数据显出某种趋势，符合「呈现出上升的趋势」。", "咬断": "语义：「咬断」用于绳索等有形之物，趋势不能被咬断。", "掀开": "语义：「掀开」用于遮盖之物，趋势不能被掀开。", "寄给": "配价：「寄给」需要收件人，「上升的趋势」不能充当收件人。"}, "sentence_index": 6, "correct_answer": "呈现出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天呈现出生病的爸爸。", "explanation": "这里应该用〈照顾〉。呈现出指事物显出样子，不能用来指照料生病的人。"}, {"text": "我们队呈现出了对手。", "explanation": "这里应该用〈战胜〉。呈现出指显出样子，不能用来指打败对手。"}, {"text": "他呈现出了纪录。", "explanation": "这里应该用〈打破〉。呈现出不能与纪录搭配，应该说「打破纪录」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "远处的雪山呈现了出淡淡的紫色。", "corrected_sentence": "远处的雪山呈现出淡淡的紫色。", "error_description": "错误形式是「呈现了出」，「了」插在「现」和「出」之间，把「呈现出」拆开了。正确形式是「呈现出」；若要表示完成，「了」应放在「出」后面，说「呈现出了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张表格很呈现出一个明显的变化。", "corrected_sentence": "这张表格呈现出一个明显的变化。", "error_description": "错误形式是「很呈现出」，正确形式是「呈现出」。「很」一般修饰形容词或部分心理动词（如「很喜欢」），不能修饰「呈现出」这类表示显现的动词，应删去「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
