INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21622, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21622, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公司把产品卖给很多不同的地方或商店。", "primary_collocate": null, "pronunciation": "fēn xiāo", "ipa": "fən˥ ɕiɑʊ˥", "syllable_count": 2, "sentences": [{"text": "这家公司把新产品分销到全国各地。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的茶叶主要靠经销商分销。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂做好饮料以后，交给公司分销。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子的牛奶在南方由一家公司分销。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们负责把水果分销给各个超市。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定把手机分销到更多的城市。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司不自己做面包，只负责分销。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药在海外是怎么分销的？", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们已经分销了三万箱啤酒。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新书由三家公司分销，书店很快就能买到。", "target_word": "分销", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分销商", "label": "复合词"}, {"form": "分銷", "label": "繁体"}], "register": "中性", "sense_fingerprint": "公司把产品通过中间环节卖到许多地方或商店", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1de80df8-30f4-4a4d-832e-d5d2f03764c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产", "is_correct": false, "explanation": "语义：“生产”指制造物品，不能说“把新产品生产到全国各地”，与“到全国各地”的语境不合。"}, {"text": "分销", "is_correct": true, "explanation": "“分销”指经中间商把产品卖到各地，与“把新产品……到全国各地”的语境相符。"}, {"text": "研发", "is_correct": false, "explanation": "配价：“研发”不带“到……地方”的补语，“把新产品研发到全国各地”不通。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：“包装”指给产品加外包装，不能带“到全国各地”这样的地点补语。"}], "explanations": {"生产": "语义：“生产”指制造物品，不能说“把新产品生产到全国各地”，与“到全国各地”的语境不合。", "分销": "“分销”指经中间商把产品卖到各地，与“把新产品……到全国各地”的语境相符。", "研发": "配价：“研发”不带“到……地方”的补语，“把新产品研发到全国各地”不通。", "包装": "搭配：“包装”指给产品加外包装，不能带“到全国各地”这样的地点补语。"}, "sentence_index": 0, "correct_answer": "分销"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家食品厂分销自己生产的饼干，顾客可以直接到厂里买。", "explanation": "这里应该用〈直销〉。分销要经过中间商，顾客直接到厂里买，是厂家直接卖给消费者，应说直销。"}, {"text": "我每天在学校门口分销烤红薯，学生都是直接买。", "explanation": "这里应该用〈销售〉。分销面向中间商；在门口直接卖给学生，应说销售。"}, {"text": "她每天在小区里分销化妆品，逐户敲门。", "explanation": "这里应该用〈推销〉。分销要借助中间商；逐户敲门上门卖是直接推销，应说推销。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”就是自己做面包，与“不自己做面包”相矛盾，“只负责烘焙”不通。"}, {"text": "分销", "is_correct": true, "explanation": "“分销”指经中间商销售，与“只负责”搭配，表示小店只做销售环节，与前半句的语境一致。"}, {"text": "制作", "is_correct": false, "explanation": "语义：“制作”同样指做东西，与“不自己做面包”矛盾，“只负责制作”不通。"}, {"text": "生产", "is_correct": false, "explanation": "语义：“生产”就是制造面包，与“不自己做面包”矛盾，“只负责生产”不通。"}], "explanations": {"烘焙": "语义：“烘焙”就是自己做面包，与“不自己做面包”相矛盾，“只负责烘焙”不通。", "分销": "“分销”指经中间商销售，与“只负责”搭配，表示小店只做销售环节，与前半句的语境一致。", "制作": "语义：“制作”同样指做东西，与“不自己做面包”矛盾，“只负责制作”不通。", "生产": "语义：“生产”就是制造面包，与“不自己做面包”矛盾，“只负责生产”不通。"}, "sentence_index": 6, "correct_answer": "分销"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家超市每天分销两百斤大米，都是卖给路过的居民。", "explanation": "这里应该用〈零售〉。分销要把货交给中间商，超市直接卖给路过的居民应说零售。"}, {"text": "这家连锁品牌的门店都是分销的，由总部自己管理，不找加盟商。", "explanation": "这里应该用〈直营〉。分销要交给中间商，门店由总部自己管理、不找加盟商，应说直营。"}, {"text": "快递员每天分销包裹到各家各户。", "explanation": "这里应该用〈派送〉。分销要经过中间商，快递员把包裹送到各家各户应说派送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家厂商把牛奶分销从南方各省。", "corrected_sentence": "这家厂商把牛奶分销到南方各省。", "error_description": "错误在“分销”的地点补语：表示去往的地点应用介词“到”，不能用表示起点的“从”；“分销从南方各省”不通，应改为“到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家厂商把茶叶分销各地的零售商。", "corrected_sentence": "这家厂商把茶叶分销给各地的零售商。", "error_description": "错误在“分销”后面表示对象的“给”被省略了。应说“分销给各地的零售商”，去掉“给”后句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
