INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21626, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "普通的广大民众，社会上的许多人。", "primary_collocate": null, "pronunciation": "dà zhòng", "ipa": "ta˥˩ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这家餐厅的价格大众都能接受。", "target_word": "大众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影很受大众欢迎。", "target_word": "大众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一种大众喜爱的运动。", "target_word": "大众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写得简单，适合大众阅读。", "target_word": "大众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸要为大众说真话。", "target_word": "大众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁是大众常用的交通工具。", "target_word": "大众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生向大众介绍了健康的生活方式。", "target_word": "大众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的歌听起来很亲切，大众都爱听。", "target_word": "大众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店的东西很便宜，大众都买得起。", "target_word": "大众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大众的看法会影响电影的票房。", "target_word": "大众", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大众化", "label": "复合"}, {"form": "大众传媒", "label": "复合"}], "register": "中性", "sense_fingerprint": "指普通的广大民众、社会上的许多人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33c7f637-619d-49ba-80ef-a53edb7b3254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21626, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大众", "is_correct": true, "explanation": "正确。大众（dà zhòng）指普通的广大民众，是目标词。"}, {"text": "大钟", "is_correct": false, "explanation": "zhōng（第一声）与 zhòng（第四声）声调不同，第二音节不同，意思是大钟。"}, {"text": "打中", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）声调不同，第一音节不同，意思是击中。"}, {"text": "打钟", "is_correct": false, "explanation": "两个音节声调都与目标不同，dǎ zhōng 意思是敲钟。"}], "explanations": {"大众": "正确。大众（dà zhòng）指普通的广大民众，是目标词。", "大钟": "zhōng（第一声）与 zhòng（第四声）声调不同，第二音节不同，意思是大钟。", "打中": "dǎ（第三声）与 dà（第四声）声调不同，第一音节不同，意思是击中。", "打钟": "两个音节声调都与目标不同，dǎ zhōng 意思是敲钟。"}, "sentence_index": null, "correct_answer": "大众"}, "level_3": {"options": [{"text": "大众", "is_correct": true, "explanation": "正确。“这家餐厅的价格大众都能接受”中，“大众”指广大民众，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能“接受”价格，句子意思不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“接受价格”的主语应是人，天气不能接受价格。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能接受价格，句意荒谬。"}], "explanations": {"大众": "正确。“这家餐厅的价格大众都能接受”中，“大众”指广大民众，符合句意。", "桌子": "语义：桌子不能“接受”价格，句子意思不通。", "天气": "语义：“接受价格”的主语应是人，天气不能接受价格。", "石头": "语义：石头不能接受价格，句意荒谬。"}, "sentence_index": 0, "correct_answer": "大众"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛的大众坐满了整个体育馆。", "explanation": "这里应该用〈观众〉。大众指一般民众，不指特定场合观看比赛的人。"}, {"text": "我的大众都来了，我们一起吃饭。", "explanation": "这里应该用〈朋友们〉。大众指社会上的普通民众，不用于指自己的朋友。"}, {"text": "这个班的大众都很认真，老师很满意。", "explanation": "这里应该用〈同学〉。大众指社会上的普通人，不用于指同一班的同学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21626, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大众", "is_correct": true, "explanation": "正确。“医生向大众介绍了健康的生活方式”中，“大众”指广大民众，是介绍的对象。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“介绍”需要能接受内容的对象，桌子不能接受介绍，句子不成立。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不能接受健康生活方式的介绍，句意荒谬。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：衣服不能听医生介绍，句子意思不通。"}], "explanations": {"大众": "正确。“医生向大众介绍了健康的生活方式”中，“大众”指广大民众，是介绍的对象。", "桌子": "配价：“介绍”需要能接受内容的对象，桌子不能接受介绍，句子不成立。", "垃圾": "语义：垃圾不能接受健康生活方式的介绍，句意荒谬。", "衣服": "语义：衣服不能听医生介绍，句子意思不通。"}, "sentence_index": 6, "correct_answer": "大众"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大众，你们快进来吧。", "explanation": "这里应该用〈大家〉作称呼。大众是指广大民众的名词，不直接用于称呼别人。"}, {"text": "这个孩子很大众，喜欢一个人玩。", "explanation": "这里应该用〈独立〉或〈孤僻〉。大众一般修饰事物（如大众文化），不用来形容人的性格。"}, {"text": "这个大众很有钱，买了好几栋房子。", "explanation": "这里应该用〈有人〉或〈某人〉。大众是集合名词，不能指某一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21626, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个电视节目很受一个大众喜爱。", "corrected_sentence": "这个电视节目很受大众喜爱。", "error_description": "量词错误：“大众”是集合名词，指广大民众，前面不能直接加“一个”。应去掉“一个”，说“很受大众喜爱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21626, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小区的公园很干净，大众们都很喜欢。", "corrected_sentence": "这个小区的公园很干净，大众都很喜欢。", "error_description": "“大众”本身已是集合概念，指广大民众，后面再加复数词尾“们”属于冗余，应去掉“们”，说“大众都很喜欢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
