INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21628, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一样的东西变得不一样了。", "primary_collocate": null, "pronunciation": "fēn huà", "ipa": "fən˥ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "同样的学生，几年后开始分化。", "target_word": "分化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贫富差距让社会慢慢分化。", "target_word": "分化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的居民收入越来越分化。", "target_word": "分化", "complexity_tier": "T3", "furigana": "zhè ge chéngshì de jūmín shōurù yuèlái yuè fēnhuà。", "sentence_source": "generated"}, {"text": "这种细胞会分化成不同的组织。", "target_word": "分化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场分化了，有人赚钱，有人亏钱。", "target_word": "分化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业十年后，同学们的生活分化得很大。", "target_word": "分化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一个家族后来分化成两个派别。", "target_word": "分化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的想法开始分化，没法一致。", "target_word": "分化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师担心班里的成绩会分化。", "target_word": "分化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行业正在分化，大公司越来越强。", "target_word": "分化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分化了", "label": "体标"}, {"form": "分化着", "label": "体标"}, {"form": "分化过", "label": "体标"}, {"form": "两极分化", "label": "复合"}], "register": "书面", "sense_fingerprint": "原本相同或相近的事物逐渐变得不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26dbc4a2-a243-4c22-9f23-9c2db77eb70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21628, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分化", "is_correct": true, "explanation": "正确：分化（fēn huà）指原本相同的事物逐渐变得不同。"}, {"text": "焚化", "is_correct": false, "explanation": "fén（第二声）与 fēn（第一声）声调不同，焚化意思是烧成灰。"}, {"text": "粉画", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，粉画意思是用粉末颜料画的画。"}, {"text": "风化", "is_correct": false, "explanation": "fēng 与 fēn 韵母不同，风化意思是岩石等受风雨侵蚀而逐渐破碎。"}], "explanations": {"分化": "正确：分化（fēn huà）指原本相同的事物逐渐变得不同。", "焚化": "fén（第二声）与 fēn（第一声）声调不同，焚化意思是烧成灰。", "粉画": "fěn（第三声）与 fēn（第一声）声调不同，粉画意思是用粉末颜料画的画。", "风化": "fēng 与 fēn 韵母不同，风化意思是岩石等受风雨侵蚀而逐渐破碎。"}, "sentence_index": null, "correct_answer": "分化"}, "level_3": {"options": [{"text": "分化", "is_correct": true, "explanation": "正确：“分化”指原本相同的学生逐渐变得不同，与“同样的”和“几年后”相合。"}, {"text": "降低", "is_correct": false, "explanation": "语义：“降低”说数量或水平下降，不能说学生“降低”，与“同样的学生”的语境不合。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指冰雪等受热变成水，不能用于学生。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”指植物长出芽，不能用于学生。"}], "explanations": {"分化": "正确：“分化”指原本相同的学生逐渐变得不同，与“同样的”和“几年后”相合。", "降低": "语义：“降低”说数量或水平下降，不能说学生“降低”，与“同样的学生”的语境不合。", "融化": "语义：“融化”指冰雪等受热变成水，不能用于学生。", "发芽": "语义：“发芽”指植物长出芽，不能用于学生。"}, "sentence_index": 0, "correct_answer": "分化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块饼干分化成了两半。", "explanation": "这里应该用〈分裂〉。分化指原本相同的事物逐渐变得不同，把一整块东西切成两半要用分裂。"}, {"text": "今天的天气分化了。", "explanation": "这里应该用〈变化〉。分化强调原本相同的事物分开、变得不同，天气的冷暖变化不是这种过程。"}, {"text": "两人在车站分化了。", "explanation": "这里应该用〈分开〉。分化不表示人在空间上的分离，两人离开车站要用分开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21628, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分化", "is_correct": true, "explanation": "正确：“分化”指同一家族内部逐渐分成不同的派别，与句意相合。"}, {"text": "合并", "is_correct": false, "explanation": "语义：“合并”指合为一体，与“分成两个派别”的结果相反。"}, {"text": "繁殖", "is_correct": false, "explanation": "搭配：“繁殖”多指生物数量增多，不能说家族繁殖成派别。"}, {"text": "联合", "is_correct": false, "explanation": "语义：“联合”指多方结合在一起，与句中分成派别的意思相反。"}], "explanations": {"分化": "正确：“分化”指同一家族内部逐渐分成不同的派别，与句意相合。", "合并": "语义：“合并”指合为一体，与“分成两个派别”的结果相反。", "繁殖": "搭配：“繁殖”多指生物数量增多，不能说家族繁殖成派别。", "联合": "语义：“联合”指多方结合在一起，与句中分成派别的意思相反。"}, "sentence_index": 6, "correct_answer": "分化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板把奖金分化了，分给每个员工。", "explanation": "这里应该用〈分配〉。分化指原本相同的事物逐渐变得不同，把奖金分给大家要用分配。"}, {"text": "这杯牛奶和咖啡分化了。", "explanation": "这里应该用〈融合〉。分化指原本相同的事物逐渐变得不同，牛奶和咖啡混在一起要用融合。"}, {"text": "冰块在热水里分化了。", "explanation": "这里应该用〈融化〉。分化不用于物质受热变成液体的变化，冰块变成水要用融化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21628, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种语言经过千年，分化给了不同的方言。", "corrected_sentence": "这种语言经过千年，分化成了不同的方言。", "error_description": "错误形式：“分化给”；正确形式：“分化成”。“分化”后应接补语“成”，表示变成不同的样子；“给”表示给予，与句意不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21628, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两派的观点分化成很厉害。", "corrected_sentence": "这两派的观点分化得很厉害。", "error_description": "错误形式：“分化成很厉害”；正确形式：“分化得很厉害”。“成”要接名词性结果（如“分化成两派”），不能接程度补语；程度补语应用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
