INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21630, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西用纸或盒子包起来。", "primary_collocate": null, "pronunciation": "bāo zhuāng", "ipa": "pɑʊ̯˥ ʈʂwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "请帮我把这个礼物包装一下。", "target_word": "包装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在包装生日礼物。", "target_word": "包装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员用红纸把花包装好了。", "target_word": "包装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些水果要先包装，再送出去。", "target_word": "包装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会包装礼物吗？", "target_word": "包装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把盒子包装得很漂亮。", "target_word": "包装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板让我们明天早上包装这些杯子。", "target_word": "包装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这个盒子包装起来。", "target_word": "包装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他包装了十份水果。", "target_word": "包装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店可以免费帮你包装。", "target_word": "包装", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "包装纸", "label": "复合"}, {"form": "包装盒", "label": "复合"}, {"form": "包装袋", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词，用纸、盒子等把东西包好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f511cdf7-32fc-4ebd-97bd-19cfb744bda7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包装", "is_correct": true, "explanation": "正确：“包装”指用纸或盒子把礼物包起来，与“请帮我把这个礼物……一下”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能用于礼物。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是用火毁坏，与“请帮我”的请求意思相反。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料，不能用于礼物。"}], "explanations": {"包装": "正确：“包装”指用纸或盒子把礼物包起来，与“请帮我把这个礼物……一下”的语境相符。", "吃": "搭配：“吃”的对象是食物，不能用于礼物。", "烧": "语义：“烧”是用火毁坏，与“请帮我”的请求意思相反。", "喝": "搭配：“喝”的对象是饮料，不能用于礼物。"}, "sentence_index": 0, "correct_answer": "包装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把衣服包装进行李箱。", "explanation": "这里应该用〈装〉。包装指用纸或盒子把东西包起来，把衣服放进行李箱要用〈装〉。"}, {"text": "妈妈每天用吸尘器包装地板。", "explanation": "这里应该用〈吸〉。包装指用纸或盒子把东西包起来，用吸尘器清理地板要用〈吸〉。"}, {"text": "医生正在包装伤口。", "explanation": "这里应该用〈包扎〉。包装用于商品或礼物，包扎用于伤口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包装", "is_correct": true, "explanation": "正确：“包装”指用纸或盒子把东西包起来，与“老板让我们明天早上……这些杯子”的工作安排相符。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”是把杯子毁坏，老板不会要求员工这样做。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”表示用力击打或毁坏，与“老板让我们”的工作安排不符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”用于食物或液体，不能用于杯子。"}], "explanations": {"包装": "正确：“包装”指用纸或盒子把东西包起来，与“老板让我们明天早上……这些杯子”的工作安排相符。", "打碎": "语义：“打碎”是把杯子毁坏，老板不会要求员工这样做。", "砸": "语义：“砸”表示用力击打或毁坏，与“老板让我们”的工作安排不符。", "煮": "搭配：“煮”用于食物或液体，不能用于杯子。"}, "sentence_index": 6, "correct_answer": "包装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我帮你包装房间。", "explanation": "这里应该用〈收拾〉。包装指用纸或盒子把东西包起来，整理房间要用〈收拾〉。"}, {"text": "我每天早上包装牙齿。", "explanation": "这里应该用〈刷〉。包装指用纸或盒子把东西包起来，刷牙要用〈刷〉。"}, {"text": "周末我们包装教室。", "explanation": "这里应该用〈打扫〉。包装指用纸或盒子把东西包起来，打扫教室要用〈打扫〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个礼物我帮你包装了好。", "corrected_sentence": "这个礼物我帮你包装好了。", "error_description": "错误：结果补语“好”应紧跟动词“包装”，“了”放在补语之后。正确：“包装好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐把生日蛋糕包装很精致。", "corrected_sentence": "姐姐把生日蛋糕包装得很精致。", "error_description": "错误：程度补语的标记“得”漏掉了，动词后应加“得”。正确：“包装得很精致”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
