INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21636, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "卖咖啡和点心的地方。", "primary_collocate": null, "pronunciation": "kā fēi diàn", "ipa": "kʰa˥ feɪ˥ tiɛn˥˩", "syllable_count": 3, "sentences": [{"text": "那家咖啡店卖咖啡和点心。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在咖啡店点了一块蛋糕。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡店里有咖啡，也有小饼干。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班后，我们去咖啡店坐坐。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡店的点心很甜。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口新开了一家咖啡店。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢在安静的咖啡店写作业。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡店的服务员给我们送来了茶。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请朋友去咖啡店吃点心。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡店离地铁站不远。", "target_word": "咖啡店", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "咖啡店老板", "label": "复合词"}], "register": "通用", "sense_fingerprint": "咖啡店：卖咖啡和点心、可以坐下来的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d8d8829-6187-4938-b5a2-6292d29cf1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors